export enum PlayerCategory {
  Batsman = "Batsman",
  Bowler = "Bowler",
  AllRounder = "All-Rounder",
  Wicketkeeper = "Wicketkeeper",
}

export interface PlayerRole {
    id?: string;
    name: string;
    basePrice: number; // Default base price for this role
}

export interface Player {
  id: number | string;
  name: string;
  photoUrl: string;
  category: string; // Auction Category (Group: MVP, Set 1, Uncapped)
  role: string;     // Player Type (Skill: Batsman, Bowler)
  basePrice: number;
  nationality: string;
  speciality: string; // Kept for backward compat, usually same as role
  stats: {
    matches: number;
    runs: number;
    wickets: number;
  };
  status?: 'SOLD' | 'UNSOLD';
  soldPrice?: number;
  soldTo?: string;
}

export interface RegisteredPlayer {
    id: string;
    fullName: string;
    mobile: string;
    playerType: string;
    gender: string;
    dob: string;
    profilePic: string;
    paymentScreenshot: string;
    status: 'PENDING' | 'APPROVED' | 'REJECTED';
    submittedAt: number;
    [key: string]: any; // For custom fields
}

export interface Team {
  id: number | string;
  name: string;
  shortName?: string;
  owner: string;
  logoUrl: string;
  budget: number;
  players: Player[];
  minPlayers?: number;
  maxPlayers?: number;
  password?: string; // Added password for team login
}

export interface Bid {
  teamId: number | string;
  amount: number;
}

export enum AuctionStatus {
  NotStarted = "NOT_STARTED",
  InProgress = "IN_PROGRESS",
  Paused = "PAUSED",
  Sold = "SOLD",
  Unsold = "UNSOLD",
  Finished = "FINISHED",
}

export interface AuctionLog {
  message: string;
  timestamp: number;
  type: 'SYSTEM' | 'BID' | 'SOLD' | 'UNSOLD';
}

export interface BidIncrementSlab {
    from: number;
    increment: number;
}

export interface AuctionCategory {
    id?: string;
    name: string;
    basePrice: number;
    minPerTeam: number;
    maxPerTeam: number;
    bidIncrement: number;
    bidLimit: number;
    slabs: BidIncrementSlab[];
}

export interface Sponsor {
    id: string;
    name: string;
    imageUrl: string;
}

export interface SponsorConfig {
    showOnOBS: boolean;
    showOnProjector: boolean;
    loopInterval: number; // seconds
}

export type ProjectorLayout = 'STANDARD' | 'IPL' | 'MODERN';
export type OBSLayout = 'STANDARD' | 'MINIMAL' | 'VERTICAL';

export type AdminViewType = 'SQUAD' | 'PURSES' | 'UNSOLD' | 'SOLD' | 'TOP_BUY' | 'TOP_5' | 'NONE';

export interface AdminViewOverride {
    type: AdminViewType;
    data?: any; // e.g. { teamId: '...' }
}

export type BiddingStatus = 'ON' | 'PAUSED' | 'HIDDEN';

export interface AuctionState {
  players: Player[];
  teams: Team[];
  unsoldPlayers: Player[]; // This is the pool of available players
  categories: AuctionCategory[]; // Available categories with rules
  roles: PlayerRole[]; // Added Roles to State
  status: AuctionStatus;
  currentPlayerId: string | number | null; // Source of truth for current player
  currentPlayerIndex: number | null; // Derived helper
  currentBid: number | null;
  highestBidder: Team | null;
  timer: number;
  bidIncrement: number; // Global fallback increment
  bidSlabs?: BidIncrementSlab[]; // Global fallback slabs
  auctionLog: AuctionLog[];
  biddingStatus: BiddingStatus; // Replaces biddingEnabled
  playerSelectionMode: 'MANUAL' | 'AUTO';
  auctionLogoUrl?: string;
  tournamentName?: string;
  sponsors: Sponsor[];
  sponsorConfig: SponsorConfig;
  projectorLayout: ProjectorLayout;
  obsLayout: OBSLayout;
  adminViewOverride: AdminViewOverride | null;
}

export enum UserRole {
  SUPER_ADMIN = 'SUPER_ADMIN',
  ADMIN = 'ADMIN',
  TEAM_OWNER = 'TEAM_OWNER',
  VIEWER = 'VIEWER'
}

export interface UserProfile {
  uid: string;
  email: string;
  name?: string;
  role: UserRole;
  teamId?: number | string; // If role is TEAM_OWNER
}

export type FieldType = 'text' | 'number' | 'email' | 'select' | 'date' | 'file' | 'textarea';

export interface FormField {
    id: string;
    label: string;
    type: FieldType;
    required: boolean;
    options?: string[]; // For select inputs
    placeholder?: string;
}

export interface RegistrationConfig {
    isEnabled: boolean;
    includePayment: boolean; // Controls visibility of payment section
    fee: number;
    upiId: string;
    upiName: string;
    qrCodeUrl: string;
    terms: string;
    bannerUrl?: string; // Optional tournament logo
    customFields: FormField[];
}

export interface AuctionSetup {
    id?: string;
    title: string;
    sport: string;
    date: string;
    plan: string;
    totalTeams: number;
    purseValue: number;
    basePrice: number;
    bidIncrement: number;
    slabs?: BidIncrementSlab[]; // Global slabs for auction
    playersPerTeam: number;
    status: 'DRAFT' | 'LIVE' | 'COMPLETED';
    createdAt: number;
    createdBy?: string;
    registrationConfig?: RegistrationConfig;
    logoUrl?: string;
    bannerUrl?: string;
    playerSelectionMode?: 'MANUAL' | 'AUTO';
    sponsors?: Sponsor[];
    sponsorConfig?: SponsorConfig;
    projectorLayout?: ProjectorLayout;
    obsLayout?: OBSLayout;
}

export interface Tournament {
    id?: string;
    name: string;
    createdAt: number;
    createdBy: string;
    teams?: Team[]; // For simplicity in standalone tournaments, teams might be nested or subcollection
}

export interface AuctionContextType {
    state: AuctionState;
    userProfile: UserProfile | null;
    setUserProfile: (profile: UserProfile) => void;
    placeBid: (teamId: number | string, amount: number) => Promise<void>;
    sellPlayer: (teamId?: string | number, customPrice?: number) => Promise<void>;
    passPlayer: () => Promise<void>;
    correctPlayerSale: (playerId: string, newTeamId: string | null, newPrice: number) => Promise<void>;
    startAuction: (specificPlayerId?: string | number) => Promise<boolean>;
    endAuction: () => Promise<void>;
    resetAuction: () => Promise<void>;
    resetCurrentPlayer: () => Promise<void>;
    resetUnsoldPlayers: () => Promise<void>;
    updateBiddingStatus: (status: BiddingStatus) => Promise<void>; // Updated from toggleBidding
    toggleSelectionMode: () => Promise<void>; // Toggle Auto/Manual
    updateTheme: (type: 'PROJECTOR' | 'OBS', layout: string) => Promise<void>;
    setAdminView: (view: AdminViewOverride | null) => Promise<void>;
    logout: () => void;
    error: string | null;
    joinAuction: (id: string) => void;
    activeAuctionId: string | null;
    nextBid: number; 
}

// --- SCORING TYPES ---

export interface BatsmanStats {
    playerId: string;
    name: string;
    runs: number;
    balls: number;
    fours: number;
    sixes: number;
    isStriker: boolean;
    outBy?: string; // If out, how/who
}

export interface BowlerStats {
    playerId: string;
    name: string;
    overs: number; // 1.2
    ballsBowled: number; // actual valid balls in current over
    runsConceded: number;
    wickets: number;
    maidens: number;
}

export interface BallEvent {
    ballNumber: number;
    overNumber: number; // 0, 1, 2...
    bowlerId: string;
    batsmanId: string;
    runs: number;
    isWide: boolean;
    isNoBall: boolean;
    isBye?: boolean;
    isLegBye?: boolean;
    isWicket: boolean;
    wicketType?: string;
    extras: number;
    commentary?: string;
}

export interface InningsState {
    battingTeamId: string;
    bowlingTeamId: string;
    totalRuns: number;
    wickets: number;
    overs: number; // e.g., 10.4
    ballsInCurrentOver: number; // 0-6 (valid balls)
    currentRunRate: number;
    extras: {
        wides: number;
        noBalls: number;
        byes: number;
        legByes: number;
    };
    strikerId: string | null;
    nonStrikerId: string | null;
    currentBowlerId: string | null;
    batsmen: { [playerId: string]: BatsmanStats };
    bowlers: { [playerId: string]: BowlerStats };
    recentBalls: BallEvent[];
}

export interface OverlayState {
    currentView: string; 
    theme?: 'DEFAULT' | 'CWC2023'; // Added Theme Property
    animation: string; 
    customMessage?: string;
    decision?: string;
    momId?: string;
    autoRefresh?: boolean;
}

export interface Match {
    id: string;
    auctionId: string; // ID of the Auction OR the Tournament
    sourceType?: 'AUCTION' | 'TOURNAMENT'; // Distinguish between sources
    teamAId: string;
    teamBId: string;
    teamAName: string;
    teamBName: string;
    totalOvers: number;
    status: 'SCHEDULED' | 'TOSS' | 'LIVE' | 'COMPLETED';
    tossWinnerId?: string;
    tossChoice?: 'BAT' | 'BOWL';
    currentInnings: 1 | 2;
    innings: {
        1: InningsState;
        2: InningsState;
    };
    winnerId?: string;
    createdAt: number;
    overlay?: OverlayState;
}

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db, auth } from '../firebase';
import { AuctionSetup, Team, AuctionCategory, RegistrationConfig, FormField, RegisteredPlayer, Player, Sponsor, SponsorConfig, PlayerRole, BidIncrementSlab } from '../types';
import { ArrowLeft, Plus, Trash2, X, Image as ImageIcon, AlertTriangle, FileText, Settings, Upload, Users, CheckCircle, Edit, Loader2, DollarSign, Cast, Monitor, FileSpreadsheet, UserPlus, Tag, Briefcase, Info } from 'lucide-react';
import firebase from 'firebase/compat/app';
import { useAuction } from '../hooks/useAuction';
import * as XLSX from 'xlsx';

const AuctionManage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { correctPlayerSale } = useAuction();

  const [auction, setAuction] = useState<AuctionSetup | null>(null);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'teams' | 'types' | 'categories' | 'registration' | 'registrations' | 'pool' | 'sponsors'>('teams');

  // Data States
  const [teams, setTeams] = useState<Team[]>([]);
  const [categories, setCategories] = useState<AuctionCategory[]>([]);
  const [playerRoles, setPlayerRoles] = useState<PlayerRole[]>([]);
  const [registrations, setRegistrations] = useState<RegisteredPlayer[]>([]);
  const [poolPlayers, setPoolPlayers] = useState<Player[]>([]);
  const [sponsors, setSponsors] = useState<Sponsor[]>([]);
  const [sponsorConfig, setSponsorConfig] = useState<SponsorConfig>({ showOnOBS: true, showOnProjector: true, loopInterval: 5 });

  // Registration Config State
  const [regConfig, setRegConfig] = useState<RegistrationConfig>({
      isEnabled: false,
      includePayment: true,
      fee: 1500,
      upiId: '',
      upiName: '',
      qrCodeUrl: '',
      terms: '* Player registration fees is Rs. 1500...\n* Make payment and attach screenshot...',
      bannerUrl: '',
      customFields: []
  });
  const qrInputRef = useRef<HTMLInputElement>(null);
  const bannerInputRef = useRef<HTMLInputElement>(null);

  // UI States
  const [showTeamModal, setShowTeamModal] = useState(false);
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [showRoleModal, setShowRoleModal] = useState(false);
  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isApproving, setIsApproving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Player Edit/Bulk States
  const [showAddPlayerModal, setShowAddPlayerModal] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  // Registration View Modal
  const [selectedRegistration, setSelectedRegistration] = useState<RegisteredPlayer | null>(null);
  // Auto-fill states for approval
  const [approveName, setApproveName] = useState('');
  const [approveRole, setApproveRole] = useState('');
  const [approveCategory, setApproveCategory] = useState('');
  const [approveBase, setApproveBase] = useState(0);

  // Auction Edit Modal
  const [showEditAuctionModal, setShowEditAuctionModal] = useState(false);

  // Sponsor Modal
  const [showSponsorModal, setShowSponsorModal] = useState(false);

  // Real-time Listener for Auction Details
  useEffect(() => {
    if (!id) return;

    setLoading(true);
    const unsubscribe = db.collection('auctions').doc(id).onSnapshot((docSnap) => {
        if (docSnap.exists) {
            const data = { id: docSnap.id, ...docSnap.data() } as AuctionSetup;
            setAuction(data);
            if (data.registrationConfig) {
                setRegConfig({
                    ...data.registrationConfig,
                    includePayment: data.registrationConfig.includePayment ?? true,
                    customFields: data.registrationConfig.customFields || []
                });
            }
            if (data.sponsorConfig) setSponsorConfig(data.sponsorConfig);
            setErrorMsg(null);
        } else {
            console.error("Auction not found");
            setErrorMsg("Auction not found.");
        }
        setLoading(false);
    }, (error: any) => {
        setErrorMsg(error.message);
        setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  // Real-time Listeners
  useEffect(() => {
      if (!id) return;
      const unsubTeams = db.collection('auctions').doc(id).collection('teams').onSnapshot(s => setTeams(s.docs.map(d => ({ id: d.id, ...d.data() } as Team))));
      const unsubCats = db.collection('auctions').doc(id).collection('categories').onSnapshot(s => setCategories(s.docs.map(d => ({ id: d.id, ...d.data() } as AuctionCategory))));
      const unsubRoles = db.collection('auctions').doc(id).collection('roles').onSnapshot(s => setPlayerRoles(s.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole))));
      const unsubRegs = db.collection('auctions').doc(id).collection('registrations').onSnapshot(s => setRegistrations(s.docs.map(d => ({ id: d.id, ...d.data() } as RegisteredPlayer))));
      const unsubPlayers = db.collection('auctions').doc(id).collection('players').onSnapshot(s => setPoolPlayers(s.docs.map(d => ({ id: d.id, ...d.data() } as Player))));
      const unsubSponsors = db.collection('auctions').doc(id).collection('sponsors').onSnapshot(s => setSponsors(s.docs.map(d => ({ id: d.id, ...d.data() } as Sponsor))));

      return () => {
          unsubTeams(); unsubCats(); unsubRoles(); unsubRegs(); unsubPlayers(); unsubSponsors();
      };
  }, [id]);

  // Set default approval values when a registration is selected
  useEffect(() => {
      if (selectedRegistration) {
          setApproveName(selectedRegistration.fullName);
          setApproveRole(selectedRegistration.playerType);
          setApproveCategory(''); // Let admin choose, or could default to 'Standard'
          setApproveBase(auction?.basePrice || 0);
      }
  }, [selectedRegistration, auction]);

  const handleDeleteTeam = async (teamId: string) => {
      if (!id || !auth.currentUser) return alert("You must be logged in to delete teams.");
      if (window.confirm(`Are you sure you want to delete this team (ID: ${teamId})?`)) {
          try { await db.collection('auctions').doc(id).collection('teams').doc(teamId).delete(); } catch (e: any) { alert("Failed to delete team: " + e.message); }
      }
  };

  const handleDeletePoolPlayer = async (playerId: string) => {
      if (!id) return;
      if (window.confirm("Remove player from pool?")) {
          try { await db.collection('auctions').doc(id).collection('players').doc(playerId).delete(); } catch (e: any) { alert(e.message); }
      }
  };

  const handleClearPool = async () => {
      if (!id) return;
      if (window.confirm("Delete ALL players from pool?")) {
          setIsDeleting(true);
          try {
              const snapshot = await db.collection('auctions').doc(id).collection('players').get();
              const batch = db.batch();
              snapshot.docs.forEach((doc) => batch.delete(doc.ref));
              await batch.commit();
              alert(`Deleted ${snapshot.size} players.`);
          } catch (e: any) { alert(e.message); } finally { setIsDeleting(false); }
      }
  };

  const handleApprovePlayer = async (reg: RegisteredPlayer) => {
      if (!id) return;
      if (!approveName || !approveRole) return alert("Name and Role are required.");

      setIsApproving(true);
      const newPlayerId = db.collection('dummy').doc().id; 
      const playerData: Player = {
          id: String(newPlayerId),
          name: String(approveName),
          category: String(approveCategory || 'Standard'),
          role: String(approveRole),
          basePrice: Number(approveBase),
          nationality: 'India',
          photoUrl: reg.profilePic || '',
          speciality: String(approveRole),
          stats: { matches: 0, runs: 0, wickets: 0 },
          status: 'UNSOLD'
      };
      try {
          await db.collection('auctions').doc(id).collection('players').doc(newPlayerId).set(playerData);
          await db.collection('auctions').doc(id).collection('registrations').doc(reg.id).update({ status: 'APPROVED' });
          alert("Player Approved & Added to Pool!");
          setSelectedRegistration(null);
      } catch (e: any) { alert(e.message); } finally { setIsApproving(false); }
  };

  const handleRejectPlayer = async (regId: string) => {
      if (!id) return;
      if (window.confirm("Reject registration?")) {
          try { await db.collection('auctions').doc(id).collection('registrations').doc(regId).delete(); } catch (e: any) { alert(e.message); }
      }
  };

  const handleSaveRegConfig = async () => {
      if (!id) return;
      setIsSavingConfig(true);
      try { await db.collection('auctions').doc(id).update({ registrationConfig: regConfig }); alert("Config Saved!"); } catch (e) { alert("Failed."); } finally { setIsSavingConfig(false); }
  };

  const copyRegLink = () => {
      navigator.clipboard.writeText(`${window.location.origin}/#/auction/${id}/register`);
      alert("Link Copied!");
  };

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!id) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      navigator.clipboard.writeText(`${baseUrl}#/${route}/${id}`);
      alert("OBS Link Copied!");
  }

  // ... (Excel Import Logic remains same)
  const handleExcelImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !id) return;
      setIsImporting(true);
      try {
          const data = await file.arrayBuffer();
          const workbook = XLSX.read(data);
          const jsonData = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
          let count = 0;
          let batch = db.batch();
          for (const row of jsonData as any[]) {
               const name = row['Name'] || row['name'] || row['Player Name'];
               if(name) {
                   const newId = db.collection('dummy').doc().id;
                   batch.set(db.collection('auctions').doc(id).collection('players').doc(newId), {
                       id: String(newId),
                       name: String(name),
                       category: row['Category'] || 'Standard',
                       role: row['Role'] || 'General',
                       basePrice: Number(row['Base Price'] || 0),
                       nationality: 'India',
                       photoUrl: '',
                       speciality: row['Role'] || 'General',
                       stats: { matches: 0, runs: 0, wickets: 0 },
                       status: 'UNSOLD'
                   });
                   count++;
                   if(count % 400 === 0) { await batch.commit(); batch = db.batch(); }
               }
          }
          await batch.commit();
          alert(`Imported ${count} players!`);
      } catch (err: any) { alert(err.message); } finally { setIsImporting(false); if(excelInputRef.current) excelInputRef.current.value=''; }
  };

  // ... (Sponsor Logic remains same)
  const handleSaveSponsorConfig = async () => {
      if (!id) return;
      try { await db.collection('auctions').doc(id).update({ sponsorConfig }); alert("Saved!"); } catch(e) { console.error(e); }
  };

  const deleteSponsor = async (sponsorId: string) => {
      if (!id || !window.confirm("Remove sponsor?")) return;
      try { await db.collection('auctions').doc(id).collection('sponsors').doc(sponsorId).delete(); } catch (e: any) { alert(e.message); }
  };

  // --- MODALS ---
  const EditAuctionModal = () => {
      // ... (Implementation unchanged for brevity, keeping existing modal logic)
      const [formData, setFormData] = useState({
          title: auction?.title || '',
          date: auction?.date || '',
          sport: auction?.sport || '',
          purseValue: auction?.purseValue || 0,
          basePrice: auction?.basePrice || 0,
          bidIncrement: auction?.bidIncrement || 0
      });
      const [saving, setSaving] = useState(false);

      const save = async () => {
          if(!id) return;
          setSaving(true);
          try {
              await db.collection('auctions').doc(id).update(formData);
              setShowEditAuctionModal(false);
          } catch(e:any) { alert("Failed: " + e.message); }
          finally { setSaving(false); }
      };

      return (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-fade-in">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-md p-6">
                  <h3 className="text-lg font-bold mb-4">Edit Auction Settings</h3>
                  <div className="space-y-4">
                      <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Title</label><input className="w-full border p-2 rounded" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} /></div>
                      <div className="grid grid-cols-2 gap-4">
                          <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Date</label><input type="date" className="w-full border p-2 rounded" value={formData.date} onChange={e => setFormData({...formData, date: e.target.value})} /></div>
                          <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Sport</label><input className="w-full border p-2 rounded" value={formData.sport} onChange={e => setFormData({...formData, sport: e.target.value})} /></div>
                      </div>
                      <div className="grid grid-cols-3 gap-4">
                          <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Purse</label><input type="number" className="w-full border p-2 rounded" value={formData.purseValue} onChange={e => setFormData({...formData, purseValue: Number(e.target.value)})} /></div>
                          <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Base</label><input type="number" className="w-full border p-2 rounded" value={formData.basePrice} onChange={e => setFormData({...formData, basePrice: Number(e.target.value)})} /></div>
                          <div><label className="block text-xs font-bold text-gray-500 uppercase mb-1">Increment</label><input type="number" className="w-full border p-2 rounded" value={formData.bidIncrement} onChange={e => setFormData({...formData, bidIncrement: Number(e.target.value)})} /></div>
                      </div>
                  </div>
                  <div className="flex justify-end gap-2 mt-6">
                      <button onClick={() => setShowEditAuctionModal(false)} className="px-4 py-2 border rounded">Cancel</button>
                      <button onClick={save} disabled={saving} className="px-4 py-2 bg-blue-600 text-white rounded font-bold">{saving ? 'Saving...' : 'Save'}</button>
                  </div>
              </div>
          </div>
      );
  }

  const AddSponsorModal = () => {
      // ... (Implementation unchanged for brevity)
      const [name, setName] = useState('');
      const [image, setImage] = useState('');
      const [saving, setSaving] = useState(false);
      const ref = useRef<HTMLInputElement>(null);

      const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
          const file = e.target.files?.[0];
          if(file) {
              const reader = new FileReader();
              reader.onloadend = () => setImage(reader.result as string);
              reader.readAsDataURL(file);
          }
      };

      const save = async () => {
          if(!id || !name || !image) return alert("Required");
          setSaving(true);
          try { await db.collection('auctions').doc(id).collection('sponsors').add({ name, imageUrl: image }); setShowSponsorModal(false); } catch(e:any) { alert(e.message); } finally { setSaving(false); }
      };

      return (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-fade-in">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm p-6">
