                                  type="checkbox" 
                                  checked={selectedFields.includes(field.id)}
                                  onChange={() => toggleField(field.id)}
                                  className="rounded text-blue-600 focus:ring-blue-500"
                              />
                              <span className="text-sm text-gray-700">{field.label}</span>
                          </label>
                      ))}
