            )}

            <div className={`max-w-3xl mx-auto bg-white shadow-xl rounded-xl overflow-hidden border border-gray-200 ${success ? 'blur-sm pointer-events-none' : ''}`}>

                {/* Header Section */}
                <div className="text-center p-8 pb-4">
