};

export default PlayerRegistration;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../firebase';
import { Tournament, Team, Player } from '../types';
import { Plus, Trash2, Save, FileSpreadsheet, Loader2, ChevronDown, ChevronRight, UserPlus, Users, X, Image as ImageIcon, Upload } from 'lucide-react';
import * as XLSX from 'xlsx';
import { useAuction } from '../hooks/useAuction';

const TournamentManager: React.FC = () => {
    const { userProfile } = useAuction();
    const [tournaments, setTournaments] = useState<Tournament[]>([]);
    const [loading, setLoading] = useState(true);
    const [newTournName, setNewTournName] = useState('');
    const [isCreating, setIsCreating] = useState(false);

    // Expanded Tournament ID for accordion view
    const [expandedTournId, setExpandedTournId] = useState<string | null>(null);
    const [teams, setTeams] = useState<Team[]>([]);
    const [loadingTeams, setLoadingTeams] = useState(false);

    // New Team Input
    const [newTeamName, setNewTeamName] = useState('');

    // Excel Import
    const excelInputRef = useRef<HTMLInputElement>(null);
    const [importingTeamId, setImportingTeamId] = useState<string | null>(null);

    // Manual Player Add State
    const [showAddPlayerModal, setShowAddPlayerModal] = useState(false);
    const [targetTeamId, setTargetTeamId] = useState<string | null>(null);
    const [manualPlayerName, setManualPlayerName] = useState('');
    const [manualPlayerPhoto, setManualPlayerPhoto] = useState('');
    const [isAddingPlayer, setIsAddingPlayer] = useState(false);
    const photoInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (!userProfile?.uid) return;
        const unsub = db.collection('tournaments')
            .where('createdBy', '==', userProfile.uid)
            .orderBy('createdAt', 'desc')
            .onSnapshot(snap => {
                setTournaments(snap.docs.map(d => ({ id: d.id, ...d.data() } as Tournament)));
                setLoading(false);
            });
        return () => unsub();
    }, [userProfile]);

    useEffect(() => {
        if (!expandedTournId) {
            setTeams([]);
            return;
        }
        setLoadingTeams(true);
        const unsub = db.collection('tournaments').doc(expandedTournId).collection('teams').onSnapshot(snap => {
            setTeams(snap.docs.map(d => ({ id: d.id, ...d.data() } as Team)));
            setLoadingTeams(false);
        });
        return () => unsub();
    }, [expandedTournId]);

    const handleCreateTournament = async () => {
        if (!newTournName.trim()) return;
        setIsCreating(true);
        try {
            await db.collection('tournaments').add({
                name: newTournName,
                createdBy: userProfile?.uid,
                createdAt: Date.now()
            });
            setNewTournName('');
        } catch (e) {
            console.error(e);
            alert("Failed to create tournament");
        } finally {
            setIsCreating(false);
        }
    };

    const handleDeleteTournament = async (id: string) => {
        if (window.confirm("Delete this tournament and all its teams?")) {
            await db.collection('tournaments').doc(id).delete();
        }
    };

    const handleAddTeam = async () => {
        if (!expandedTournId || !newTeamName.trim()) return;
        try {
            const teamId = db.collection('dummy').doc().id;
            await db.collection('tournaments').doc(expandedTournId).collection('teams').doc(teamId).set({
                id: teamId,
                name: newTeamName,
                owner: 'Manager',
                budget: 0,
                players: [],
                logoUrl: ''
            });
            setNewTeamName('');
        } catch (e) {
            alert("Error adding team");
        }
    };

    const handleDeleteTeam = async (teamId: string) => {
        if (!expandedTournId) return;
        if(window.confirm("Delete team?")) {
            await db.collection('tournaments').doc(expandedTournId).collection('teams').doc(teamId).delete();
        }
    };

    const handleExcelImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        // Ensure we have a file, a tournament selected, and a target team ID
        if (!file || !expandedTournId || !importingTeamId) return;

        try {
            const data = await file.arrayBuffer();
            // Important: Specify type: 'array' for arrayBuffer
            const workbook = XLSX.read(data, { type: 'array' });
            const worksheet = workbook.Sheets[workbook.SheetNames[0]];
            const jsonData = XLSX.utils.sheet_to_json(worksheet);

            if (jsonData.length === 0) {
                alert("File empty or invalid format");
                return;
            }

            const newPlayers: Player[] = jsonData.map((row: any) => {
                // Support multiple column names for Name
                const name = row['Name'] || row['name'] || row['Player Name'];
                if (!name) return null;

                return {
                    id: db.collection('dummy').doc().id,
                    name: String(name),
                    role: row['Role'] || row['role'] || 'General',
                    category: row['Category'] || row['category'] || 'Standard',
                    basePrice: Number(row['Base Price'] || 0),
                    photoUrl: '',
                    nationality: 'India',
                    speciality: row['Role'] || 'General',
                    stats: { matches: 0, runs: 0, wickets: 0 },
                    status: 'SOLD',
                    soldPrice: Number(row['Sold Price'] || row['Price'] || 0)
                };
            }).filter(p => p !== null) as Player[];

            if (newPlayers.length === 0) {
                alert("No valid players found in Excel. Check column headers (Name, Role, Category).");
                return;
            }

            // Fetch current team to append
            const teamRef = db.collection('tournaments').doc(expandedTournId).collection('teams').doc(importingTeamId);
            const teamDoc = await teamRef.get();
            if (teamDoc.exists) {
                const currentPlayers = (teamDoc.data() as Team).players || [];
                await teamRef.update({
                    players: [...currentPlayers, ...newPlayers]
                });
                alert(`Successfully added ${newPlayers.length} players to team.`);
            } else {
                alert("Team not found in database.");
            }
        } catch (err: any) {
            console.error("Import Error", err);
            alert("Import Failed: " + err.message);
        } finally {
            if (excelInputRef.current) excelInputRef.current.value = '';
            setImportingTeamId(null);
        }
    };

    const triggerImport = (teamId: string) => {
        setImportingTeamId(teamId);
        // Small timeout to ensure state update propagates before click
        setTimeout(() => {
            if (excelInputRef.current) {
                excelInputRef.current.click();
            }
        }, 100);
    };

    // Manual Player Functions
    const openAddPlayerModal = (teamId: string) => {
        setTargetTeamId(teamId);
        setManualPlayerName('');
        setManualPlayerPhoto('');
        setShowAddPlayerModal(true);
    };

    const handlePhotoSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            if (file.size > 500 * 1024) {
                alert("Image too large (Max 500KB)");
                return;
            }
            const reader = new FileReader();
            reader.onloadend = () => {
                setManualPlayerPhoto(reader.result as string);
            };
            reader.readAsDataURL(file);
        }
    };

    const saveManualPlayer = async () => {
        if (!expandedTournId || !targetTeamId || !manualPlayerName.trim()) return;

        setIsAddingPlayer(true);
        try {
            const teamRef = db.collection('tournaments').doc(expandedTournId).collection('teams').doc(targetTeamId);
            const teamDoc = await teamRef.get();

            if (teamDoc.exists) {
                const currentPlayers = (teamDoc.data() as Team).players || [];

                const newPlayer: Player = {
                    id: db.collection('dummy').doc().id,
                    name: manualPlayerName,
                    role: 'General', 
                    category: 'Standard', 
                    basePrice: 0,
                    photoUrl: manualPlayerPhoto,
                    nationality: 'India',
                    speciality: 'General',
                    stats: { matches: 0, runs: 0, wickets: 0 },
                    status: 'SOLD',
                    soldPrice: 0
                };

                await teamRef.update({
                    players: [...currentPlayers, newPlayer]
                });

                setShowAddPlayerModal(false);
            }
        } catch (e: any) {
            console.error(e);
            alert("Error adding player: " + e.message);
        } finally {
            setIsAddingPlayer(false);
        }
    };

    return (
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6 relative">
            <h2 className="text-xl font-bold text-gray-800 mb-4 flex items-center">
                <Users className="w-5 h-5 mr-2 text-blue-600"/> Tournament Manager
            </h2>

            <div className="flex gap-2 mb-6">
                <input 
                    type="text" 
                    placeholder="New Tournament Name" 
                    className="flex-1 border rounded px-3 py-2 text-sm"
                    value={newTournName}
                    onChange={(e) => setNewTournName(e.target.value)}
                />
                <button 
                    onClick={handleCreateTournament} 
                    disabled={isCreating}
                    className="bg-blue-600 text-white px-4 py-2 rounded text-sm font-bold flex items-center"
                >
                    {isCreating ? <Loader2 className="w-4 h-4 animate-spin"/> : <Plus className="w-4 h-4 mr-1"/>} Create
                </button>
            </div>

            <div className="space-y-3">
                {tournaments.length === 0 && !loading && (
                    <div className="text-center text-gray-500 py-4 italic">No standalone tournaments created.</div>
                )}
                {tournaments.map(tourn => (
                    <div key={tourn.id} className="border border-gray-200 rounded-lg overflow-hidden">
                        <div 
                            className="bg-gray-50 p-3 flex justify-between items-center cursor-pointer hover:bg-gray-100"
                            onClick={() => setExpandedTournId(expandedTournId === tourn.id ? null : tourn.id!)}
                        >
                            <div className="flex items-center gap-2 font-bold text-gray-700">
                                {expandedTournId === tourn.id ? <ChevronDown className="w-4 h-4"/> : <ChevronRight className="w-4 h-4"/>}
                                {tourn.name}
                            </div>
                            <button 
                                onClick={(e) => { e.stopPropagation(); handleDeleteTournament(tourn.id!); }}
                                className="text-red-400 hover:text-red-600 p-1"
                            >
                                <Trash2 className="w-4 h-4"/>
                            </button>
                        </div>

                        {expandedTournId === tourn.id && (
                            <div className="p-4 bg-white border-t border-gray-200 animate-slide-up">
                                <div className="flex gap-2 mb-4">
                                    <input 
                                        type="text" 
                                        placeholder="Add Team Name" 
                                        className="flex-1 border rounded px-3 py-1.5 text-sm"
                                        value={newTeamName}
                                        onChange={(e) => setNewTeamName(e.target.value)}
                                    />
                                    <button 
                                        onClick={handleAddTeam}
                                        className="bg-green-600 text-white px-3 py-1.5 rounded text-xs font-bold"
                                    >
                                        Add Team
                                    </button>
                                </div>

                                {loadingTeams ? (
                                    <div className="flex justify-center py-4"><Loader2 className="w-5 h-5 animate-spin text-blue-500"/></div>
                                ) : (
                                    <div className="space-y-2">
                                        {teams.length === 0 && <p className="text-xs text-gray-400 text-center">No teams added yet.</p>}
                                        {teams.map(team => (
                                            <div key={team.id} className="flex flex-col sm:flex-row justify-between items-center bg-gray-50 p-2 rounded border border-gray-100 gap-2">
                                                <div className="flex-1">
                                                    <span className="font-bold text-sm text-gray-800">{team.name}</span>
                                                    <span className="text-xs text-gray-500 ml-2">({team.players.length} players)</span>
                                                </div>
                                                <div className="flex items-center gap-2">
                                                    <button 
                                                        onClick={() => openAddPlayerModal(team.id.toString())}
                                                        className="bg-white text-green-600 hover:bg-green-50 px-2 py-1 rounded text-xs flex items-center border border-green-200 font-bold shadow-sm"
                                                        title="Add Player Manually"
                                                    >
                                                        <UserPlus className="w-3 h-3 mr-1"/> Add
                                                    </button>
                                                    <button 
                                                        onClick={() => triggerImport(team.id.toString())}
                                                        className="bg-blue-50 text-blue-600 hover:bg-blue-100 px-2 py-1 rounded text-xs flex items-center border border-blue-200"
                                                        title="Import Players from Excel"
                                                    >
                                                        <FileSpreadsheet className="w-3 h-3 mr-1"/> Import
                                                    </button>
                                                    <button onClick={() => handleDeleteTeam(team.id.toString())} className="text-gray-400 hover:text-red-500 p-1">
                                                        <Trash2 className="w-4 h-4"/>
                                                    </button>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* Hidden Input for Excel */}
            <input ref={excelInputRef} type="file" accept=".xlsx, .xls" className="hidden" onChange={handleExcelImport}/>

            {/* MANUAL PLAYER MODAL */}
            {showAddPlayerModal && (
                <div className="fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4">
                    <div className="bg-white rounded-lg shadow-xl w-full max-w-sm overflow-hidden animate-slide-up">
                        <div className="bg-gray-100 p-3 border-b border-gray-200 flex justify-between items-center">
                            <h3 className="font-bold text-gray-700">Add Player to Team</h3>
                            <button onClick={() => setShowAddPlayerModal(false)} className="text-gray-400 hover:text-red-500"><X className="w-5 h-5"/></button>
                        </div>

                        <div className="p-4 space-y-4">
                            <div className="flex flex-col items-center">
                                <div 
                                    onClick={() => photoInputRef.current?.click()}
                                    className="w-24 h-24 rounded-full bg-gray-100 border-2 border-dashed border-gray-300 flex items-center justify-center cursor-pointer hover:bg-gray-50 overflow-hidden relative"
                                >
                                    {manualPlayerPhoto ? (
                                        <img src={manualPlayerPhoto} alt="Preview" className="w-full h-full object-cover"/>
                                    ) : (
                                        <div className="text-center text-gray-400">
                                            <ImageIcon className="w-8 h-8 mx-auto mb-1"/>
                                            <span className="text-[10px]">Photo</span>
                                        </div>
                                    )}
                                    <div className="absolute bottom-0 w-full bg-black/50 text-white text-[9px] text-center py-0.5">Click to Upload</div>
                                </div>
                                <input ref={photoInputRef} type="file" accept="image/*" className="hidden" onChange={handlePhotoSelect}/>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Player Name</label>
                                <input 
                                    type="text" 
                                    className="w-full border rounded p-2 text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                                    placeholder="Enter full name"
                                    value={manualPlayerName}
                                    onChange={(e) => setManualPlayerName(e.target.value)}
                                />
                            </div>

                            <button 
                                onClick={saveManualPlayer}
                                disabled={isAddingPlayer || !manualPlayerName.trim()}
                                className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-2 rounded shadow transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
                            >
                                {isAddingPlayer ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Add Player'}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default TournamentManager;

import React, { useEffect, useState, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db, auth } from '../firebase';
import { AuctionSetup, Team, AuctionCategory, RegistrationConfig, FormField, RegisteredPlayer, Player, Sponsor, SponsorConfig, PlayerRole, BidIncrementSlab, FieldType } from '../types';
import { ArrowLeft, Plus, Trash2, X, Image as ImageIcon, AlertTriangle, FileText, Settings, Upload, Users, CheckCircle, Edit, Loader2, DollarSign, Cast, Monitor, FileSpreadsheet, UserPlus, Tag, Briefcase, Info, Save, ChevronDown, ChevronUp, Download, List } from 'lucide-react';
import firebase from 'firebase/compat/app';
import { useAuction } from '../hooks/useAuction';
import * as XLSX from 'xlsx';

const AuctionManage: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { correctPlayerSale } = useAuction();

  const [auction, setAuction] = useState<AuctionSetup | null>(null);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'teams' | 'types' | 'categories' | 'registration' | 'registrations' | 'pool' | 'sponsors'>('teams');

  // Data States
  const [teams, setTeams] = useState<Team[]>([]);
  const [categories, setCategories] = useState<AuctionCategory[]>([]);
  const [playerRoles, setPlayerRoles] = useState<PlayerRole[]>([]);
  const [registrations, setRegistrations] = useState<RegisteredPlayer[]>([]);
  const [poolPlayers, setPoolPlayers] = useState<Player[]>([]);
  const [sponsors, setSponsors] = useState<Sponsor[]>([]);
  const [sponsorConfig, setSponsorConfig] = useState<SponsorConfig>({ showOnOBS: true, showOnProjector: true, loopInterval: 5 });

  // Registration Config State
  const [regConfig, setRegConfig] = useState<RegistrationConfig>({
      isEnabled: false,
      includePayment: true,
      fee: 1500,
      upiId: '',
      upiName: '',
      qrCodeUrl: '',
      terms: '* Player registration fees is Rs. 1500...\n* Make payment and attach screenshot...',
      bannerUrl: '',
      customFields: []
  });

  // Custom Field State
  const [newField, setNewField] = useState<{
      label: string;
      type: FieldType;
      required: boolean;
      options: string; // comma separated for UI
  }>({
      label: '',
      type: 'text',
      required: false,
      options: ''
  });

  const qrInputRef = useRef<HTMLInputElement>(null);
  const bannerInputRef = useRef<HTMLInputElement>(null);

  // UI States
  const [showTeamModal, setShowTeamModal] = useState(false);
  const [editingTeam, setEditingTeam] = useState<Team | null>(null);

  // Category UI State
  const [showCategoryModal, setShowCategoryModal] = useState(false);
  const [editingCategory, setEditingCategory] = useState<AuctionCategory | null>(null);

  // Role UI State
  const [showRoleModal, setShowRoleModal] = useState(false);
  const [editingRole, setEditingRole] = useState<PlayerRole | null>(null);

  const [isSavingConfig, setIsSavingConfig] = useState(false);
  const [isApproving, setIsApproving] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  // Player Edit/Bulk States
  const [showAddPlayerModal, setShowAddPlayerModal] = useState(false);
  const [isImporting, setIsImporting] = useState(false);
  const excelInputRef = useRef<HTMLInputElement>(null);

  // Registration View Modal
  const [selectedRegistration, setSelectedRegistration] = useState<RegisteredPlayer | null>(null);
  // Auto-fill states for approval
  const [approveName, setApproveName] = useState('');
  const [approveRole, setApproveRole] = useState('');
  const [approveCategory, setApproveCategory] = useState('');
  const [approveBase, setApproveBase] = useState(0);

  // Auction Edit Modal
  const [showEditAuctionModal, setShowEditAuctionModal] = useState(false);

  // Sponsor Modal
  const [showSponsorModal, setShowSponsorModal] = useState(false);

  // Export Modal
  const [showExportModal, setShowExportModal] = useState(false);

  // Real-time Listener for Auction Details
  useEffect(() => {
    if (!id) return;

    setLoading(true);
    const unsubscribe = db.collection('auctions').doc(id).onSnapshot((docSnap) => {
        if (docSnap.exists) {
            const data = { id: docSnap.id, ...docSnap.data() } as AuctionSetup;
            setAuction(data);
            if (data.registrationConfig) {
                setRegConfig({
                    ...data.registrationConfig,
                    includePayment: data.registrationConfig.includePayment ?? true,
                    customFields: data.registrationConfig.customFields || []
                });
            }
            if (data.sponsorConfig) setSponsorConfig(data.sponsorConfig);
            setErrorMsg(null);
        } else {
            console.error("Auction not found");
            setErrorMsg("Auction not found.");
        }
        setLoading(false);
    }, (error: any) => {
        setErrorMsg(error.message);
        setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  // Real-time Listeners
  useEffect(() => {
      if (!id) return;
      const unsubTeams = db.collection('auctions').doc(id).collection('teams').onSnapshot(s => setTeams(s.docs.map(d => ({ id: d.id, ...d.data() } as Team))));
      const unsubCats = db.collection('auctions').doc(id).collection('categories').onSnapshot(s => setCategories(s.docs.map(d => ({ id: d.id, ...d.data() } as AuctionCategory))));
      const unsubRoles = db.collection('auctions').doc(id).collection('roles').onSnapshot(s => setPlayerRoles(s.docs.map(d => ({ id: d.id, ...d.data() } as PlayerRole))));
      const unsubRegs = db.collection('auctions').doc(id).collection('registrations').onSnapshot(s => setRegistrations(s.docs.map(d => ({ id: d.id, ...d.data() } as RegisteredPlayer))));
      const unsubPlayers = db.collection('auctions').doc(id).collection('players').onSnapshot(s => setPoolPlayers(s.docs.map(d => ({ id: d.id, ...d.data() } as Player))));
      const unsubSponsors = db.collection('auctions').doc(id).collection('sponsors').onSnapshot(s => setSponsors(s.docs.map(d => ({ id: d.id, ...d.data() } as Sponsor))));

      return () => {
          unsubTeams(); unsubCats(); unsubRoles(); unsubRegs(); unsubPlayers(); unsubSponsors();
      };
  }, [id]);

  // Set default approval values when a registration is selected
  useEffect(() => {
      if (selectedRegistration) {
          setApproveName(selectedRegistration.fullName);
          setApproveRole(selectedRegistration.playerType);
          setApproveCategory(''); // Let admin choose, or could default to 'Standard'
          setApproveBase(auction?.basePrice || 0);
      }
  }, [selectedRegistration, auction]);

  const handleDeleteTeam = async (teamId: string) => {
      if (!id || !auth.currentUser) return alert("You must be logged in to delete teams.");
      if (window.confirm(`Are you sure you want to delete this team (ID: ${teamId})?`)) {
          try { await db.collection('auctions').doc(id).collection('teams').doc(teamId).delete(); } catch (e: any) { alert("Failed to delete team: " + e.message); }
      }
  };

  const handleDeleteCategory = async (catId: string) => {
      if (!id) return;
      if (window.confirm("Delete this category?")) {
          try { await db.collection('auctions').doc(id).collection('categories').doc(catId).delete(); } catch (e: any) { alert("Failed to delete: " + e.message); }
      }
  };

  const handleDeleteRole = async (roleId: string) => {
      if (!id) return;
      if (window.confirm("Delete this player role?")) {
          try { await db.collection('auctions').doc(id).collection('roles').doc(roleId).delete(); } catch (e: any) { alert("Failed to delete: " + e.message); }
      }
  };

  const handleDeletePoolPlayer = async (playerId: string) => {
      if (!id) return;
      if (window.confirm("Remove player from pool?")) {
          try { await db.collection('auctions').doc(id).collection('players').doc(playerId).delete(); } catch (e: any) { alert(e.message); }
      }
  };

  const handleClearPool = async () => {
      if (!id) return;
      if (window.confirm("Delete ALL players from pool?")) {
          setIsDeleting(true);
          try {
              const snapshot = await db.collection('auctions').doc(id).collection('players').get();
              const batch = db.batch();
              snapshot.docs.forEach((doc) => batch.delete(doc.ref));
              await batch.commit();
              alert(`Deleted ${snapshot.size} players.`);
          } catch (e: any) { alert(e.message); } finally { setIsDeleting(false); }
      }
  };

  const handleApprovePlayer = async (reg: RegisteredPlayer) => {
      if (!id) return;
      if (!approveName || !approveRole) return alert("Name and Role are required.");

      setIsApproving(true);
      const newPlayerId = db.collection('dummy').doc().id; 
      const playerData: Player = {
          id: String(newPlayerId),
          name: String(approveName),
          category: String(approveCategory || 'Standard'),
          role: String(approveRole),
          basePrice: Number(approveBase),
          nationality: 'India',
          photoUrl: reg.profilePic || '',
          speciality: String(approveRole),
          stats: { matches: 0, runs: 0, wickets: 0 },
          status: 'UNSOLD'
      };
      try {
          await db.collection('auctions').doc(id).collection('players').doc(newPlayerId).set(playerData);
          await db.collection('auctions').doc(id).collection('registrations').doc(reg.id).update({ status: 'APPROVED' });
          alert("Player Approved & Added to Pool!");
          setSelectedRegistration(null);
      } catch (e: any) { alert(e.message); } finally { setIsApproving(false); }
  };

  const handleRejectPlayer = async (regId: string) => {
      if (!id) return;
      if (window.confirm("Reject registration?")) {
          try { await db.collection('auctions').doc(id).collection('registrations').doc(regId).delete(); } catch (e: any) { alert(e.message); }
      }
  };

  const handleSaveRegConfig = async () => {
      if (!id) return;
      setIsSavingConfig(true);
      try { 
          // Deep clean undefined values (Firestore rejects undefined)
          const cleanConfig = JSON.parse(JSON.stringify(regConfig));
          await db.collection('auctions').doc(id).update({ registrationConfig: cleanConfig }); 
          alert("Config Saved Successfully!"); 
      } catch (e: any) { 
          console.error("Save Error:", e);
          alert("Failed to save config: " + e.message); 
      } finally { 
          setIsSavingConfig(false); 
      }
  };

  // Custom Field Handlers
  const handleAddCustomField = () => {
      if (!newField.label.trim()) return alert("Field Label is required");

      const fieldId = `field_${Date.now()}`;

      const field: FormField = {
          id: fieldId,
          label: newField.label,
          type: newField.type,
          required: newField.required,
          placeholder: `Enter ${newField.label}`
      };

      // Only add options if it's a select field to avoid undefined values in state
      if (newField.type === 'select') {
          field.options = newField.options.split(',').map(s => s.trim()).filter(s => s);
      }

      setRegConfig(prev => ({
          ...prev,
          customFields: [...(prev.customFields || []), field]
      }));

      // Reset form
      setNewField({
          label: '',
          type: 'text',
          required: false,
          options: ''
      });
  };

  const handleDeleteCustomField = (fieldId: string) => {
      setRegConfig(prev => ({
          ...prev,
          customFields: prev.customFields?.filter(f => f.id !== fieldId) || []
      }));
  };

  const copyRegLink = () => {
      navigator.clipboard.writeText(`${window.location.origin}/#/auction/${id}/register`);
      alert("Link Copied!");
  };

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!id) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      navigator.clipboard.writeText(`${baseUrl}#/${route}/${id}`);
      alert("OBS Link Copied!");
  }

  // --- EXCEL IMPORT LOGIC ---
  const handleExcelImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file || !id) return;
      setIsImporting(true);
      try {
          const data = await file.arrayBuffer();
          // Specify type: 'array' for reliability
          const workbook = XLSX.read(data, { type: 'array' });
          const worksheet = workbook.Sheets[workbook.SheetNames[0]];
          const jsonData = XLSX.utils.sheet_to_json(worksheet);

          if (jsonData.length === 0) {
              alert("File appears to be empty.");
              return;
          }

          let count = 0;
          let batch = db.batch();
          const BATCH_SIZE = 400; // Firestore batch limit is 500

          for (const row of jsonData as any[]) {
               const name = row['Name'] || row['name'] || row['Player Name'];
               if(name) {
                   const newId = db.collection('dummy').doc().id;
                   const playerData: Player = {
                       id: String(newId),
                       name: String(name),
                       category: row['Category'] || row['category'] || 'Standard',
                       role: row['Role'] || row['role'] || 'General',
                       basePrice: Number(row['Base Price'] || row['Base'] || 0),
                       nationality: 'India',
                       photoUrl: '',
                       speciality: row['Role'] || row['role'] || 'General',
                       stats: { matches: 0, runs: 0, wickets: 0 },
                       status: 'UNSOLD'
                   };

                   batch.set(db.collection('auctions').doc(id).collection('players').doc(newId), playerData);
                   count++;

                   if(count % BATCH_SIZE === 0) { 
                       await batch.commit(); 
                       batch = db.batch(); 
                   }
               }
          }

          if (count % BATCH_SIZE !== 0) {
              await batch.commit();
          }

          alert(`Successfully imported ${count} players!`);
      } catch (err: any) { 
          console.error(err);
          alert("Import Failed: " + err.message); 
      } finally { 
          setIsImporting(false); 
          if(excelInputRef.current) excelInputRef.current.value=''; 
      }
  };

  // ... (Sponsor Logic remains same)
  const handleSaveSponsorConfig = async () => {
      if (!id) return;
      try { await db.collection('auctions').doc(id).update({ sponsorConfig }); alert("Saved!"); } catch(e) { console.error(e); }
  };

  const deleteSponsor = async (sponsorId: string) => {
      if (!id || !window.confirm("Remove sponsor?")) return;
      try { await db.collection('auctions').doc(id).collection('sponsors').doc(sponsorId).delete(); } catch (e: any) { alert(e.message); }
  };

  // --- MODALS ---
  const CategoryModal = () => {
      const [cName, setCName] = useState(editingCategory?.name || '');
      const [cBase, setCBase] = useState(editingCategory?.basePrice || 0);
      const [saving, setSaving] = useState(false);

      const save = async () => {
          if (!id || !cName) return alert("Name required");
          setSaving(true);
          try {
              const data = { name: cName, basePrice: Number(cBase) };
              if (editingCategory?.id) {
                  await db.collection('auctions').doc(id).collection('categories').doc(editingCategory.id).update(data);
              } else {
                  await db.collection('auctions').doc(id).collection('categories').add(data);
              }
              setShowCategoryModal(false);
          } catch(e: any) { alert(e.message); } finally { setSaving(false); }
      };

      return (
          <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 animate-fade-in">
              <div className="bg-white rounded-xl shadow-2xl w-full max-w-sm p-6">
