                    // Reset to OPEN first (handles refunds if previously sold)
                    await correctPlayerSale(String(statusPlayer.id), null, 0);

                    if (sStatus === 'UNSOLD') {
                        await db.collection('auctions').doc(id).collection('players').doc(String(statusPlayer.id)).update({
