      const addSlab = () => {
          const fromVal = Number(newSlab.from);
          const incVal = Number(newSlab.increment);
          if (fromVal >= 0 && incVal > 0) {
              setSlabs(prev => [...prev, { from: fromVal, increment: incVal }]);
              setNewSlab({ from: '', increment: '' });
          }
