        const handleSave = async () => {
            if (!id || !editingPlayer) return;
            setSaving(true);
            try {
                // 1. Update Basic Details first
                const basicUpdates: Partial<Player> = {
                    name: pName,
                    category: pCat,
                    role: pRole,
                    basePrice: Number(pBase),
