                                    {pPhoto ? <img src={pPhoto} className="w-full h-full object-cover"/> : <div className="text-gray-400 text-center"><ImageIcon className="w-6 h-6 mx-auto"/><span className="text-[9px] block">Photo</span></div>}
                                </div>
