                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 uppercase mb-1">Sold To Team</label>
                                        <select className="w-full border p-2 rounded text-sm" value={sTeam} onChange={e => setSTeam(e.target.value)}>
