const placeBid = async (teamId: number | string, amount: number) => {
    if (!activeAuctionId) return;

    const isAdmin = userProfile?.role === UserRole.ADMIN || userProfile?.role === UserRole.SUPER_ADMIN;

    // STRICT EXCLUSIVE CHECK:
    // If not Admin, enforce Bidding Status
    if (!isAdmin && state.biddingStatus !== 'ON') {
        alert("Bidding is currently disabled by the Admin.");
        return;
    }

    const auctionRef = db.collection('auctions').doc(activeAuctionId);

    try {
      await db.runTransaction(async (transaction) => {
          const auctionSnap = await transaction.get(auctionRef);
          if (!auctionSnap.exists) throw "No auction";
          const data = auctionSnap.data() as any;

          if (data?.status !== AuctionStatus.InProgress) throw "Auction not in progress";

          // Server side check (Skip for Admin)
          if (!isAdmin) {
              if (data?.biddingStatus && data.biddingStatus !== 'ON') throw "Bidding is currently paused by Admin";
              if (data?.biddingEnabled === false && !data.biddingStatus) throw "Bidding is currently paused by Admin";
          }

          const currentPlayerId = data?.currentPlayerId;
          if (!currentPlayerId) throw "No active player";

          const playerRef = auctionRef.collection('players').doc(String(currentPlayerId));
          const playerSnap = await transaction.get(playerRef);
          if (!playerSnap.exists) throw "Player data missing";
          const playerData = playerSnap.data() as Player;

          const teamRef = auctionRef.collection('teams').doc(String(teamId));
          const teamSnap = await transaction.get(teamRef);
          if (!teamSnap.exists) throw "Team not found";
          const teamData = teamSnap.data() as Team;

          // --- CATEGORY LIMIT CHECK ---
          const playerCategory = playerData.category;
          // Note: We use state.categories here assuming config doesn't change mid-auction. 
          // Ideally fetch categories in transaction if strict consistency needed, but this is efficient.
          const categoryConfig = state.categories.find(c => c.name === playerCategory);

          if (categoryConfig && categoryConfig.maxPerTeam > 0) {
              const currentPlayers = teamData.players || [];
              // Count players in this specific category
              const categoryCount = currentPlayers.filter(p => p.category === playerCategory).length;

              if (categoryCount >= categoryConfig.maxPerTeam) {
                  throw `Limit Reached: Team can only buy ${categoryConfig.maxPerTeam} players in '${playerCategory}' category.`;
              }
          }
          // -----------------------------

          const currentHighest = Number(data?.currentBid || 0);

          // Allow initial bid to be base price
          if (amount <= 0) throw "Invalid Bid Amount";

          if (currentHighest > 0 && amount <= currentHighest) {
              throw `Bid (${amount}) must be higher than current bid (${currentHighest})`;
          }

          if (Number(teamData.budget) < amount) throw "Insufficient funds";

          transaction.update(auctionRef, {
              currentBid: Number(amount),
              highestBidderId: String(teamId),
              timer: BID_INTERVAL 
          });

          const logRef = auctionRef.collection('log').doc();
          transaction.set(logRef, {
              message: `${teamData.name} bids ${amount} ${isAdmin ? '(Admin)' : ''}`,
              timestamp: Date.now(), 
              type: 'BID'
          });
      });
      console.log("Bid placed successfully");
    } catch (e: any) {
        console.error("Bid Error:", e);
        alert(`Bid Failed: ${e.message || e}`);
        throw e;
    }
};

// Find user's team securely
const userTeam = teams.find(t => String(t.id) === String(userProfile.teamId));
if (!userTeam) return null;

const { currentPlayerIndex, unsoldPlayers, categories } = state;
const currentPlayer = currentPlayerIndex !== null ? unsoldPlayers[currentPlayerIndex] : null;

// Check Category Limit
let isCategoryLimitReached = false;
let categoryLimitMsg = "";

if (currentPlayer && currentPlayer.category) {
    const catConfig = categories.find(c => c.name === currentPlayer.category);
    if (catConfig && catConfig.maxPerTeam > 0) {
        const currentCount = userTeam.players.filter(p => p.category === currentPlayer.category).length;
        if (currentCount >= catConfig.maxPerTeam) {
            isCategoryLimitReached = true;
            categoryLimitMsg = `Max ${catConfig.maxPerTeam} '${currentPlayer.category}' players reached`;
        }
    }
}

const canAfford = userTeam.budget >= nextBid;
const isLeading = highestBidder && String(highestBidder.id) === String(userTeam.id);
const isLoadingBid = nextBid === 0;

// Status Helpers
const isPaused = biddingStatus === 'PAUSED';
const isActive = biddingStatus === 'ON';

// Sorted teams by budget for display
const sortedTeams = [...teams].sort((a,b) => b.budget - a.budget);

const handleBid = async () => {
  // Strict Client-Side Check
  if (canAfford && !isLeading && isActive && !isCategoryLimitReached) {
    setIsBidding(true);
    try {
