                                <select className={`w-full border p-2 rounded font-bold ${sStatus === 'SOLD' ? 'text-green-600' : sStatus === 'UNSOLD' ? 'text-red-600' : 'text-gray-600'}`} value={sStatus} onChange={(e) => setSStatus(e.target.value as any)}>
