                                    </div>
                                    <p className="text-[10px] text-green-700">
                                        Note: Changing this will automatically update team budgets.
                                    </p>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="flex justify-end gap-2 mt-6">
