        try {
            if (editItem.id) {
                await db.collection('auctions').doc(id).collection('categories').doc(editItem.id).update(catData);
                setCategories(prev => prev.map(c => c.id === editItem.id ? { ...c, ...catData } : c));
            } else {
                const newRef = db.collection('auctions').doc(id).collection('categories').doc();
                await newRef.set({ id: newRef.id, ...catData });
                setCategories(prev => [...prev, { id: newRef.id, ...catData } as AuctionCategory]);
            }
            closeModal();
        } catch (err) { alert("Error saving category"); }
    };

    const handleSaveRole = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!id) return;
        const roleData = {
            name: editItem.name,
            basePrice: Number(editItem.basePrice || 0)
        };
        try {
            if (editItem.id) {
                await db.collection('auctions').doc(id).collection('roles').doc(editItem.id).update(roleData);
                setRoles(prev => prev.map(r => r.id === editItem.id ? { ...r, ...roleData } : r));
            } else {
                const newRef = db.collection('auctions').doc(id).collection('roles').doc();
                await newRef.set({ id: newRef.id, ...roleData });
                setRoles(prev => [...prev, { id: newRef.id, ...roleData } as PlayerRole]);
            }
            closeModal();
        } catch (err) { alert("Error saving role"); }
    };

    const handleSaveSponsor = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!id) return;
        const sponsorData = {
            name: editItem.name,
            imageUrl: previewImage || editItem.imageUrl || ''
        };
        try {
            if (editItem.id) {
                await db.collection('auctions').doc(id).collection('sponsors').doc(editItem.id).update(sponsorData);
                setSponsors(prev => prev.map(s => s.id === editItem.id ? { ...s, ...sponsorData } : s));
            } else {
                const newRef = db.collection('auctions').doc(id).collection('sponsors').doc();
                await newRef.set({ id: newRef.id, ...sponsorData });
                setSponsors(prev => [...prev, { id: newRef.id, ...sponsorData } as Sponsor]);
            }
            closeModal();
        } catch (err) { alert("Error saving sponsor"); }
    };

    const handleSaveRegistrationConfig = async () => {
        if (!id) return;
        try {
            await db.collection('auctions').doc(id).update({
                registrationConfig: regConfig,
                bannerUrl: regConfig.bannerUrl // Sync banner to root for ease
            });
            alert("Registration settings saved successfully!");
        } catch (e) {
            console.error(e);
            alert("Failed to save settings");
        }
    };

    const handleApproveRequest = async (reg: RegisteredPlayer) => {
        if (!id || !window.confirm(`Approve ${reg.fullName} and add to auction pool?`)) return;
        try {
            // Create Player Object
            const newPlayer: any = {
                name: reg.fullName,
                category: 'Uncapped', // Default to Uncapped, admin can change later
                role: reg.playerType || 'All Rounder',
                basePrice: auction?.basePrice || 0,
                photoUrl: reg.profilePic || '',
                nationality: 'India',
                status: 'UNSOLD',
                stats: { matches: 0, runs: 0, wickets: 0 },
                speciality: reg.playerType
            };

            // Add to Players Collection
            const playerRef = await db.collection('auctions').doc(id).collection('players').add(newPlayer);
            const playerWithId = { id: playerRef.id, ...newPlayer };

            // Update Registration Status
            await db.collection('auctions').doc(id).collection('registrations').doc(reg.id).update({ status: 'APPROVED' });

            // Update Local State
            setPlayers(prev => [...prev, playerWithId]);
            setRegistrations(prev => prev.map(r => r.id === reg.id ? { ...r, status: 'APPROVED' } : r));

            alert("Player Approved!");
        } catch (e: any) {
            console.error(e);
            alert("Error approving player: " + e.message);
        }
    };

    const handleRejectRequest = async (regId: string) => {
        if (!id || !window.confirm("Reject this registration?")) return;
        try {
            await db.collection('auctions').doc(id).collection('registrations').doc(regId).update({ status: 'REJECTED' });
            setRegistrations(prev => prev.map(r => r.id === regId ? { ...r, status: 'REJECTED' } : r));
        } catch (e: any) {
            alert("Error: " + e.message);
        }
    };

    const handleDeleteRequest = async (regId: string) => {
        if (!id || !window.confirm("Permanently delete this request?")) return;
        try {
            await db.collection('auctions').doc(id).collection('registrations').doc(regId).delete();
            setRegistrations(prev => prev.filter(r => r.id !== regId));
        } catch (e: any) {
            alert("Error: " + e.message);
        }
    };

    const handleDelete = async (collection: string, itemId: string) => {
        if (!window.confirm("Are you sure?")) return;
        if (!id) return;
        try {
            await db.collection('auctions').doc(id).collection(collection).doc(String(itemId)).delete();
            if (collection === 'teams') setTeams(prev => prev.filter(t => t.id !== itemId));
            if (collection === 'players') setPlayers(prev => prev.filter(p => p.id !== itemId));
            if (collection === 'categories') setCategories(prev => prev.filter(c => c.id !== itemId));
            if (collection === 'sponsors') setSponsors(prev => prev.filter(s => s.id !== itemId));
            if (collection === 'roles') setRoles(prev => prev.filter(r => r.id !== itemId));
        } catch (e) { alert("Delete failed"); }
    };

    const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            const base64 = await compressImage(e.target.files[0]);
            setPreviewImage(base64);
        }
    };

    const handleRegFileChange = async (e: React.ChangeEvent<HTMLInputElement>, field: 'qrCodeUrl' | 'bannerUrl') => {
        if (e.target.files && e.target.files[0]) {
            const base64 = await compressImage(e.target.files[0]);
            setRegConfig(prev => ({ ...prev, [field]: base64 }));
        }
    };

    const addCustomField = () => {
        if (!newField.label) return alert("Enter Field Label");
        const fieldId = newField.label.toLowerCase().replace(/\s+/g, '_');
        setRegConfig(prev => ({
            ...prev,
            customFields: [...prev.customFields, { ...newField, id: fieldId }]
        }));
        setNewField({ id: '', label: '', type: 'text', required: false });
    };

    const removeCustomField = (idx: number) => {
        setRegConfig(prev => ({
            ...prev,
            customFields: prev.customFields.filter((_, i) => i !== idx)
        }));
    };

    const openModal = (item: any = {}) => {
        setEditItem(item);
        setPreviewImage(item.logoUrl || item.photoUrl || item.imageUrl || '');
        setIsEditing(true);
    };

    const closeModal = () => {
        setIsEditing(false);
        setEditItem(null);
        setPreviewImage('');
    };

    const filteredPlayers = players.filter(p => p.name.toLowerCase().includes(playerSearch.toLowerCase()));
    const filteredRequests = registrations.filter(r => r.fullName.toLowerCase().includes(requestSearch.toLowerCase()));

    const Loading = () => <div className="p-10 text-center text-gray-700">Loading...</div>;

    if (loading) return <Loading />;

    return (
        <div className="min-h-screen bg-gray-50 font-sans pb-10 text-gray-900">
            <header className="bg-white shadow-sm border-b border-gray-200 sticky top-0 z-10">
                <div className="container mx-auto px-4 py-3 flex flex-col md:flex-row justify-between items-center gap-4">
                    <div className="flex items-center gap-3 w-full md:w-auto">
                        <button onClick={() => navigate('/admin')} className="text-gray-500 hover:text-gray-800"><ArrowLeft className="w-5 h-5"/></button>
                        <h1 className="text-lg font-bold text-gray-700 truncate">{auction?.title || 'Manage Auction'}</h1>
                    </div>
                    <div className="flex gap-1 bg-gray-100 p-1 rounded-lg overflow-x-auto w-full md:w-auto custom-scrollbar">
                        {['TEAMS', 'PLAYERS', 'REQUESTS', 'CATEGORIES', 'ROLES', 'SPONSORS', 'REGISTRATION'].map((tab) => (
                            <button 
                                key={tab}
                                onClick={() => setActiveTab(tab as any)} 
                                className={`px-3 py-1 text-xs font-bold rounded whitespace-nowrap transition-colors ${activeTab === tab ? 'bg-white shadow text-blue-600' : 'text-gray-500 hover:text-gray-700'}`}
                            >
                                {tab}
                            </button>
                        ))}
                    </div>
                </div>
            </header>

            <main className="container mx-auto px-4 py-6">

                {/* TEAMS TAB */}
                {activeTab === 'TEAMS' && (
                    <div className="bg-white rounded shadow p-4">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-lg font-bold flex items-center gap-2"><Users className="w-5 h-5"/> Teams ({teams.length})</h2>
                            <button onClick={() => openModal({ name: '', budget: auction?.purseValue || 10000 })} className="bg-blue-600 text-white px-3 py-1.5 rounded text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Team</button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                            {teams.map(t => (
                                <div key={t.id} className="border rounded p-3 flex items-center gap-3 relative group hover:shadow-md transition-shadow">
                                    <img src={t.logoUrl || 'https://via.placeholder.com/50'} className="w-12 h-12 object-contain bg-gray-100 rounded-full" />
                                    <div>
                                        <h3 className="font-bold text-gray-800">{t.name}</h3>
                                        <p className="text-xs text-gray-500">Budget: {t.budget}</p>
                                    </div>
                                    <div className="absolute top-2 right-2 hidden group-hover:flex gap-1">
                                        <button onClick={() => openModal(t)} className="p-1 text-blue-500 bg-blue-50 rounded"><Edit className="w-3 h-3"/></button>
                                        <button onClick={() => handleDelete('teams', String(t.id))} className="p-1 text-red-500 bg-red-50 rounded"><Trash2 className="w-3 h-3"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* PLAYERS TAB */}
                {activeTab === 'PLAYERS' && (
                    <div className="bg-white rounded shadow p-4">
                        <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-3">
                            <h2 className="text-lg font-bold flex items-center gap-2"><Users className="w-5 h-5"/> Players ({players.length})</h2>
                            <div className="flex gap-2 w-full md:w-auto">
                                <div className="relative flex-grow md:flex-grow-0">
                                    <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                    <input 
                                        type="text" 
                                        placeholder="Search players..." 
                                        className="w-full md:w-64 border rounded pl-9 pr-3 py-1.5 text-sm outline-none focus:ring-1 focus:ring-blue-500"
                                        value={playerSearch}
                                        onChange={(e) => setPlayerSearch(e.target.value)}
                                    />
                                </div>
                                <button onClick={() => openModal({ name: '', basePrice: auction?.basePrice || 20, category: 'Uncapped', role: 'All Rounder' })} className="bg-blue-600 text-white px-3 py-1.5 rounded text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Player</button>
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-left text-sm text-gray-700">
                                <thead className="bg-gray-100 text-gray-600">
                                    <tr>
                                        <th className="p-2">Name</th>
                                        <th className="p-2">Category</th>
                                        <th className="p-2">Role</th>
                                        <th className="p-2">Base Price</th>
                                        <th className="p-2 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredPlayers.length > 0 ? filteredPlayers.map(p => (
                                        <tr key={p.id} className="border-b hover:bg-gray-50">
                                            <td className="p-2 flex items-center gap-2">
                                                <img src={p.photoUrl || 'https://via.placeholder.com/30'} className="w-8 h-8 rounded-full object-cover"/>
                                                {p.name}
                                            </td>
                                            <td className="p-2">{p.category}</td>
                                            <td className="p-2">{p.role}</td>
                                            <td className="p-2">{p.basePrice}</td>
                                            <td className="p-2 text-right">
                                                <button onClick={() => openModal(p)} className="text-blue-500 mr-2"><Edit className="w-4 h-4"/></button>
                                                <button onClick={() => handleDelete('players', String(p.id))} className="text-red-500"><Trash2 className="w-4 h-4"/></button>
                                            </td>
                                        </tr>
                                    )) : (
                                        <tr><td colSpan={5} className="p-4 text-center text-gray-400 italic">No players found</td></tr>
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* REQUESTS TAB */}
                {activeTab === 'REQUESTS' && (
                    <div className="bg-white rounded shadow p-4">
                        <div className="flex flex-col md:flex-row justify-between items-center mb-4 gap-3">
                            <h2 className="text-lg font-bold flex items-center gap-2"><Clock className="w-5 h-5"/> Registration Requests ({registrations.length})</h2>
                            <div className="relative w-full md:w-64">
                                <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
                                <input 
                                    type="text" 
                                    placeholder="Search requests..." 
                                    className="w-full border rounded pl-9 pr-3 py-1.5 text-sm outline-none focus:ring-1 focus:ring-blue-500"
                                    value={requestSearch}
                                    onChange={(e) => setRequestSearch(e.target.value)}
                                />
                            </div>
                        </div>
                        <div className="overflow-x-auto">
                            <table className="w-full text-left text-sm text-gray-700">
                                <thead className="bg-gray-100 text-gray-600">
                                    <tr>
                                        <th className="p-3">Player</th>
                                        <th className="p-3">Details</th>
                                        <th className="p-3">Status</th>
                                        <th className="p-3 text-right">Actions</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {filteredRequests.map(r => (
                                        <tr key={r.id} className="border-b hover:bg-gray-50">
                                            <td className="p-3 flex items-center gap-3">
                                                {r.profilePic ? <img src={r.profilePic} className="w-10 h-10 rounded-full object-cover border"/> : <div className="w-10 h-10 bg-gray-200 rounded-full"/>}
                                                <div>
                                                    <div className="font-bold">{r.fullName}</div>
                                                    <div className="text-xs text-gray-500">{r.mobile}</div>
                                                </div>
                                            </td>
                                            <td className="p-3">
                                                <div className="text-xs">
                                                    <span className="font-bold">Role:</span> {r.playerType} <br/>
                                                    <span className="font-bold">DOB:</span> {r.dob}
                                                </div>
                                                {r.paymentScreenshot && (
                                                    <a href={r.paymentScreenshot} target="_blank" rel="noreferrer" className="text-blue-600 text-xs underline mt-1 block">View Payment</a>
                                                )}
                                            </td>
                                            <td className="p-3">
                                                <span className={`px-2 py-1 rounded text-xs font-bold ${r.status === 'APPROVED' ? 'bg-green-100 text-green-700' : r.status === 'REJECTED' ? 'bg-red-100 text-red-700' : 'bg-yellow-100 text-yellow-700'}`}>
                                                    {r.status}
                                                </span>
                                            </td>
                                            <td className="p-3 text-right">
                                                {r.status === 'PENDING' && (
                                                    <div className="flex justify-end gap-2">
                                                        <button onClick={() => handleApproveRequest(r)} className="text-green-600 hover:bg-green-50 p-1 rounded" title="Approve"><CheckCircle className="w-5 h-5"/></button>
                                                        <button onClick={() => handleRejectRequest(r.id)} className="text-red-600 hover:bg-red-50 p-1 rounded" title="Reject"><XCircle className="w-5 h-5"/></button>
                                                    </div>
                                                )}
                                                {r.status !== 'PENDING' && (
                                                    <button onClick={() => handleDeleteRequest(r.id)} className="text-gray-400 hover:text-red-600"><Trash2 className="w-4 h-4"/></button>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                    {filteredRequests.length === 0 && <tr><td colSpan={4} className="p-6 text-center text-gray-400 italic">No pending requests found.</td></tr>}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {/* CATEGORIES TAB */}
                {activeTab === 'CATEGORIES' && (
                    <div className="bg-white rounded shadow p-4">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-lg font-bold flex items-center gap-2"><Layers className="w-5 h-5"/> Categories</h2>
                            <button onClick={() => openModal({ name: '', basePrice: 20, maxPerTeam: 0, bidIncrement: 10 })} className="bg-blue-600 text-white px-3 py-1.5 rounded text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Category</button>
                        </div>
                        <div className="grid gap-2">
                             {categories.map(c => (
                                 <div key={c.id} className="border p-3 rounded flex justify-between items-center hover:bg-gray-50">
                                     <div>
                                         <h3 className="font-bold text-gray-800">{c.name}</h3>
                                         <p className="text-xs text-gray-500">Base: {c.basePrice} | Max/Team: {c.maxPerTeam > 0 ? c.maxPerTeam : 'No Limit'} | Inc: {c.bidIncrement}</p>
                                     </div>
                                     <div className="flex gap-2">
                                         <button onClick={() => openModal(c)} className="text-blue-500"><Edit className="w-4 h-4"/></button>
                                         <button onClick={() => handleDelete('categories', String(c.id))} className="text-red-500"><Trash2 className="w-4 h-4"/></button>
                                     </div>
                                 </div>
                             ))}
                        </div>
                    </div>
                )}

                {/* ROLES TAB */}
                {activeTab === 'ROLES' && (
                    <div className="bg-white rounded shadow p-4">
                        <div className="flex justify-between items-center mb-4">
                            <h2 className="text-lg font-bold flex items-center gap-2"><Briefcase className="w-5 h-5"/> Player Roles</h2>
                            <button onClick={() => openModal({ name: '' })} className="bg-blue-600 text-white px-3 py-1.5 rounded text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Role</button>
                        </div>
                        <div className="grid gap-2">
                             {roles.length > 0 ? roles.map(r => (
                                 <div key={r.id} className="border p-3 rounded flex justify-between items-center hover:bg-gray-50">
                                     <div>
                                         <h3 className="font-bold text-gray-800">{r.name}</h3>
                                         {r.basePrice ? <p className="text-xs text-gray-500">Default Base: {r.basePrice}</p> : null}
                                     </div>
                                     <div className="flex gap-2">
                                         <button onClick={() => openModal(r)} className="text-blue-500"><Edit className="w-4 h-4"/></button>
                                         <button onClick={() => handleDelete('roles', String(r.id))} className="text-red-500"><Trash2 className="w-4 h-4"/></button>
                                     </div>
                                 </div>
                             )) : <p className="text-gray-400 italic text-center p-4">No roles defined. (e.g. Batsman, Bowler)</p>}
                        </div>
                    </div>
                )}

                {/* SPONSORS TAB */}
                {activeTab === 'SPONSORS' && (
                    <div className="bg-white rounded shadow p-4">
                         <div className="flex justify-between items-center mb-4">
                            <h2 className="text-lg font-bold flex items-center gap-2"><DollarSign className="w-5 h-5"/> Sponsors</h2>
                            <button onClick={() => openModal({ name: '' })} className="bg-blue-600 text-white px-3 py-1.5 rounded text-sm font-bold flex items-center"><Plus className="w-4 h-4 mr-1"/> Add Sponsor</button>
                        </div>
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {sponsors.map(s => (
                                <div key={s.id} className="border rounded p-3 text-center relative group">
                                    <img src={s.imageUrl} className="h-20 w-full object-contain mb-2"/>
                                    <p className="font-bold text-sm text-gray-800">{s.name}</p>
                                    <div className="absolute top-2 right-2 hidden group-hover:flex gap-1 bg-white p-1 rounded shadow">
                                        <button onClick={() => openModal(s)} className="text-blue-500"><Edit className="w-3 h-3"/></button>
                                        <button onClick={() => handleDelete('sponsors', s.id)} className="text-red-500"><Trash2 className="w-3 h-3"/></button>
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                )}

                {/* REGISTRATION TAB */}
                {activeTab === 'REGISTRATION' && (
                    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                        {/* Settings Column */}
                        <div className="lg:col-span-2 space-y-6">
                            {/* General Settings */}
                            <div className="bg-white rounded shadow p-6">
                                <h3 className="font-bold text-gray-800 border-b pb-2 mb-4 flex items-center"><Settings className="w-5 h-5 mr-2"/> General Config</h3>
                                <div className="space-y-4">
                                    <div className="flex items-center justify-between bg-gray-50 p-3 rounded">
                                        <span className="font-semibold">Enable Registration Page</span>
                                        <label className="relative inline-flex items-center cursor-pointer">
                                            <input type="checkbox" className="sr-only peer" checked={regConfig.isEnabled} onChange={e => setRegConfig({...regConfig, isEnabled: e.target.checked})} />
                                            <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-green-600"></div>
                                        </label>
                                    </div>
                                    <div>
                                        <label className="block text-sm font-bold text-gray-600 mb-1">Registration Fee (₹)</label>
                                        <input type="number" className="w-full border rounded p-2" value={regConfig.fee} onChange={e => setRegConfig({...regConfig, fee: Number(e.target.value)})} />
                                    </div>
                                    <div className="flex items-center gap-2">
                                        <input type="checkbox" id="payToggle" checked={regConfig.includePayment} onChange={e => setRegConfig({...regConfig, includePayment: e.target.checked})} className="w-4 h-4"/>
                                        <label htmlFor="payToggle" className="text-sm font-semibold select-none cursor-pointer">Require Payment Screenshot</label>
                                    </div>
                                    {regConfig.includePayment && (
                                        <div className="grid grid-cols-2 gap-4 animate-fade-in">
                                            <div>
                                                <label className="block text-sm font-bold text-gray-600 mb-1">UPI ID</label>
                                                <input type="text" className="w-full border rounded p-2" value={regConfig.upiId} onChange={e => setRegConfig({...regConfig, upiId: e.target.value})} placeholder="e.g. 9876543210@upi" />
                                            </div>
                                            <div>
                                                <label className="block text-sm font-bold text-gray-600 mb-1">Payee Name</label>
                                                <input type="text" className="w-full border rounded p-2" value={regConfig.upiName} onChange={e => setRegConfig({...regConfig, upiName: e.target.value})} placeholder="e.g. John Doe" />
                                            </div>
                                        </div>
                                    )}
                                </div>
                            </div>

                            {/* Terms & Images */}
                            <div className="bg-white rounded shadow p-6">
                                <h3 className="font-bold text-gray-800 border-b pb-2 mb-4 flex items-center"><FileText className="w-5 h-5 mr-2"/> Content & Terms</h3>
                                <div className="space-y-4">
                                    <div>
                                        <label className="block text-sm font-bold text-gray-600 mb-1">Terms & Conditions</label>
                                        <textarea rows={4} className="w-full border rounded p-2 text-sm" value={regConfig.terms} onChange={e => setRegConfig({...regConfig, terms: e.target.value})} />
                                    </div>
                                    <div className="grid grid-cols-2 gap-4">
                                        <div>
                                            <label className="block text-sm font-bold text-gray-600 mb-1">Tournament Banner</label>
                                            <div onClick={() => bannerInputRef.current?.click()} className="border border-dashed p-4 text-center cursor-pointer hover:bg-gray-50 rounded">
                                                {regConfig.bannerUrl ? <img src={regConfig.bannerUrl} className="h-16 mx-auto object-contain" /> : <span className="text-gray-400 text-xs">Upload Banner</span>}
                                                <input ref={bannerInputRef} type="file" className="hidden" accept="image/*" onChange={(e) => handleRegFileChange(e, 'bannerUrl')} />
                                            </div>
                                        </div>
                                        {regConfig.includePayment && (
                                            <div>
                                                <label className="block text-sm font-bold text-gray-600 mb-1">UPI QR Code</label>
                                                <div onClick={() => qrInputRef.current?.click()} className="border border-dashed p-4 text-center cursor-pointer hover:bg-gray-50 rounded">
                                                    {regConfig.qrCodeUrl ? <img src={regConfig.qrCodeUrl} className="h-16 mx-auto object-contain" /> : <div className="flex flex-col items-center text-gray-400 text-xs"><QrCode className="w-6 h-6 mb-1"/>Upload QR</div>}
                                                    <input ref={qrInputRef} type="file" className="hidden" accept="image/*" onChange={(e) => handleRegFileChange(e, 'qrCodeUrl')} />
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Custom Fields Column */}
                        <div className="lg:col-span-1">
                            <div className="bg-white rounded shadow p-6 h-full flex flex-col">
                                <h3 className="font-bold text-gray-800 border-b pb-2 mb-4 flex items-center"><AlignLeft className="w-5 h-5 mr-2"/> Custom Fields</h3>
                                <div className="flex-1 overflow-y-auto mb-4 space-y-2">
                                    {regConfig.customFields.map((field, idx) => (
                                        <div key={idx} className="bg-gray-50 p-2 rounded border flex justify-between items-center text-sm">
                                            <div>
                                                <p className="font-bold">{field.label}</p>
                                                <p className="text-xs text-gray-500 uppercase">{field.type} {field.required ? '(Required)' : ''}</p>
                                            </div>
                                            <button onClick={() => removeCustomField(idx)} className="text-red-500 hover:bg-red-100 p-1 rounded"><Trash2 className="w-4 h-4"/></button>
                                        </div>
                                    ))}
                                    {regConfig.customFields.length === 0 && <p className="text-gray-400 text-sm italic text-center py-4">No custom fields added.</p>}
                                </div>
                                <div className="bg-gray-100 p-3 rounded border">
                                    <input type="text" placeholder="Field Label (e.g. Jersey No)" className="w-full border rounded p-1.5 text-sm mb-2" value={newField.label} onChange={e => setNewField({...newField, label: e.target.value})} />
                                    <div className="flex gap-2 mb-2">
                                        <select className="flex-1 border rounded p-1.5 text-sm" value={newField.type} onChange={e => setNewField({...newField, type: e.target.value as any})}>
                                            <option value="text">Text</option>
                                            <option value="number">Number</option>
                                            <option value="date">Date</option>
                                            <option value="file">File Upload</option>
                                            <option value="select">Dropdown</option>
                                        </select>
                                        {newField.type === 'select' && <span className="text-xs text-red-500 flex items-center" title="Options managed in code for now">*</span>}
                                    </div>
                                    <label className="flex items-center gap-2 text-sm text-gray-700 mb-2">
                                        <input type="checkbox" checked={newField.required} onChange={e => setNewField({...newField, required: e.target.checked})} /> Required
                                    </label>
                                    <button onClick={addCustomField} className="w-full bg-blue-600 text-white text-xs font-bold py-2 rounded">Add Field</button>
                                </div>
                            </div>
                        </div>

                        {/* Save Button */}
                        <div className="lg:col-span-3">
                            <button onClick={handleSaveRegistrationConfig} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-4 rounded shadow-lg flex items-center justify-center text-lg">
                                <Save className="w-6 h-6 mr-2" /> Save Configuration
                            </button>
                        </div>
                    </div>
                )}

            </main>

            {/* MODALS */}
            {isEditing && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-lg p-6 w-full max-w-md max-h-[90vh] overflow-y-auto">
                        <div className="flex justify-between items-center mb-4">
                            <h3 className="text-lg font-bold text-gray-900">
                                {editItem.id ? 'Edit' : 'Add'} {activeTab === 'ROLES' ? 'Role' : activeTab.slice(0, -1)}
                            </h3>
                            <button onClick={closeModal}><X className="w-5 h-5 text-gray-500"/></button>
                        </div>

                        <form onSubmit={activeTab === 'TEAMS' ? handleSaveTeam : activeTab === 'PLAYERS' ? handleSavePlayer : activeTab === 'CATEGORIES' ? handleSaveCategory : activeTab === 'SPONSORS' ? handleSaveSponsor : handleSaveRole} className="space-y-4">

                            {/* COMMON NAME FIELD */}
                            <div>
                                <label className="block text-xs font-bold text-gray-500 mb-1">Name</label>
                                <input required type="text" className="w-full border rounded p-2 text-gray-900" value={editItem.name} onChange={e => setEditItem({...editItem, name: e.target.value})} />
                            </div>

                            {/* IMAGE UPLOAD (Teams, Players, Sponsors) */}
                            {(activeTab === 'TEAMS' || activeTab === 'PLAYERS' || activeTab === 'SPONSORS') && (
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">Image</label>
                                    <div onClick={() => fileInputRef.current?.click()} className="border border-dashed rounded p-4 text-center cursor-pointer hover:bg-gray-50">
                                        {previewImage ? <img src={previewImage} className="h-20 mx-auto object-contain"/> : <div className="text-gray-400"><Upload className="w-6 h-6 mx-auto mb-1"/>Upload Image</div>}
                                    </div>
                                    <input ref={fileInputRef} type="file" className="hidden" accept="image/*" onChange={handleFileChange} />
                                </div>
                            )}

                            {/* TEAMS SPECIFIC */}
                            {activeTab === 'TEAMS' && (
                                <>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">Budget</label>
                                        <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.budget} onChange={e => setEditItem({...editItem, budget: e.target.value})} />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">Login Password</label>
                                        <input type="text" className="w-full border rounded p-2 text-gray-900" value={editItem.password} onChange={e => setEditItem({...editItem, password: e.target.value})} placeholder="Optional" />
                                    </div>
                                </>
                            )}

                            {/* PLAYERS SPECIFIC */}
                            {activeTab === 'PLAYERS' && (
                                <>
                                    <div className="grid grid-cols-2 gap-2">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">Role</label>
                                            <select className="w-full border rounded p-2 text-gray-900" value={editItem.role} onChange={e => setEditItem({...editItem, role: e.target.value})}>
                                                <option value="Batsman">Batsman</option>
                                                <option value="Bowler">Bowler</option>
                                                <option value="All Rounder">All Rounder</option>
                                                <option value="Wicket Keeper">Wicket Keeper</option>
                                                {roles.map(r => <option key={r.id} value={r.name}>{r.name}</option>)}
                                            </select>
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">Category</label>
                                            <select className="w-full border rounded p-2 text-gray-900" value={editItem.category} onChange={e => setEditItem({...editItem, category: e.target.value})}>
                                                <option value="Uncapped">Uncapped</option>
                                                {categories.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                                            </select>
                                        </div>
                                    </div>
                                    <div>
                                        <label className="block text-xs font-bold text-gray-500 mb-1">Base Price</label>
                                        <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.basePrice} onChange={e => setEditItem({...editItem, basePrice: e.target.value})} />
                                    </div>
                                </>
                            )}

                            {/* CATEGORIES SPECIFIC */}
                            {activeTab === 'CATEGORIES' && (
                                <>
                                    <div className="grid grid-cols-2 gap-2">
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">Base Price</label>
                                            <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.basePrice} onChange={e => setEditItem({...editItem, basePrice: e.target.value})} />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">Max Per Team</label>
                                            <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.maxPerTeam} onChange={e => setEditItem({...editItem, maxPerTeam: e.target.value})} />
                                        </div>
                                        <div>
                                            <label className="block text-xs font-bold text-gray-500 mb-1">Bid Increment</label>
                                            <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.bidIncrement} onChange={e => setEditItem({...editItem, bidIncrement: e.target.value})} />
                                        </div>
                                    </div>
                                </>
                            )}

                            {/* ROLES SPECIFIC */}
                            {activeTab === 'ROLES' && (
                                <div>
                                    <label className="block text-xs font-bold text-gray-500 mb-1">Default Base Price (Optional)</label>
                                    <input type="number" className="w-full border rounded p-2 text-gray-900" value={editItem.basePrice || 0} onChange={e => setEditItem({...editItem, basePrice: e.target.value})} placeholder="0" />
                                </div>
                            )}

                            <button type="submit" className="w-full bg-blue-600 text-white font-bold py-2 rounded hover:bg-blue-700 shadow">Save</button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
};

export default AuctionManage;

import React, { useState } from 'react';
import { Mail, Lock, LogIn, ArrowLeft, Key, Hash, Info, AlertTriangle, User, Chrome, RefreshCw } from 'lucide-react';
import { auth, db } from '../firebase';
import firebase from 'firebase/compat/app';
import { useAuction } from '../hooks/useAuction';
import { Link, useNavigate } from 'react-router-dom';

const AuthScreen: React.FC = () => {
    const { setUserProfile } = useAuction();
    const navigate = useNavigate();
    const [activeTab, setActiveTab] = useState<'team' | 'admin'>('team');

    // Admin State
    const [adminName, setAdminName] = useState('');
    const [adminEmail, setAdminEmail] = useState('');
    const [adminPassword, setAdminPassword] = useState('');
    const [isAdminRegister, setIsAdminRegister] = useState(false);

    // Forgot Password State
    const [showForgotPassword, setShowForgotPassword] = useState(false);
    const [resetEmail, setResetEmail] = useState('');
    const [resetMessage, setResetMessage] = useState<string | null>(null);

    // Team State
    const [selectedTeamId, setSelectedTeamId] = useState<string>("");
    const [teamPassword, setTeamPassword] = useState('');

    const [error, setError] = useState<string | null>(null);
    const [isConfigError, setIsConfigError] = useState(false);
    const [configErrorMsg, setConfigErrorMsg] = useState("");
    const [isLoading, setIsLoading] = useState(false);

    const getFriendlyErrorMessage = (err: any) => {
        const code = err.code;
        console.error("Auth Error:", code, err.message);

        if (code === 'auth/configuration-not-found' || code === 'auth/operation-not-allowed') {
            setIsConfigError(true);
            return "Firebase Authentication provider is disabled.";
        }
        if (code === 'auth/admin-restricted-operation') {
            setIsConfigError(true);
            if (activeTab === 'team') {
                setConfigErrorMsg("Anonymous Authentication is disabled.");
                return "Team Login requires Anonymous Auth to be enabled.";
            } else {
                setConfigErrorMsg("Create (sign-up) is disabled.");
                return "Client-side sign-up is disabled.";
            }
        }
        if (code === 'auth/invalid-credential' || code === 'auth/wrong-password') {
            return "Incorrect Email or Password.";
        }
        if (code === 'auth/user-not-found') {
            return "User not found. Please register first.";
        }
        if (code === 'auth/email-already-in-use') {
            return "This email is already currently used by another account.";
        }
        if (code === 'auth/weak-password') {
            return "Password should be at least 6 characters.";
        }
        if (code === 'auth/popup-closed-by-user') {
            return "Sign-in popup was closed.";
        }
        return err.message || "An unknown error occurred.";
    };

    const handleGoogleLogin = async () => {
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);
        try {
            const provider = new firebase.auth.GoogleAuthProvider();
            await auth.signInWithPopup(provider);
            // App.tsx auth listener will handle redirection
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handlePasswordReset = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!resetEmail) {
            setError("Please enter your email address.");
            return;
        }
        setError(null);
        setIsLoading(true);
        try {
            await auth.sendPasswordResetEmail(resetEmail);
            setResetMessage("Password reset email sent! Check your inbox.");
            setIsLoading(false);
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handleAdminSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);

        try {
            await auth.signOut();

            if (isAdminRegister) {
                if (!adminName.trim()) {
                    throw new Error("Full Name is required for registration.");
                }
                const userCredential = await auth.createUserWithEmailAndPassword(adminEmail, adminPassword);
                if (userCredential.user) {
                    await userCredential.user.updateProfile({
                        displayName: adminName
                    });
                }
            } else {
                await auth.signInWithEmailAndPassword(adminEmail, adminPassword);
            }
        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    };

    const handleTeamSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError(null);
        setIsConfigError(false);
        setIsLoading(true);

        try {
            const auctionsSnapshot = await db.collection('auctions').get();

            if (auctionsSnapshot.empty) {
                throw new Error("No auctions found.");
            }

            let matchedTeam: any = null;
            let auctionId: string = "";

            for (const doc of auctionsSnapshot.docs) {
                const teamQuery = await doc.ref.collection('teams').where('id', '==', selectedTeamId).limit(1).get();
                if (!teamQuery.empty) {
                    matchedTeam = teamQuery.docs[0].data();
                    auctionId = doc.id;
                    break;
                }
            }

            if (!matchedTeam) {
                throw new Error("Team ID not found.");
            }

            if (matchedTeam.password && matchedTeam.password !== teamPassword) {
                throw new Error("Incorrect Password.");
            }

            const sessionData = {
                role: 'TEAM_OWNER',
                teamId: selectedTeamId,
                auctionId: auctionId
            };
            localStorage.setItem('sm_sports_team_session', JSON.stringify(sessionData));

            await auth.signOut();
            await auth.signInAnonymously();
            navigate(`/auction/${auctionId}`);

        } catch (err: any) {
            setError(getFriendlyErrorMessage(err));
            setIsLoading(false);
        }
    }

    return (
        <div className="min-h-screen bg-primary font-sans flex items-center justify-center p-4 bg-[url('https://images.unsplash.com/photo-1531415074968-036ba1b575da?q=80&w=2067&auto=format&fit=crop')] bg-cover bg-center bg-no-repeat relative">
            <div className="absolute inset-0 bg-primary/90 backdrop-blur-sm"></div>

            <div className="w-full max-w-md relative z-10">
                <Link to="/" className="inline-flex items-center text-text-secondary hover:text-white mb-6 transition-colors">
                    <ArrowLeft className="w-4 h-4 mr-2" /> Back to Home
                </Link>

                <div className="text-center mb-8">
                    <h1 className="text-5xl font-bold text-highlight mb-2">🏏 SM SPORTS</h1>
                    <p className="text-text-secondary uppercase tracking-widest text-sm">Your Streaming Partner</p>
                </div>

                <div className="bg-secondary/80 backdrop-blur-md p-8 rounded-2xl shadow-2xl border border-accent">

                    {/* Tabs */}
                    <div className="flex mb-6 bg-primary/50 rounded-lg p-1">
                        <button 
                            onClick={() => { setActiveTab('team'); setError(null); setIsConfigError(false); setShowForgotPassword(false); }}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'team' ? 'bg-highlight text-primary shadow-lg' : 'text-text-secondary hover:text-white'}`}
                        >
                            Team Owner
                        </button>
                        <button 
                            onClick={() => { setActiveTab('admin'); setError(null); setIsConfigError(false); setShowForgotPassword(false); }}
                            className={`flex-1 py-2 rounded-md text-sm font-bold transition-all ${activeTab === 'admin' ? 'bg-highlight text-primary shadow-lg' : 'text-text-secondary hover:text-white'}`}
                        >
                            Admin
                        </button>
                    </div>

                    <h2 className="text-xl font-bold text-center text-white mb-6">
                        {activeTab === 'team' ? 'Team Terminal Access' : (showForgotPassword ? 'Reset Password' : (isAdminRegister ? 'Create Admin Account' : 'Administrator Login'))}
                    </h2>

                    {/* Critical Config Error Alert */}
                    {isConfigError && (
                        <div className="bg-yellow-500/20 border border-yellow-500 text-yellow-200 p-4 rounded-lg mb-6 text-sm">
                            <div className="flex items-center font-bold mb-2 text-yellow-400">
                                <AlertTriangle className="w-4 h-4 mr-2" /> SETUP REQUIRED
                            </div>
                            <p className="mb-2 font-semibold">{configErrorMsg || "Configuration missing in Firebase."}</p>
                            <ol className="list-decimal list-inside space-y-1 text-xs text-yellow-100/80">
                                <li>Go to <a href="https://console.firebase.google.com" target="_blank" className="underline hover:text-white">Firebase Console</a> &gt; <b>Authentication</b></li>
                                <li>Click <b>Sign-in method</b> tab</li>
                                {activeTab === 'team' ? (
                                     <li>Enable <b>Anonymous</b> provider and Save.</li>
                                ) : (
                                     <li>Enable <b>Email/Password</b> and <b>Google</b> providers.</li>
                                )}
                            </ol>
                        </div>
                    )}

                    {/* Forgot Password Message */}
                    {resetMessage && (
                        <div className="bg-green-500/20 border border-green-500 text-green-200 p-3 rounded-lg mb-4 text-sm text-center">
                            {resetMessage}
                        </div>
                    )}

                    {activeTab === 'team' ? (
                        <form onSubmit={handleTeamSubmit} className="space-y-5">
                            <div className="relative">
                                <Hash className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                <input
                                    type="text"
                                    placeholder="Enter Team ID (e.g., T001)"
                                    value={selectedTeamId}
                                    onChange={(e) => setSelectedTeamId(e.target.value.toUpperCase())}
                                    className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50 uppercase"
                                    required
                                />
                            </div>

                            <div className="relative">
                                <Key className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                <input
                                    type="password"
                                    placeholder="Team Password"
                                    value={teamPassword}
                                    onChange={(e) => setTeamPassword(e.target.value)}
                                    required
                                    className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50"
                                />
                            </div>

                            {error && !isConfigError && <p className="text-red-400 text-sm text-center bg-red-400/10 py-2 rounded">{error}</p>}

                            <button
                                type="submit"
                                disabled={isLoading}
                                className="w-full flex items-center justify-center bg-highlight hover:bg-teal-400 text-primary font-extrabold py-4 px-6 rounded-lg transition-all duration-300 transform hover:scale-[1.02] disabled:opacity-50 shadow-[0_0_15px_rgba(56,178,172,0.5)]"
                            >
                               <LogIn className="mr-2 h-5 w-5"/> {isLoading ? 'VERIFYING...' : 'ENTER AUCTION'}
                            </button>
                        </form>
                    ) : showForgotPassword ? (
                         // FORGOT PASSWORD FORM
                         <form onSubmit={handlePasswordReset} className="space-y-5 animate-fade-in">
                            <div className="relative">
                                <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                <input
                                    type="email"
                                    placeholder="Enter your registered email"
                                    value={resetEmail}
                                    onChange={(e) => setResetEmail(e.target.value)}
                                    required
                                    className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50"
                                />
                            </div>

                            {error && !isConfigError && <p className="text-red-400 text-sm text-center bg-red-400/10 py-2 rounded">{error}</p>}

                            <button
                                type="submit"
                                disabled={isLoading}
                                className="w-full flex items-center justify-center bg-highlight hover:bg-teal-400 text-primary font-extrabold py-3 px-6 rounded-lg transition-all"
                            >
                               {isLoading ? 'SENDING...' : 'SEND RESET LINK'}
                            </button>

                            <button
                                type="button"
                                onClick={() => setShowForgotPassword(false)}
                                className="w-full text-sm text-text-secondary hover:text-white"
                            >
                                Back to Login
                            </button>
                         </form>
                    ) : (
                        // ADMIN LOGIN / REGISTER FORM
                        <div className="space-y-5 animate-slide-up">
                             <button
                                onClick={handleGoogleLogin}
                                disabled={isLoading}
                                className="w-full flex items-center justify-center bg-white hover:bg-gray-100 text-gray-800 font-bold py-3 px-6 rounded-lg transition-all shadow-md mb-4"
                            >
                                <Chrome className="mr-2 h-5 w-5 text-red-500" />
                                Sign in with Google
                            </button>

                            <div className="relative flex py-1 items-center">
                                <div className="flex-grow border-t border-gray-600"></div>
                                <span className="flex-shrink-0 mx-4 text-gray-400 text-xs uppercase">Or with Email</span>
                                <div className="flex-grow border-t border-gray-600"></div>
                            </div>

                            <form onSubmit={handleAdminSubmit} className="space-y-4">
                                {isAdminRegister && (
                                    <div className="relative animate-fade-in">
                                        <User className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                        <input
                                            type="text"
                                            placeholder="Full Name"
                                            value={adminName}
                                            onChange={(e) => setAdminName(e.target.value)}
                                            required={isAdminRegister}
                                            className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50"
                                        />
                                    </div>
                                )}
                                <div className="relative">
                                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                    <input
                                        type="email"
                                        placeholder="Admin Email"
                                        value={adminEmail}
                                        onChange={(e) => setAdminEmail(e.target.value)}
                                        required
                                        className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50"
                                    />
                                </div>
                                <div>
                                    <div className="relative">
                                        <Lock className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-text-secondary" />
                                        <input
                                            type="password"
                                            placeholder="Password"
                                            value={adminPassword}
                                            onChange={(e) => setAdminPassword(e.target.value)}
                                            required
                                            className="w-full bg-primary border border-gray-600 rounded-lg py-3 pl-10 pr-4 text-text-main focus:outline-none focus:ring-2 focus:ring-highlight placeholder-text-secondary/50"
                                        />
                                    </div>
                                    {!isAdminRegister && (
                                        <div className="text-right mt-2">
                                            <button 
                                                type="button" 
                                                onClick={() => { setShowForgotPassword(true); setError(null); setResetMessage(null); }}
                                                className="text-xs text-text-secondary hover:text-highlight transition-colors"
                                            >
                                                Forgot Password?
                                            </button>
                                        </div>
                                    )}
                                </div>

                                {error && !isConfigError && <p className="text-red-400 text-sm text-center bg-red-400/10 py-2 rounded">{error}</p>}

                                <button
                                    type="submit"
                                    disabled={isLoading}
                                    className="w-full flex items-center justify-center bg-highlight hover:bg-teal-400 text-primary font-extrabold py-4 px-6 rounded-lg transition-all duration-300 transform hover:scale-[1.02] disabled:opacity-50 shadow-[0_0_15px_rgba(56,178,172,0.5)]"
                                >
                                <LogIn className="mr-2 h-5 w-5"/> {isLoading ? 'CONNECTING...' : isAdminRegister ? 'REGISTER ADMIN' : 'LOGIN ADMIN'}
                                </button>

                                <div className="text-center mt-4">
                                    <button
                                        type="button"
                                        onClick={() => { setIsAdminRegister(!isAdminRegister); setError(null); setIsConfigError(false); }}
                                        className="text-xs text-text-secondary hover:text-highlight underline"
                                    >
                                        {isAdminRegister ? 'Back to Login' : 'Register new Admin?'}
                                    </button>
                                </div>
                            </form>
                        </div>
                    )}

                    {/* Demo Credentials Box */}
                    <div className="mt-8 bg-primary/40 p-4 rounded-lg border border-white/5 text-xs text-text-secondary">
                        <div className="flex items-center mb-2 text-highlight font-bold">
                            <Info className="w-3 h-3 mr-1" /> CREDENTIALS INFO
                        </div>
                        <ul className="space-y-1 list-disc list-inside text-gray-400">
                            <li><span className="text-white font-semibold">Admin:</span> Use Google Sign-in or register an email.</li>
                            <li><span className="text-white font-semibold">Team Owner:</span> Use the <span className="text-highlight">Team ID</span> (e.g. T001) and <span className="text-highlight">Password</span> provided by Admin.</li>
                        </ul>
                    </div>

                </div>
            </div>
        </div>
    );
};

export default AuthScreen;

import React, { useState, useEffect, useMemo } from 'react';
import { useAuction } from '../hooks/useAuction';
import { AuctionStatus, Team, Player, ProjectorLayout, OBSLayout } from '../types';
import TeamStatusCard from '../components/TeamStatusCard';
import { Play, Check, X, ArrowLeft, Loader2, RotateCcw, AlertOctagon, DollarSign, Cast, Lock, Unlock, Monitor, ChevronDown, Shuffle, Search, User, Palette, Trophy, Gavel, Wallet } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const LiveAdminPanel: React.FC = () => {
  const { state, sellPlayer, passPlayer, startAuction, endAuction, resetAuction, resetCurrentPlayer, resetUnsoldPlayers, updateBiddingStatus, toggleSelectionMode, updateTheme, activeAuctionId, placeBid, nextBid } = useAuction();
  const { teams, players, biddingStatus, playerSelectionMode, categories } = state;
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(false);

  // Inline Sell State
  const [isSellingMode, setIsSellingMode] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string>('');
  const [finalPrice, setFinalPrice] = useState<number>(0);

  // Manual Player Selection State
  const [manualPlayerId, setManualPlayerId] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState(''); // New search state

  // Auto-fill price and leader when entering sell mode or when bid updates
  useEffect(() => {
      // 1. Determine Price
      if (state.currentBid !== null && state.currentBid > 0) {
          setFinalPrice(Number(state.currentBid));
      } else if (state.currentPlayerId) {
          // Fallback to Base Price if no bids
          const p = players.find(player => String(player.id) === String(state.currentPlayerId));
          if (p) setFinalPrice(p.basePrice);
      }

      // 2. Determine Team
      if (state.highestBidder) {
          setSelectedTeamId(String(state.highestBidder.id));
      } else if (!isSellingMode) {
          // Reset selection only if we aren't currently editing
          setSelectedTeamId('');
      }
  }, [state.currentBid, state.highestBidder, isSellingMode, state.currentPlayerId, players]);

  const handleStart = async (specificId?: string) => {
      if (teams.length === 0) {
          alert("Cannot start auction: No teams added. Please go back to Dashboard > Edit Auction > Teams to add teams.");
          return;
      }

      const availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
      if (availablePlayers.length === 0) {
          alert("Cannot start auction: No more players available.");
          return;
      }

      setIsProcessing(true);
      const hasNextPlayer = await startAuction(specificId);

      if (!hasNextPlayer) {
          if (window.confirm("No more players available in the pool.\n\nDo you want to MARK AUCTION AS COMPLETED?")) {
              await endAuction();
          }
      } else {
          // Clear manual selection
          setManualPlayerId('');
          setSearchTerm('');
      }
      setIsProcessing(false);
  }

  const handleResetFull = async () => {
      if(!window.confirm("WARNING: This will reset the auction status to 'Not Started'. It will NOT remove sold players from teams. Proceed?")) return;
      setIsProcessing(true);
      await resetAuction();
      setIsProcessing(false);
  }

  const handleResetPlayer = async () => {
      if(!window.confirm("This will clear the current bid and timer for this player. Proceed?")) return;
      setIsProcessing(true);
      await resetCurrentPlayer();
      setIsProcessing(false);
  }

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!activeAuctionId) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      const url = `${baseUrl}#/${route}/${activeAuctionId}`;
      navigator.clipboard.writeText(url);

      if (type === 'green') {
          alert("PROJECTOR VIEW URL Copied!\n\nOpen this link on the projector screen.");
      } else {
          alert("OBS OVERLAY URL Copied!\n\nPaste this into OBS Browser Source.");
      }
  };

  const handleSellClick = () => {
      setIsSellingMode(true);
  };

  const cancelSell = () => {
      setIsSellingMode(false);
  };

  const confirmSell = async () => {
      if (!selectedTeamId) {
          alert("Please select a team to sell to.");
          return;
      }
      if (finalPrice <= 0) {
          alert("Price must be greater than 0.");
          return;
      }

      setIsProcessing(true);
      try {
          await sellPlayer(selectedTeamId, finalPrice);
          setIsSellingMode(false);
      } catch(e) {
          console.error(e);
          alert("Failed to sell player. Check console.");
      } finally {
          setIsProcessing(false);
      }
  };

  const handlePass = async () => {
      if (window.confirm("Confirm UNSOLD?")) {
          setIsProcessing(true);
          await passPlayer();
          setIsProcessing(false);
      }
  }

  const handleQuickBid = async (teamId: string | number) => {
      try {
          await placeBid(teamId, nextBid);
      } catch (e) {
          console.error(e);
      }
  };

  const selectedPlayerObj = players.find(p => p.id === manualPlayerId);
  const currentPlayer = state.currentPlayerIndex !== null ? state.unsoldPlayers[state.currentPlayerIndex] : null;

  // Helper to check category limits
  const isTeamLimitReached = (team: Team) => {
      if (!currentPlayer || !currentPlayer.category) return false;
      const catConfig = categories.find(c => c.name === currentPlayer.category);
      if (catConfig && catConfig.maxPerTeam > 0) {
          const count = team.players.filter(p => p.category === currentPlayer.category).length;
          return count >= catConfig.maxPerTeam;
      }
      return false;
  };

  const getControlButtons = () => {
      const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
      const availablePlayersCount = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD').length;
      const isStartDisabled = isProcessing || (state.status === AuctionStatus.NotStarted && (teams.length === 0 || availablePlayersCount === 0));
      const unsoldCount = players.filter(p => p.status === 'UNSOLD').length;

      // NEW: Finish Auction Option
      // Show this if no players are left AND we are not currently bidding on one (isRoundActive is false)
      if (availablePlayersCount === 0 && state.status !== AuctionStatus.NotStarted && !isRoundActive) {
          return (
             <div className="space-y-4 animate-fade-in">
                 {unsoldCount > 0 && (
                     <div className="bg-blue-900/30 border border-blue-500/50 p-4 rounded-xl text-center shadow-inner">
                        <h3 className="text-white font-bold text-lg mb-2">Unsold Players Available</h3>
                        <p className="text-gray-300 text-xs mb-4">There are {unsoldCount} unsold players. Do you want to bring them back into the bidding pool?</p>
                        <button 
                            onClick={async () => {
                                if(window.confirm(`Bring back ${unsoldCount} unsold players to the pool?`)) {
                                    setIsProcessing(true);
                                    await resetUnsoldPlayers();
                                    setIsProcessing(false);
                                }
                            }}
                            disabled={isProcessing}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 rounded-lg shadow-lg transition-all active:scale-95 flex items-center justify-center"
                        >
                            {isProcessing ? <Loader2 className="mr-2 h-4 w-4 animate-spin"/> : <RotateCcw className="mr-2 h-4 w-4"/>}
                            BRING BACK UNSOLD ({unsoldCount})
                        </button>
                     </div>
                 )}

                 <div className="bg-green-900/30 border border-green-500/50 p-6 rounded-xl text-center shadow-inner">
                    <Trophy className="w-12 h-12 text-yellow-400 mx-auto mb-3 drop-shadow-lg" />
                    <h3 className="text-white font-bold text-xl mb-2">Auction Completed!</h3>
                    <p className="text-gray-300 text-sm mb-6">All players have been auctioned. You can now finalize the event.</p>
                    <button 
                        onClick={async () => {
                            if(window.confirm("Are you sure you want to finish the auction? This will enable the summary view for all users.")) {
                                setIsProcessing(true);
                                await endAuction();
                                setIsProcessing(false);
                            }
                        }}
                        disabled={isProcessing}
                        className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-lg shadow-lg shadow-green-900/20 transition-all active:scale-95 flex items-center justify-center tracking-wide"
                    >
                        {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : "GENERATE SUMMARY & FINISH"}
                    </button>
                </div>
            </div>
          );
      }

      // 1. ACTIVE ROUND CONTROLS (SOLD / UNSOLD)
      if (isRoundActive) {
          if (isSellingMode) {
              return (
                  <div className="bg-primary/20 p-3 rounded-lg border border-gray-600 animate-fade-in space-y-3">
                      <div className="flex items-center gap-2 mb-2 text-white font-bold border-b border-gray-600 pb-1">
                          <Check className="w-4 h-4 text-green-500" /> Confirm Sale
                      </div>

                      {/* Inline Form */}
                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Sold To Team</label>
                          <div className="relative">
                            <select 
                                value={selectedTeamId} 
                                onChange={(e) => setSelectedTeamId(e.target.value)}
                                className="w-full bg-primary border border-gray-600 rounded p-2 text-sm text-white outline-none focus:border-green-500 appearance-none"
                            >
                                <option value="">-- Select Team --</option>
                                {teams.map(t => (
                                    <option key={t.id} value={t.id}>{t.name} ({t.budget})</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                          </div>
                      </div>

                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Final Price</label>
                          <div className="relative">
                              <DollarSign className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />
                              <input 
                                type="number" 
                                value={finalPrice} 
                                onChange={(e) => setFinalPrice(Number(e.target.value))}
                                className="w-full bg-primary border border-gray-600 rounded p-2 pl-8 text-sm text-white font-bold outline-none focus:border-green-500"
                              />
                          </div>
                      </div>

                      <div className="flex gap-2 pt-1">
                          <button 
                            onClick={cancelSell}
                            className="flex-1 bg-gray-600 hover:bg-gray-700 text-white py-2 rounded text-sm font-bold transition-colors"
                          >
                              Cancel
                          </button>
                          <button 
                            onClick={confirmSell}
                            disabled={isProcessing}
                            className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 rounded text-sm font-bold shadow-lg flex items-center justify-center transition-colors"
                          >
                              {isProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Confirm'}
                          </button>
                      </div>
                  </div>
              );
          }

          return (
              <div className="grid grid-cols-2 gap-3">
                  <button 
                    onClick={handleSellClick}
                    disabled={isProcessing}
                    className="flex flex-col items-center justify-center bg-green-600 hover:bg-green-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                  >
                      {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <Check className="mb-1 h-6 w-6"/>}
                      {isProcessing ? 'SELLING...' : 'SOLD'}
                  </button>
                  <button 
                    onClick={handlePass}
                    disabled={isProcessing}
                    className="flex flex-col items-center justify-center bg-red-600 hover:bg-red-700 disabled:bg-gray-700 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                  >
                      {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <X className="mb-1 h-6 w-6"/>}
                      UNSOLD
                  </button>
              </div>
          );
      }

      // 2. NEXT PLAYER SELECTION (Based on Mode)
      if (playerSelectionMode === 'MANUAL') {
           const availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
           availablePlayers.sort((a, b) => a.name.localeCompare(b.name));

           // Filter based on search term
           const filteredPlayers = availablePlayers.filter(p => 
               p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
               p.category.toLowerCase().includes(searchTerm.toLowerCase())
           );

           return (
               <div className="space-y-3 bg-primary/20 p-3 rounded-lg border border-gray-600">
                   <div>
                       <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Select Next Player</label>

                       {/* Search Input */}
                       <div className="relative mb-2">
                           <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                           <input 
                                type="text"
                                className="w-full bg-gray-900 border border-gray-700 rounded p-1.5 pl-7 text-xs text-white focus:border-highlight outline-none"
                                placeholder="Search player name..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                           />
                       </div>

                       <div className="relative">
                           <select 
                               className="w-full bg-gray-900 text-white text-xs p-3 rounded border border-gray-700 focus:border-highlight outline-none appearance-none cursor-pointer"
                               value={manualPlayerId}
                               onChange={(e) => setManualPlayerId(e.target.value)}
                           >
                               <option value="">-- Choose Player ({filteredPlayers.length}) --</option>
                               {filteredPlayers.map(p => (
                                   <option key={p.id} value={p.id}>
                                       {p.name} ({p.category}) - Base: {p.basePrice}
                                   </option>
                               ))}
                           </select>
                           <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" />
                       </div>
                   </div>

                   <button 
                     onClick={() => handleStart(manualPlayerId)} 
                     disabled={isStartDisabled || !manualPlayerId}
                     className={`w-full flex items-center justify-center font-bold py-3 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                         ${isStartDisabled || !manualPlayerId
                             ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                             : 'bg-highlight hover:bg-teal-500 text-primary'}`
                     }
                   >
                       {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Play className="mr-2 h-5 w-5"/>} 
                       Start Bidding
                   </button>
               </div>
           );
      }

      // AUTO MODE
      return (
          <button 
            onClick={() => handleStart()} 
            disabled={isStartDisabled}
            className={`w-full flex items-center justify-center font-bold py-4 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                ${isStartDisabled 
                    ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                    : 'bg-highlight hover:bg-teal-500 text-primary'}`
            }
          >
              {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Shuffle className="mr-2 h-5 w-5"/>} 
              {state.status === AuctionStatus.NotStarted ? 'Start Auction (Auto Random)' : 'Next Random Player'}
          </button>
      );
  }

  return (
    <div className="bg-secondary p-4 rounded-lg shadow-lg h-full flex flex-col border border-gray-700 relative">

      <div className="flex justify-between items-center mb-4 border-b border-accent pb-2">
          <div className="flex flex-col gap-2 w-full">
              <div className="flex justify-between items-center w-full">
                <h2 className="text-xl font-bold text-highlight uppercase tracking-wider">Auctioneer</h2>
                <button onClick={() => navigate('/admin')} className="text-xs text-text-secondary hover:text-white flex items-center">
                    <ArrowLeft className="w-3 h-3 mr-1"/> Dashboard
                </button>
              </div>

              {/* Quick Actions & Theme Selectors */}
              <div className="flex flex-wrap gap-2 items-center bg-primary/50 rounded-lg p-2 w-full">
                  <div className="flex items-center gap-1">
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('transparent'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-highlight transition-colors"
                        title="Copy OBS Transparent Link"
                    >
                        <Cast className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('green'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-green-400 transition-colors"
                        title="Copy Projector View Link"
                    >
                        <Monitor className="w-4 h-4" />
                    </button>

                    {/* Bidding Dropdown */}
                    <div className="relative ml-1">
                        <select
                            value={biddingStatus === 'ON' ? 'ON' : 'OFF'}
                            onChange={(e) => {
                                const newVal = e.target.value === 'ON';
                                updateBiddingStatus(newVal ? 'ON' : 'PAUSED');
                            }}
                            className={`appearance-none pl-6 pr-6 py-1 rounded text-xs font-bold border outline-none cursor-pointer ${biddingStatus === 'ON' ? 'bg-green-900/30 text-green-400 border-green-500/50' : 'bg-red-900/30 text-red-400 border-red-500/50'}`}
                        >
                            <option value="ON">BIDDING ON</option>
                            <option value="OFF">BIDDING PAUSED</option>
                        </select>
                        <div className="absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none">
                            {biddingStatus === 'ON' ? <Unlock className="w-3 h-3 text-green-400"/> : <Lock className="w-3 h-3 text-red-400"/>}
                        </div>
                    </div>
                  </div>

                  <div className="w-px h-6 bg-gray-600 mx-1"></div>

                  {/* Theme Selectors with Clearer Labels */}
                  <div className="flex flex-1 gap-2">
                      <div className="flex-1">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">Projector</label>
                          <select 
                            value={state.projectorLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('PROJECTOR', e.target.value)}
                            className="w-full bg-gray-800 text-white text-xs p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="IPL">Gold/Blue</option>
                              <option value="MODERN">Modern</option>
                          </select>
                      </div>
                      <div className="flex-1">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">OBS</label>
                          <select 
                            value={state.obsLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('OBS', e.target.value)}
                            className="w-full bg-gray-800 text-white text-xs p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="MINIMAL">Minimal</option>
                              <option value="VERTICAL">Vertical</option>
                          </select>
                      </div>
                  </div>
              </div>
          </div>
      </div>

      {/* SELECTION MODE TOGGLE */}
      <div className="bg-primary/40 rounded-lg p-2 mb-4 flex justify-between items-center border border-gray-700">
          <span className="text-xs font-bold text-text-secondary uppercase ml-1">Selection Mode</span>
          <div className="flex bg-gray-800 rounded p-1">
              <button 
                onClick={playerSelectionMode !== 'MANUAL' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'MANUAL' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Manual
              </button>
              <button 
                onClick={playerSelectionMode !== 'AUTO' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'AUTO' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Auto
              </button>
          </div>
      </div>

      <div className="mb-6 space-y-3">
         {getControlButtons()}

         {!isSellingMode && (
             <div className="grid grid-cols-2 gap-2 mt-4 pt-4 border-t border-accent/30">
                 <button 
                    onClick={handleResetPlayer} 
                    disabled={isProcessing || !state.currentPlayerId}
                    className="flex flex-col items-center justify-center bg-yellow-600 hover:bg-yellow-700 text-xs text-white py-2 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    title="Clears bids for current player only"
                 >
                    <RotateCcw className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Current
                 </button>
                 <button 
                    onClick={handleResetFull} 
                    disabled={isProcessing}
                    className="flex flex-col items-center justify-center bg-red-900/80 hover:bg-red-900 text-xs text-red-200 border border-red-800 py-2 rounded transition-colors disabled:opacity-50"
                    title="Resets auction status to Not Started"
                 >
                    <AlertOctagon className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Full
                 </button>
             </div>
         )}
      </div>

      {/* QUICK BID BAR */}
      {state.status === AuctionStatus.InProgress && currentPlayer && (
          <div className="mb-4 animate-slide-up">
              <h3 className="text-xs font-bold text-text-secondary uppercase mb-2 flex items-center">
                  <Gavel className="w-3 h-3 mr-1 text-yellow-400" /> Quick Bid
              </h3>
              <div className="flex gap-2 overflow-x-auto pb-2 custom-scrollbar snap-x">
                  {teams.map(team => {
                      const isLimitReached = isTeamLimitReached(team);
                      const isHighest = state.highestBidder?.id === team.id;
                      const canAfford = team.budget >= nextBid;
                      const disabled = isLimitReached || isHighest || !canAfford;

                      return (
                          <button
                              key={team.id}
                              onClick={() => handleQuickBid(team.id)}
                              disabled={disabled}
                              className={`
                                  flex-shrink-0 w-24 flex flex-col items-center p-2 rounded-lg border-2 transition-all active:scale-95 snap-start
                                  ${isHighest 
                                      ? 'bg-green-600 border-green-400 shadow-[0_0_10px_rgba(22,163,74,0.5)]' 
                                      : disabled 
                                          ? 'bg-gray-800 border-gray-700 opacity-50 cursor-not-allowed' 
                                          : 'bg-primary border-gray-600 hover:border-highlight hover:bg-gray-800'}
                              `}
                          >
                              <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center mb-1 overflow-hidden">
                                  {team.logoUrl ? <img src={team.logoUrl} className="w-full h-full object-contain"/> : <span className="text-black font-bold text-xs">{team.name.charAt(0)}</span>}
                              </div>
                              <div className="text-[10px] font-bold text-white truncate w-full text-center mb-0.5">{team.name}</div>
                              <div className={`text-[10px] font-mono ${canAfford ? 'text-green-400' : 'text-red-400'}`}>{team.budget}</div>

                              <div className={`mt-1 text-[9px] font-black uppercase px-2 py-0.5 rounded w-full text-center ${isHighest ? 'bg-white text-green-700' : disabled ? 'text-gray-500' : 'bg-highlight text-primary'}`}>
                                  {isHighest ? 'LEADING' : isLimitReached ? 'FULL' : `+${nextBid - (Number(state.currentBid) || 0)}`}
                              </div>
                          </button>
                      );
                  })}
              </div>
          </div>
      )}

      <h3 className="text-sm font-bold mb-3 text-text-secondary uppercase Teams Overview">Teams Overview</h3>
      <div className="flex-grow overflow-y-auto space-y-3 pr-1 custom-scrollbar">
        {teams.map((team: Team) => (
          <TeamStatusCard key={team.id} team={team} />
        ))}
      </div>
    </div>
  );
};

export default LiveAdminPanel;

import React, { createContext, useState, useEffect, useContext, useMemo } from 'react';
import { AuctionContextType, AuctionState, UserProfile, Team, Player, AuctionStatus, BiddingStatus, AdminViewOverride, BidIncrementSlab, UserRole } from '../types';
import { db, auth } from '../firebase';
import firebase from 'firebase/compat/app';

// Initial State
const initialState: AuctionState = {
    players: [],
    teams: [],
    unsoldPlayers: [],
    categories: [],
    roles: [],
    status: AuctionStatus.NotStarted,
    currentPlayerId: null,
    currentPlayerIndex: null,
    currentBid: null,
    highestBidder: null,
    timer: 0,
    bidIncrement: 0,
    bidSlabs: [],
    auctionLog: [],
    biddingStatus: 'PAUSED',
    playerSelectionMode: 'MANUAL',
    auctionLogoUrl: '',
    tournamentName: '',
    sponsors: [],
    sponsorConfig: { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
    projectorLayout: 'STANDARD',
    obsLayout: 'STANDARD',
    adminViewOverride: null,
};

export const AuctionContext = createContext<AuctionContextType | null>(null);

export const AuctionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, setState] = useState<AuctionState>(initialState);
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [activeAuctionId, setActiveAuctionId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    // Auth Listener
    useEffect(() => {
        const unsubscribe = auth.onAuthStateChanged(async (user) => {
            if (user) {
                // Check if user is anonymous (Team Owner usually) or Google/Email (Admin)
                if (user.isAnonymous) {
                    // Try to recover session from localStorage if exists
                    const session = localStorage.getItem('sm_sports_team_session');
                    if (session) {
                        const data = JSON.parse(session);
                        setUserProfile({
                            uid: user.uid,
                            email: 'team@smsports.com',
                            role: UserRole.TEAM_OWNER,
                            teamId: data.teamId
                        });
                        if (data.auctionId) joinAuction(data.auctionId);
                    } else {
                        // Just a viewer or lost session
                        setUserProfile({ uid: user.uid, email: 'viewer@smsports.com', role: UserRole.VIEWER });
                    }
                } else {
                    // Admin
                    setUserProfile({
                        uid: user.uid,
                        email: user.email || '',
                        name: user.displayName || '',
                        role: user.email === 'admin@smsports.com' ? UserRole.SUPER_ADMIN : UserRole.ADMIN
                    });
                }
            } else {
                setUserProfile(null);
            }
        });
        return () => unsubscribe();
    }, []);

    // Auction Listener
    useEffect(() => {
        if (!activeAuctionId) return;

        const unsubscribe = db.collection('auctions').doc(activeAuctionId).onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data();
                if (data) {
                    setState(prev => ({
                        ...prev,
                        ...data,
                        // Explicitly map 'slabs' from DB to 'bidSlabs' in state
                        bidSlabs: data.slabs || [],
                        // Preserve local arrays if not in root doc (handled by subcollection listeners below)
                    }));
                }
            } else {
                setError("Auction not found");
            }
        }, (err) => {
            console.error("Auction Listener Error", err);
            setError(err.message);
        });

        // Listen to Subcollections
        const unsubTeams = db.collection('auctions').doc(activeAuctionId).collection('teams').onSnapshot(snap => {
            const teams = snap.docs.map(d => ({ id: d.id, ...d.data() } as Team));
            setState(prev => ({ ...prev, teams }));
        });

        const unsubPlayers = db.collection('auctions').doc(activeAuctionId).collection('players').onSnapshot(snap => {
            const allPlayers = snap.docs.map(d => ({ id: d.id, ...d.data() } as Player));
            setState(prev => ({ ...prev, players: allPlayers }));
        });

        const unsubCategories = db.collection('auctions').doc(activeAuctionId).collection('categories').onSnapshot(snap => {
             const categories = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, categories }));
        });

        const unsubSponsors = db.collection('auctions').doc(activeAuctionId).collection('sponsors').onSnapshot(snap => {
             const sponsors = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, sponsors }));
        });

        return () => {
            unsubscribe();
            unsubTeams();
            unsubPlayers();
            unsubCategories();
            unsubSponsors();
        };
    }, [activeAuctionId]);

    const joinAuction = (id: string) => {
        setActiveAuctionId(id);
    };

    const logout = async () => {
        await auth.signOut();
        localStorage.removeItem('sm_sports_team_session');
        setUserProfile(null);
        setActiveAuctionId(null);
        setState(initialState);
    };

    // --- DERIVED STATE (Fixes "Not Automatic Showing" Issue) ---
    // Instead of setting these in the listener, we calculate them whenever players or currentId changes.
    const derivedUnsoldPlayers = useMemo(() => {
        return state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
    }, [state.players]);

    const derivedCurrentPlayerIndex = useMemo(() => {
        if (!state.currentPlayerId || derivedUnsoldPlayers.length === 0) return null;
        const idx = derivedUnsoldPlayers.findIndex(p => String(p.id) === String(state.currentPlayerId));
        return idx !== -1 ? idx : null;
    }, [state.currentPlayerId, derivedUnsoldPlayers]);

    // Merge derived values into the state object consumed by the app
    const activeState = {
        ...state,
        unsoldPlayers: derivedUnsoldPlayers,
        currentPlayerIndex: derivedCurrentPlayerIndex
    };

    // Derived State: nextBid
    const nextBid = useMemo(() => {
        const { currentPlayerId, players, currentBid, bidIncrement, bidSlabs, categories } = state;
        const currentPlayer = players.find(p => String(p.id) === String(currentPlayerId));

        if (!currentPlayer) return 0;

        const basePrice = Number(currentPlayer.basePrice) || 0;
        const currentPrice = Number(currentBid) || 0;

        // SCENARIO 1: No bids yet (First Bid)
        if (currentPrice === 0) {
            return basePrice > 0 ? basePrice : (bidIncrement || 100);
        }

        // 1. Check Category Specific Rules First (Specific overrides General)
        if (currentPlayer.category) {
            const cat = categories.find(c => c.name === currentPlayer.category);

            // Category Slabs
            if (cat && cat.slabs && cat.slabs.length > 0) {
                 const sortedSlabs = [...cat.slabs].sort((a, b) => b.from - a.from);
                 const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
                 if (activeSlab) {
                     return currentPrice + Number(activeSlab.increment);
                 }
            }

            // Category specific increment (without slabs)
            if (cat && cat.bidIncrement > 0) {
                return currentPrice + Number(cat.bidIncrement);
            }
        }

        // 2. Check Global Slabs
        if (bidSlabs && bidSlabs.length > 0) {
            const sortedSlabs = [...bidSlabs].sort((a, b) => b.from - a.from);
            const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
            if (activeSlab) {
                return currentPrice + Number(activeSlab.increment);
            }
        }

        // 3. Default Global Increment
        return currentPrice + (Number(bidIncrement) || 100);
    }, [state.currentBid, state.currentPlayerId, state.players, state.bidIncrement, state.bidSlabs, state.categories]);

    // Implementation of actions
    const placeBid = async (teamId: string | number, amount: number) => {
        if (!activeAuctionId) return;
        const team = state.teams.find(t => String(t.id) === String(teamId));
        if (!team) throw new Error("Team not found");

        const log = {
            message: `${team.name} bid ${amount}`,
            timestamp: Date.now(),
            type: 'BID'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: amount,
            highestBidder: team,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const sellPlayer = async (teamId?: string | number, customPrice?: number) => {
        if (!activeAuctionId || !state.currentPlayerId) return;

        const finalTeam = teamId ? state.teams.find(t => String(t.id) === String(teamId)) : state.highestBidder;
        const finalPrice = customPrice !== undefined ? customPrice : (state.currentBid || 0);

        if (!finalTeam) throw new Error("No team selected to sell to");

        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.runTransaction(async (transaction) => {
            const auctionRef = db.collection('auctions').doc(activeAuctionId);
            const playerRef = auctionRef.collection('players').doc(String(player.id));
            const teamRef = auctionRef.collection('teams').doc(String(finalTeam.id));

            // CRITICAL CHECK: Ensure team doc exists before reading data
            const teamDoc = await transaction.get(teamRef);
            if (!teamDoc.exists) {
                throw new Error("Target team document does not exist in database");
            }
            const teamData = teamDoc.data() as Team;

            transaction.update(playerRef, {
                status: 'SOLD',
                soldPrice: finalPrice,
                soldTo: finalTeam.name
            });

            const updatedPlayers = [...(teamData.players || []), { ...player, status: 'SOLD', soldPrice: finalPrice, soldTo: finalTeam.name }];
            const newBudget = (teamData.budget || 0) - finalPrice;

            transaction.update(teamRef, {
                budget: newBudget,
                players: updatedPlayers
            });

            const log = {
                message: `${player.name} SOLD to ${finalTeam.name} for ${finalPrice}`,
                timestamp: Date.now(),
                type: 'SOLD'
            };

            transaction.update(auctionRef, {
                status: AuctionStatus.Sold, 
                auctionLog: firebase.firestore.FieldValue.arrayUnion(log),
                currentBid: finalPrice,
                highestBidder: finalTeam
            });
        });
    };

    const passPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(player.id)).update({
            status: 'UNSOLD'
        });

        const log = {
            message: `${player.name} UNSOLD`,
            timestamp: Date.now(),
            type: 'UNSOLD'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Unsold,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const startAuction = async (specificPlayerId?: string | number) => {
        if (!activeAuctionId) return false;

        let nextPlayerId = specificPlayerId;

        if (!nextPlayerId) {
            const available = state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
            if (available.length === 0) return false;
            const next = available[Math.floor(Math.random() * available.length)];
            nextPlayerId = next.id;
        }

        if (!nextPlayerId) return false;

        const player = state.players.find(p => String(p.id) === String(nextPlayerId));

        await db.collection('auctions').doc(activeAuctionId).update({
            currentPlayerId: nextPlayerId,
            currentBid: 0,
            highestBidder: null,
            status: AuctionStatus.InProgress,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `Bidding started for ${player?.name}`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });

        return true;
    };

    const resetCurrentPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: 0,
            highestBidder: null,
            timer: 10,
            status: AuctionStatus.InProgress
        });
    };

    const endAuction = async () => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Finished,
            currentPlayerId: null
        });
    };

    const resetAuction = async () => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        // 1. Fetch Default Purse from Auction Config
        const auctionSnap = await auctionRef.get();
        if (!auctionSnap.exists) return;
        const defaultPurse = auctionSnap.data()?.purseValue || 10000;

        // 2. Fetch all Teams and Players to reset
        const playersSnap = await auctionRef.collection('players').get();
        const teamsSnap = await auctionRef.collection('teams').get();

        // 3. Batched Updates (Handling chunks of 450 to stay under 500 limit)
        const batchSize = 450;
        const allDocs = [
            ...playersSnap.docs.map(d => ({ type: 'PLAYER', ref: d.ref })),
            ...teamsSnap.docs.map(d => ({ type: 'TEAM', ref: d.ref }))
        ];

        // Process in chunks
        for (let i = 0; i < allDocs.length; i += batchSize) {
            const batch = db.batch();
            const chunk = allDocs.slice(i, i + batchSize);

            chunk.forEach(item => {
                if (item.type === 'PLAYER') {
                    batch.update(item.ref, {
                        status: firebase.firestore.FieldValue.delete(),
                        soldPrice: firebase.firestore.FieldValue.delete(),
                        soldTo: firebase.firestore.FieldValue.delete()
                    });
                } else {
                    batch.update(item.ref, {
                        budget: defaultPurse,
                        players: []
                    });
                }
            });

            // Only update root auction doc in the first batch
            if (i === 0) {
                batch.update(auctionRef, {
                    status: AuctionStatus.NotStarted,
                    currentPlayerId: null,
                    currentBid: 0,
                    highestBidder: null,
                    auctionLog: [],
                    timer: 0
                });
            }

            await batch.commit();
        }

        // If there were no sub-docs, we still need to reset the auction status
        if (allDocs.length === 0) {
             await auctionRef.update({
                status: AuctionStatus.NotStarted,
                currentPlayerId: null,
                currentBid: 0,
                highestBidder: null,
                auctionLog: [],
                timer: 0
            });
        }
    };

    const resetUnsoldPlayers = async () => {
        if (!activeAuctionId) return;
        const unsold = state.players.filter(p => p.status === 'UNSOLD');
        const batch = db.batch();

        unsold.forEach(p => {
            const ref = db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(p.id));
            batch.update(ref, { status: firebase.firestore.FieldValue.delete() });
        });

        await batch.commit();

        await db.collection('auctions').doc(activeAuctionId).update({
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `${unsold.length} unsold players brought back to pool`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });
    };

    const updateBiddingStatus = async (status: BiddingStatus) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ biddingStatus: status });
    };

    const toggleSelectionMode = async () => {
        if (!activeAuctionId) return;
        const newMode = state.playerSelectionMode === 'MANUAL' ? 'AUTO' : 'MANUAL';
        await db.collection('auctions').doc(activeAuctionId).update({ playerSelectionMode: newMode });
    };

    const updateTheme = async (type: 'PROJECTOR' | 'OBS', layout: string) => {
        if (!activeAuctionId) return;
        const field = type === 'PROJECTOR' ? 'projectorLayout' : 'obsLayout';
        await db.collection('auctions').doc(activeAuctionId).update({ [field]: layout });
    };

    const setAdminView = async (view: AdminViewOverride | null) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ adminViewOverride: view });
    };

    const correctPlayerSale = async (playerId: string, newTeamId: string | null, newPrice: number) => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        await db.runTransaction(async (t) => {
            const playerRef = auctionRef.collection('players').doc(playerId);
            const playerDoc = await t.get(playerRef);
            const playerData = playerDoc.data() as Player;

            // 1. Revert previous sale if applicable
            if (playerData.status === 'SOLD' && playerData.soldTo) {
                const prevTeam = state.teams.find(tm => tm.name === playerData.soldTo);
                if (prevTeam) {
                    const prevTeamRef = auctionRef.collection('teams').doc(String(prevTeam.id));
                    const prevTeamDoc = await t.get(prevTeamRef);
                    if (prevTeamDoc.exists) {
                        const ptData = prevTeamDoc.data() as Team;
                        const refund = playerData.soldPrice || 0;
                        const newBudget = (ptData.budget || 0) + refund;
                        const newPlayers = (ptData.players || []).filter(p => String(p.id) !== playerId);

                        t.update(prevTeamRef, { budget: newBudget, players: newPlayers });
                    }
                }
            }

            // 2. Apply new sale if newTeamId provided
            if (newTeamId) {
                const newTeamRef = auctionRef.collection('teams').doc(newTeamId);
                const newTeamDoc = await t.get(newTeamRef);
                const newTeamData = newTeamDoc.data() as Team;

                const newBudget = (newTeamData.budget || 0) - newPrice;
                const updatedPlayerObj = { ...playerData, status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name };
                const newPlayers = [...(newTeamData.players || []), updatedPlayerObj];

                t.update(newTeamRef, { budget: newBudget, players: newPlayers });
                t.update(playerRef, { status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name });
            } else {
                t.update(playerRef, { 
                    status: firebase.firestore.FieldValue.delete(), 
                    soldPrice: firebase.firestore.FieldValue.delete(),
                    soldTo: firebase.firestore.FieldValue.delete()
                });
            }
        });
    };

    return (
        <AuctionContext.Provider value={{
            state: activeState, // Pass the state with derived values overrides
            userProfile,
            setUserProfile,
            placeBid,
            sellPlayer,
            passPlayer,
            correctPlayerSale,
            startAuction,
            endAuction,
            resetAuction,
            resetCurrentPlayer,
            resetUnsoldPlayers,
            updateBiddingStatus,
            toggleSelectionMode,
            updateTheme,
            setAdminView,
            logout,
            error,
            joinAuction,
            activeAuctionId,
            nextBid
        }}>
            {children}
        </AuctionContext.Provider>
    );
};

import React, { useEffect, useState, useRef } from 'react';
import { useAuction } from '../hooks/useAuction';
import { useParams } from 'react-router-dom';
import { User, Gavel, DollarSign } from 'lucide-react';
import { Player, Team, AuctionStatus } from '../types';

// Types for our local frozen state
interface OverlayState {
    player: Player | null;
    bid: number;
    bidder: Team | null;
    status: 'WAITING' | 'LIVE' | 'SOLD' | 'UNSOLD' | 'FINISHED';
}

const OBSOverlay: React.FC = () => {
  const { state, joinAuction } = useAuction();
  const { auctionId } = useParams<{ auctionId: string }>();

  // Local state to handle persistence
  const [display, setDisplay] = useState<OverlayState>({
      player: null,
      bid: 0,
      bidder: null,
      status: 'WAITING'
  });

  const [currentSponsorIndex, setCurrentSponsorIndex] = useState(0);
  const loopInterval = state.sponsorConfig?.loopInterval || 5;
  const sponsorsLength = state.sponsors.length;

  useEffect(() => {
      if (sponsorsLength <= 1) return;
      const interval = setInterval(() => {
          setCurrentSponsorIndex(prev => (prev + 1) % sponsorsLength);
      }, loopInterval * 1000);
      return () => clearInterval(interval);
  }, [sponsorsLength, loopInterval]);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Force Transparency on Mount
  useEffect(() => {
      const originalBodyBg = document.body.style.backgroundColor;
      const originalHtmlBg = document.documentElement.style.backgroundColor;
      document.body.style.backgroundColor = 'transparent';
      document.documentElement.style.backgroundColor = 'transparent';
      return () => {
          document.body.style.backgroundColor = originalBodyBg;
          document.documentElement.style.backgroundColor = originalHtmlBg;
      };
  }, []);

  useEffect(() => {
      if (auctionId) joinAuction(auctionId);
  }, [auctionId]);

  // --- SYNC LOGIC ---
  useEffect(() => {
      const { currentPlayerIndex, unsoldPlayers, currentBid, highestBidder, status, teams } = state;
      const currentPlayer = currentPlayerIndex !== null ? unsoldPlayers[currentPlayerIndex] : null;

      if (status === AuctionStatus.Finished) {
           setDisplay({ player: null, bid: 0, bidder: null, status: 'FINISHED' });
           return;
      }

      if (currentPlayer) {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);

          let derivedStatus: 'LIVE' | 'SOLD' | 'UNSOLD' | 'FINISHED' = 'LIVE';
          if (status === AuctionStatus.Sold || currentPlayer.status === 'SOLD') derivedStatus = 'SOLD';
          else if (status === AuctionStatus.Unsold || currentPlayer.status === 'UNSOLD') derivedStatus = 'UNSOLD';

          // Determine Bidder for Sold Status
          let resolvedBidder = highestBidder;

          if (derivedStatus === 'SOLD' && !resolvedBidder && currentPlayer.soldTo) {
             const winningTeam = teams.find(t => t.name === currentPlayer.soldTo);
             if (winningTeam) resolvedBidder = winningTeam;
          }

          setDisplay({
              player: currentPlayer,
              bid: currentPlayer.soldPrice || currentBid || currentPlayer.basePrice,
              bidder: resolvedBidder,
              status: derivedStatus
          });
      } else {
          // No player
          if (display.status !== 'WAITING' && display.status !== 'FINISHED') {
              timeoutRef.current = setTimeout(() => {
                  setDisplay({ player: null, bid: 0, bidder: null, status: 'WAITING' });
              }, 2000); 
          }
      }
  }, [state]);

  if (window.location.protocol === 'blob:') {
      return (
          <div className="min-h-screen w-full flex items-center justify-center bg-black/90 p-10">
              <div className="bg-red-600/20 border border-red-500 text-white p-8 rounded-xl text-center">
                  <h1 className="text-2xl font-bold mb-2">Preview Mode Detected</h1>
                  <p>Please deploy the app to use the OBS Overlay.</p>
              </div>
          </div>
      );
  }

  // Common Sponsor
  const SponsorLogo = () => (
      state.sponsorConfig?.showOnOBS && state.sponsors.length > 0 && (
          <div className="absolute top-6 right-6 w-40 h-24 bg-white/90 backdrop-blur rounded-xl shadow-lg p-2 flex items-center justify-center z-50 border-2 border-white/20 overflow-hidden">
               <img 
                  src={state.sponsors[currentSponsorIndex]?.imageUrl} 
                  className="max-w-full max-h-full object-contain"
                  alt="Sponsor"
              />
          </div>
      )
  );

  // --- OVERRIDE RENDERER ---
  if (state.adminViewOverride && state.adminViewOverride.type !== 'NONE') {
      const { type, data } = state.adminViewOverride;

      const OverlayCard = ({ children, title }: any) => (
          <div className="min-h-screen w-full flex flex-col items-center justify-center relative p-8">
              <SponsorLogo />
