import React, { createContext, useState, useEffect, useContext, useMemo } from 'react';
import { AuctionContextType, AuctionState, UserProfile, Team, Player, AuctionStatus, BiddingStatus, AdminViewOverride, BidIncrementSlab, UserRole, SponsorConfig } from '../types';
import { db, auth } from '../firebase';
import firebase from 'firebase/compat/app';

// Initial State
const initialState: AuctionState = {
    players: [],
    teams: [],
    unsoldPlayers: [],
    categories: [],
    roles: [],
    status: AuctionStatus.NotStarted,
    currentPlayerId: null,
    currentPlayerIndex: null,
    currentBid: null,
    highestBidder: null,
    timer: 0,
    bidIncrement: 0,
    bidSlabs: [],
    auctionLog: [],
    biddingStatus: 'PAUSED',
    playerSelectionMode: 'MANUAL',
    auctionLogoUrl: '',
    tournamentName: '',
    sponsors: [],
    sponsorConfig: { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
    projectorLayout: 'STANDARD',
    obsLayout: 'STANDARD',
    adminViewOverride: null,
    maxPlayersPerTeam: 25 // Default
};

export const AuctionContext = createContext<AuctionContextType | null>(null);

export const AuctionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, setState] = useState<AuctionState>(initialState);
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [activeAuctionId, setActiveAuctionId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    // Auth Listener
    useEffect(() => {
        const unsubscribe = auth.onAuthStateChanged(async (user) => {
            if (user) {
                // Check if user is anonymous (Team Owner usually) or Google/Email (Admin)
                if (user.isAnonymous) {
                    // Try to recover session from localStorage if exists
                    const session = localStorage.getItem('sm_sports_team_session');
                    if (session) {
                        const data = JSON.parse(session);
                        setUserProfile({
                            uid: user.uid,
                            email: 'team@smsports.com',
                            role: UserRole.TEAM_OWNER,
                            teamId: data.teamId
                        });
                        if (data.auctionId) joinAuction(data.auctionId);
                    } else {
                        // Just a viewer or lost session
                        setUserProfile({ uid: user.uid, email: 'viewer@smsports.com', role: UserRole.VIEWER });
                    }
                } else {
                    // Admin
                    setUserProfile({
                        uid: user.uid,
                        email: user.email || '',
                        name: user.displayName || '',
                        role: user.email === 'admin@smsports.com' ? UserRole.SUPER_ADMIN : UserRole.ADMIN
                    });
                }
            } else {
                setUserProfile(null);
            }
        });
        return () => unsubscribe();
    }, []);

    // Auction Listener
    useEffect(() => {
        if (!activeAuctionId) return;

        const unsubscribe = db.collection('auctions').doc(activeAuctionId).onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data();
                if (data) {
                    setState(prev => ({
                        ...prev,
                        ...data,
                        // Explicitly map 'slabs' from DB to 'bidSlabs' in state
                        bidSlabs: data.slabs || [],
                        // Explicitly map Title and Logo for display
                        tournamentName: data.title || prev.tournamentName,
                        auctionLogoUrl: data.logoUrl || prev.auctionLogoUrl,
                        // Ensure sponsorConfig has defaults
                        sponsorConfig: data.sponsorConfig || prev.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
                        // Map Squad Limit
                        maxPlayersPerTeam: data.playersPerTeam || 25
                    }));
                }
            } else {
                setError("Auction not found");
            }
        }, (err) => {
            console.error("Auction Listener Error", err);
            setError(err.message);
        });

        // Listen to Subcollections
        const unsubTeams = db.collection('auctions').doc(activeAuctionId).collection('teams').onSnapshot(snap => {
            const teams = snap.docs.map(d => ({ id: d.id, ...d.data() } as Team));
            setState(prev => ({ ...prev, teams }));
        });

        const unsubPlayers = db.collection('auctions').doc(activeAuctionId).collection('players').onSnapshot(snap => {
            const allPlayers = snap.docs.map(d => ({ id: d.id, ...d.data() } as Player));
            setState(prev => ({ ...prev, players: allPlayers }));
        });

        const unsubCategories = db.collection('auctions').doc(activeAuctionId).collection('categories').onSnapshot(snap => {
             const categories = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, categories }));
        });

        const unsubSponsors = db.collection('auctions').doc(activeAuctionId).collection('sponsors').onSnapshot(snap => {
             const sponsors = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, sponsors }));
        });

        return () => {
            unsubscribe();
            unsubTeams();
            unsubPlayers();
            unsubCategories();
            unsubSponsors();
        };
    }, [activeAuctionId]);

    const joinAuction = (id: string) => {
        setActiveAuctionId(id);
    };

    const logout = async () => {
        await auth.signOut();
        localStorage.removeItem('sm_sports_team_session');
        setUserProfile(null);
        setActiveAuctionId(null);
        setState(initialState);
    };

    // --- DERIVED STATE (Fixes "Not Automatic Showing" Issue) ---
    // Instead of setting these in the listener, we calculate them whenever players or currentId changes.
    const derivedUnsoldPlayers = useMemo(() => {
        return state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
    }, [state.players]);

    const derivedCurrentPlayerIndex = useMemo(() => {
        if (!state.currentPlayerId || derivedUnsoldPlayers.length === 0) return null;
        const idx = derivedUnsoldPlayers.findIndex(p => String(p.id) === String(state.currentPlayerId));
        return idx !== -1 ? idx : null;
    }, [state.currentPlayerId, derivedUnsoldPlayers]);

    // Merge derived values into the state object consumed by the app
    const activeState = {
        ...state,
        unsoldPlayers: derivedUnsoldPlayers,
        currentPlayerIndex: derivedCurrentPlayerIndex
    };

    // Derived State: nextBid
    const nextBid = useMemo(() => {
        const { currentPlayerId, players, currentBid, bidIncrement, bidSlabs, categories } = state;
        const currentPlayer = players.find(p => String(p.id) === String(currentPlayerId));

        if (!currentPlayer) return 0;

        const basePrice = Number(currentPlayer.basePrice) || 0;
        const currentPrice = Number(currentBid) || 0;

        // SCENARIO 1: No bids yet (First Bid)
        if (currentPrice === 0) {
            return basePrice > 0 ? basePrice : (bidIncrement || 100);
        }

        // 1. Check Category Specific Rules First (Specific overrides General)
        if (currentPlayer.category) {
            const cat = categories.find(c => c.name === currentPlayer.category);

            // Category Slabs
            if (cat && cat.slabs && cat.slabs.length > 0) {
                 const sortedSlabs = [...cat.slabs].sort((a, b) => b.from - a.from);
                 const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
                 if (activeSlab) {
                     return currentPrice + Number(activeSlab.increment);
                 }
            }

            // Category specific increment (without slabs)
            if (cat && cat.bidIncrement > 0) {
                return currentPrice + Number(cat.bidIncrement);
            }
        }

        // 2. Check Global Slabs
        if (bidSlabs && bidSlabs.length > 0) {
            const sortedSlabs = [...bidSlabs].sort((a, b) => b.from - a.from);
            const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
            if (activeSlab) {
                return currentPrice + Number(activeSlab.increment);
            }
        }

        // 3. Default Global Increment
        return currentPrice + (Number(bidIncrement) || 100);
    }, [state.currentBid, state.currentPlayerId, state.players, state.bidIncrement, state.bidSlabs, state.categories]);

    // Implementation of actions
    const placeBid = async (teamId: string | number, amount: number) => {
        if (!activeAuctionId) return;
        const team = state.teams.find(t => String(t.id) === String(teamId));
        if (!team) throw new Error("Team not found");

        const currentPlayer = state.players.find(p => String(p.id) === String(state.currentPlayerId));

        // --- BID LIMIT RULE VALIDATION ---
        if (currentPlayer) {
            let reservedBudget = 0;
            state.categories.forEach(cat => {
                if (cat.maxPerTeam > 0) {
                    const playersInCat = team.players.filter(p => p.category === cat.name).length;
                    let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);

                    // If current player belongs to this category, we count this bid as filling one slot (so don't reserve for it)
                    if (currentPlayer.category === cat.name) {
                        slotsToFill = Math.max(0, slotsToFill - 1);
                    }

                    reservedBudget += slotsToFill * cat.basePrice;
                }
            });

            const maxAllowedBid = team.budget - reservedBudget;
            if (amount > maxAllowedBid) {
                throw new Error(`Bid Limit Reached! Max allowable bid is ${maxAllowedBid} to ensure squad completion.`);
            }
        }
        // ---------------------------------

        const log = {
            message: `${team.name} bid ${amount}`,
            timestamp: Date.now(),
            type: 'BID'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: amount,
            highestBidder: team,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const sellPlayer = async (teamId?: string | number, customPrice?: number) => {
        if (!activeAuctionId || !state.currentPlayerId) return;

        const finalTeam = teamId ? state.teams.find(t => String(t.id) === String(teamId)) : state.highestBidder;
        const finalPrice = customPrice !== undefined ? customPrice : (state.currentBid || 0);

        if (!finalTeam) throw new Error("No team selected to sell to");

        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.runTransaction(async (transaction) => {
            const auctionRef = db.collection('auctions').doc(activeAuctionId);
            const playerRef = auctionRef.collection('players').doc(String(player.id));
            const teamRef = auctionRef.collection('teams').doc(String(finalTeam.id));

            // CRITICAL CHECK: Ensure team doc exists before reading data
            const teamDoc = await transaction.get(teamRef);
            if (!teamDoc.exists) {
                throw new Error("Target team document does not exist in database");
            }
            const teamData = teamDoc.data() as Team;

            transaction.update(playerRef, {
                status: 'SOLD',
                soldPrice: finalPrice,
                soldTo: finalTeam.name
            });

            const updatedPlayers = [...(teamData.players || []), { ...player, status: 'SOLD', soldPrice: finalPrice, soldTo: finalTeam.name }];
            const newBudget = (teamData.budget || 0) - finalPrice;

            transaction.update(teamRef, {
                budget: newBudget,
                players: updatedPlayers
            });

            const log = {
                message: `${player.name} SOLD to ${finalTeam.name} for ${finalPrice}`,
                timestamp: Date.now(),
                type: 'SOLD'
            };

            transaction.update(auctionRef, {
                status: AuctionStatus.Sold, 
                auctionLog: firebase.firestore.FieldValue.arrayUnion(log),
                currentBid: finalPrice,
                highestBidder: finalTeam
            });
        });
    };

    const passPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(player.id)).update({
            status: 'UNSOLD'
        });

        const log = {
            message: `${player.name} UNSOLD`,
            timestamp: Date.now(),
            type: 'UNSOLD'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Unsold,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const startAuction = async (specificPlayerId?: string | number) => {
        if (!activeAuctionId) return false;

        let nextPlayerId = specificPlayerId;

        if (!nextPlayerId) {
            const available = state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
            if (available.length === 0) return false;
            const next = available[Math.floor(Math.random() * available.length)];
            nextPlayerId = next.id;
        }

        if (!nextPlayerId) return false;

        const player = state.players.find(p => String(p.id) === String(nextPlayerId));

        await db.collection('auctions').doc(activeAuctionId).update({
            currentPlayerId: nextPlayerId,
            currentBid: 0,
            highestBidder: null,
            status: AuctionStatus.InProgress,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `Bidding started for ${player?.name}`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });

        return true;
    };

    const resetCurrentPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: 0,
            highestBidder: null,
            timer: 10,
            status: AuctionStatus.InProgress
        });
    };

    const endAuction = async () => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Finished,
            currentPlayerId: null
        });
    };

    const resetAuction = async () => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        // 1. Fetch Default Purse from Auction Config
        const auctionSnap = await auctionRef.get();
        if (!auctionSnap.exists) return;
        const defaultPurse = auctionSnap.data()?.purseValue || 10000;

        // 2. Fetch all Teams and Players to reset
        const playersSnap = await auctionRef.collection('players').get();
        const teamsSnap = await auctionRef.collection('teams').get();

        // 3. Batched Updates (Handling chunks of 450 to stay under 500 limit)
        const batchSize = 450;
        const allDocs = [
            ...playersSnap.docs.map(d => ({ type: 'PLAYER', ref: d.ref })),
            ...teamsSnap.docs.map(d => ({ type: 'TEAM', ref: d.ref }))
        ];

        // Process in chunks
        for (let i = 0; i < allDocs.length; i += batchSize) {
            const batch = db.batch();
            const chunk = allDocs.slice(i, i + batchSize);

            chunk.forEach(item => {
                if (item.type === 'PLAYER') {
                    batch.update(item.ref, {
                        status: firebase.firestore.FieldValue.delete(),
                        soldPrice: firebase.firestore.FieldValue.delete(),
                        soldTo: firebase.firestore.FieldValue.delete()
                    });
                } else {
                    batch.update(item.ref, {
                        budget: defaultPurse,
                        players: []
                    });
                }
            });

            // Only update root auction doc in the first batch
            if (i === 0) {
                batch.update(auctionRef, {
                    status: AuctionStatus.NotStarted,
                    currentPlayerId: null,
                    currentBid: 0,
                    highestBidder: null,
                    auctionLog: [],
                    timer: 0
                });
            }

            await batch.commit();
        }

        // If there were no sub-docs, we still need to reset the auction status
        if (allDocs.length === 0) {
             await auctionRef.update({
                status: AuctionStatus.NotStarted,
                currentPlayerId: null,
                currentBid: 0,
                highestBidder: null,
                auctionLog: [],
                timer: 0
            });
        }
    };

    const resetUnsoldPlayers = async () => {
        if (!activeAuctionId) return;
        const unsold = state.players.filter(p => p.status === 'UNSOLD');
        const batch = db.batch();

        unsold.forEach(p => {
            const ref = db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(p.id));
            batch.update(ref, { status: firebase.firestore.FieldValue.delete() });
        });

        await batch.commit();

        await db.collection('auctions').doc(activeAuctionId).update({
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `${unsold.length} unsold players brought back to pool`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });
    };

    const updateBiddingStatus = async (status: BiddingStatus) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ biddingStatus: status });
    };

    const updateSponsorConfig = async (config: SponsorConfig) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ sponsorConfig: config });
    };

    const toggleSelectionMode = async () => {
        if (!activeAuctionId) return;
        const newMode = state.playerSelectionMode === 'MANUAL' ? 'AUTO' : 'MANUAL';
        await db.collection('auctions').doc(activeAuctionId).update({ playerSelectionMode: newMode });
    };

    const updateTheme = async (type: 'PROJECTOR' | 'OBS', layout: string) => {
        if (!activeAuctionId) return;
        const field = type === 'PROJECTOR' ? 'projectorLayout' : 'obsLayout';
        await db.collection('auctions').doc(activeAuctionId).update({ [field]: layout });
    };

    const setAdminView = async (view: AdminViewOverride | null) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ adminViewOverride: view });
    };

    const correctPlayerSale = async (playerId: string, newTeamId: string | null, newPrice: number) => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        await db.runTransaction(async (t) => {
            const playerRef = auctionRef.collection('players').doc(playerId);
            const playerDoc = await t.get(playerRef);
            const playerData = playerDoc.data() as Player;

            // 1. Revert previous sale if applicable
            if (playerData.status === 'SOLD' && playerData.soldTo) {
                const prevTeam = state.teams.find(tm => tm.name === playerData.soldTo);
                if (prevTeam) {
                    const prevTeamRef = auctionRef.collection('teams').doc(String(prevTeam.id));
                    const prevTeamDoc = await t.get(prevTeamRef);
                    if (prevTeamDoc.exists) {
                        const ptData = prevTeamDoc.data() as Team;
                        const refund = playerData.soldPrice || 0;
                        const newBudget = (ptData.budget || 0) + refund;
                        const newPlayers = (ptData.players || []).filter(p => String(p.id) !== playerId);

                        t.update(prevTeamRef, { budget: newBudget, players: newPlayers });
                    }
                }
            }

            // 2. Apply new sale if newTeamId provided
            if (newTeamId) {
                const newTeamRef = auctionRef.collection('teams').doc(newTeamId);
                const newTeamDoc = await t.get(newTeamRef);
                const newTeamData = newTeamDoc.data() as Team;

                const newBudget = (newTeamData.budget || 0) - newPrice;
                const updatedPlayerObj = { ...playerData, status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name };
                const newPlayers = [...(newTeamData.players || []), updatedPlayerObj];

                t.update(newTeamRef, { budget: newBudget, players: newPlayers });
                t.update(playerRef, { status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name });
            } else {
                t.update(playerRef, { 
                    status: firebase.firestore.FieldValue.delete(), 
                    soldPrice: firebase.firestore.FieldValue.delete(),
                    soldTo: firebase.firestore.FieldValue.delete()
                });
            }
        });
    };

    return (
        <AuctionContext.Provider value={{
            state: activeState, // Pass the state with derived values overrides
            userProfile,
            setUserProfile,
            placeBid,
            sellPlayer,
            passPlayer,
            correctPlayerSale,
            startAuction,
            endAuction,
            resetAuction,
            resetCurrentPlayer,
            resetUnsoldPlayers,
            updateBiddingStatus,
            updateSponsorConfig,
            toggleSelectionMode,
            updateTheme,
            setAdminView,
            logout,
            error,
            joinAuction,
            activeAuctionId,
            nextBid
        }}>
            {children}
        </AuctionContext.Provider>
    );
};

import React, { useState } from 'react';
import { useAuction } from '../hooks/useAuction';
import { Gavel, Lock, AlertCircle, Users, AlertTriangle } from 'lucide-react';

const BiddingPanel: React.FC = () => {
    const { state, userProfile, placeBid, nextBid } = useAuction();
    const { teams, highestBidder, biddingStatus, currentBid, currentPlayerId, players, status, categories, maxPlayersPerTeam } = state;
    const [isBidding, setIsBidding] = useState(false);

    if (!userProfile || !userProfile.teamId) return null;

    // Find user's team securely
    const userTeam = teams.find(t => String(t.id) === String(userProfile.teamId));
    if (!userTeam) return null;

    // If auction is not in progress (e.g. SOLD), hide the bidding controls or show status
    if (status !== 'IN_PROGRESS') {
        return (
            <div className="bg-secondary rounded-xl shadow-xl p-4 border border-gray-700 text-center">
                <p className="text-gray-400 font-bold uppercase tracking-widest text-sm">
                    {status === 'SOLD' ? 'LOT SOLD' : status === 'UNSOLD' ? 'LOT UNSOLD' : 'BIDDING CLOSED'}
                </p>
            </div>
        );
    }

    // Resolve current player using ID from full list (consistent with other views)
    const currentPlayer = currentPlayerId ? players.find(p => String(p.id) === String(currentPlayerId)) : null;

    // Check Category Limit
    let isCategoryLimitReached = false;
    let categoryLimitMsg = "";

    if (currentPlayer && currentPlayer.category) {
        const catConfig = categories.find(c => c.name === currentPlayer.category);
        if (catConfig && catConfig.maxPerTeam > 0) {
            const currentCount = userTeam.players.filter(p => p.category === currentPlayer.category).length;
            if (currentCount >= catConfig.maxPerTeam) {
                isCategoryLimitReached = true;
                categoryLimitMsg = `Max ${catConfig.maxPerTeam} '${currentPlayer.category}' players reached`;
            }
        }
    }

    // --- BID LIMIT RULE (Category-wise Squad Protection) ---
    let reservedBudget = 0;
    if (currentPlayer) {
        categories.forEach(cat => {
            if (cat.maxPerTeam > 0) {
                const playersInCat = userTeam.players.filter(p => p.category === cat.name).length;
                let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);

                // If current player belongs to this category, we count this potential bid as filling one slot
                // So we don't need to reserve funds for *this* specific slot, only the remaining ones.
                if (currentPlayer.category === cat.name) {
                    slotsToFill = Math.max(0, slotsToFill - 1);
                }

                reservedBudget += slotsToFill * cat.basePrice;
            }
        });
    }
    const maxAllowedBid = userTeam.budget - reservedBudget;
    const isBidLimitExceeded = nextBid > maxAllowedBid;
    // -----------------------------------------------------

    // Check Squad Limit
    const squadLimit = maxPlayersPerTeam || 25; // Default fallback
    const isSquadFull = userTeam.players.length >= squadLimit;

    const canAfford = userTeam.budget >= nextBid;
    const isLeading = highestBidder && String(highestBidder.id) === String(userTeam.id);
    const isLoadingBid = nextBid === 0;

    // Status Helpers
    const isPaused = biddingStatus === 'PAUSED';
    const isActive = biddingStatus === 'ON';

    const handleBid = async () => {
        // Strict Client-Side Check
        if (canAfford && !isLeading && isActive && !isCategoryLimitReached && !isSquadFull && !isBidLimitExceeded) {
            setIsBidding(true);
            try {
                await placeBid(userTeam.id, nextBid);
            } catch (e) {
                console.error(e);
                alert((e as Error).message);
            } finally {
                setIsBidding(false);
            }
        }
    };

    return (
        <div className="bg-secondary rounded-xl shadow-xl p-3 md:p-6 border border-highlight/30 relative overflow-hidden">
            <div className="absolute top-0 left-0 w-1 h-full bg-highlight"></div>

            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                <div className="w-full sm:w-auto text-center sm:text-left flex flex-row sm:flex-col justify-between sm:justify-start items-center sm:items-start px-2 sm:px-0">
                    <div>
                        <p className="text-text-secondary text-[10px] md:text-sm uppercase tracking-widest font-bold">Your Purse</p>
                        <p className="text-xl md:text-3xl font-bold text-white tabular-nums leading-none mt-1">{userTeam.budget}</p>
                    </div>
                    {isPaused && (
                        <div className="sm:hidden bg-red-900/50 px-2 py-1 rounded border border-red-500/50">
                            <span className="text-[10px] text-red-200 font-bold uppercase flex items-center"><Lock className="w-3 h-3 mr-1"/> Paused</span>
                        </div>
                    )}
                </div>

                <div className="flex flex-col items-center w-full sm:w-auto">
                    <button
                        onClick={handleBid}
                        disabled={!canAfford || isLeading || isBidding || !isActive || isLoadingBid || isCategoryLimitReached || isSquadFull || isBidLimitExceeded}
                        className={`
                            w-full sm:w-auto flex-grow md:flex-grow-0 flex items-center justify-center py-3 md:py-4 px-6 md:px-8 rounded-lg font-black text-base md:text-xl tracking-wider transition-all transform
                            ${isLeading 
                                ? 'bg-green-600 text-white cursor-default' 
                                : isSquadFull || isCategoryLimitReached || isBidLimitExceeded
                                    ? 'bg-gray-700 text-red-300 border border-red-500/30 cursor-not-allowed'
                                : (!isActive)
                                    ? 'bg-red-900/50 border border-red-700 text-red-200 cursor-not-allowed opacity-75'
                                    : (!canAfford || isLoadingBid)
                                        ? 'bg-gray-600 text-gray-400 cursor-not-allowed'
                                        : 'bg-highlight hover:bg-teal-400 text-primary hover:scale-105 shadow-[0_0_20px_rgba(56,178,172,0.4)]'
                            }
                        `}
                    >
                        {isLeading ? (
                            <>LEADING <span className="ml-2 text-sm font-normal hidden sm:inline">({currentBid})</span></>
                        ) : isSquadFull ? (
                            <><Users className="mr-2 h-4 w-4"/> SQUAD FULL</>
                        ) : isCategoryLimitReached ? (
                            <><Lock className="mr-2 h-4 w-4"/> LIMIT REACHED</>
                        ) : isBidLimitExceeded ? (
                            <><AlertTriangle className="mr-2 h-4 w-4"/> MAX BID EXCEEDED</>
                        ) : !isActive ? (
                            <><Lock className="mr-2 h-4 w-4 md:h-5 md:w-5"/> PAUSED</>
                        ) : isLoadingBid ? (
                            <span className="animate-pulse">LOADING...</span>
                        ) : (
                            <><Gavel className="mr-2 h-5 w-5 md:h-6 md:w-6"/> BID {nextBid}</>
                        )}
                    </button>
                    {isBidLimitExceeded && (
                        <span className="text-[10px] text-red-400 font-bold mt-1 uppercase tracking-wide">
                            Max Allowed Bid: {maxAllowedBid}
                        </span>
                    )}
                </div>
            </div>

            {isSquadFull && <p className="text-red-400 text-xs mt-2 flex items-center justify-center sm:justify-start font-bold uppercase"><AlertCircle className="w-3 h-3 mr-1"/> Max Players ({squadLimit}) Reached</p>}
            {isCategoryLimitReached && !isSquadFull && <p className="text-red-400 text-xs mt-2 flex items-center justify-center sm:justify-start font-bold uppercase"><AlertCircle className="w-3 h-3 mr-1"/> {categoryLimitMsg}</p>}
            {isBidLimitExceeded && <p className="text-red-400 text-xs mt-2 flex items-center justify-center sm:justify-start font-bold uppercase"><AlertCircle className="w-3 h-3 mr-1"/> Reserve ({reservedBudget}) required for remaining players</p>}
            {!canAfford && isActive && !isCategoryLimitReached && !isSquadFull && !isBidLimitExceeded && <p className="text-red-400 text-xs mt-2 flex items-center justify-center sm:justify-start font-bold"><AlertCircle className="w-3 h-3 mr-1"/> Insufficient Budget</p>}
            {!isActive && <p className="hidden sm:flex text-red-300 text-xs mt-2 items-center justify-center sm:justify-start font-bold uppercase tracking-wide"><Lock className="w-3 h-3 mr-1"/> Bidding Paused by Admin</p>}
        </div>
    );
};

export default BiddingPanel;

import React, { useState } from 'react';
import { Team, UserRole } from '../types';
import { useAuction } from '../hooks/useAuction';
import { Wallet, Users, Gavel } from 'lucide-react';

interface Props {
    team: Team;
}

const TeamStatusCard: React.FC<Props> = ({ team }) => {
    const { state, placeBid, userProfile, nextBid } = useAuction();
    const { currentPlayerIndex, unsoldPlayers, maxPlayersPerTeam, categories } = state;
    const isAdmin = userProfile?.role === UserRole.ADMIN || userProfile?.role === UserRole.SUPER_ADMIN;
    const isAuctionLive = state.status === 'IN_PROGRESS';
    const currentPlayer = currentPlayerIndex !== null ? unsoldPlayers[currentPlayerIndex] : null;

    // Check Category Limit
    let isLimitReached = false;
    let limitReason = "";

    // 1. Check Global Squad Limit
    const squadLimit = maxPlayersPerTeam || 25;
    if (team.players.length >= squadLimit) {
        isLimitReached = true;
        limitReason = "Squad Full";
    }

    // 2. Check Category Specific Limit (only if global not hit)
    if (!isLimitReached && currentPlayer && currentPlayer.category) {
        const catConfig = categories.find(c => c.name === currentPlayer.category);
        if (catConfig && catConfig.maxPerTeam > 0) {
            const count = team.players.filter(p => p.category === currentPlayer.category).length;
            if (count >= catConfig.maxPerTeam) {
                isLimitReached = true;
                limitReason = "Cat. Limit";
            }
        }
    }

    // 3. Check Bid Limit Rule (Category-wise Squad Protection)
    let reservedBudget = 0;
    if (!isLimitReached && currentPlayer) {
        categories.forEach(cat => {
            if (cat.maxPerTeam > 0) {
                const playersInCat = team.players.filter(p => p.category === cat.name).length;
                let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);
                if (currentPlayer.category === cat.name) {
                    slotsToFill = Math.max(0, slotsToFill - 1);
                }
                reservedBudget += slotsToFill * cat.basePrice;
            }
        });
        const maxAllowedBid = team.budget - reservedBudget;
        if (nextBid > maxAllowedBid) {
            isLimitReached = true;
            limitReason = "Max Bid Limit";
        }
    }

    const canAfford = team.budget >= nextBid;
    const isHighest = state.highestBidder?.id === team.id;

    const handleAdminBid = async () => {
        if (canAfford && !isHighest && !isLimitReached && nextBid > 0) {
            try {
                await placeBid(team.id, nextBid);
            } catch (e) {
                alert((e as Error).message);
            }
        }
    };

    return (
        <div className={`bg-accent p-3 rounded-lg shadow-md transition-all duration-300 ${isHighest ? 'ring-2 ring-green-500 bg-green-900/30' : ''}`}>
            <div className="flex items-center justify-between mb-2">
                <div className="flex items-center">
                    {team.logoUrl ? (
                        <img src={team.logoUrl} alt={team.name} className="w-8 h-8 rounded-full mr-3 bg-white p-0.5" />
                    ) : (
                        <div className="w-8 h-8 rounded-full mr-3 bg-gray-700 flex items-center justify-center font-bold text-white text-xs">
                            {team.name.charAt(0)}
                        </div>
                    )}
                    <div>
                        <h4 className="font-bold text-white text-md truncate max-w-[120px] leading-none">{team.name}</h4>
                        <p className="text-[10px] text-gray-400 font-mono mt-0.5 select-all">ID: {team.id}</p>
                    </div>
                </div>
            </div>

            <div className="text-sm space-y-1">
                <p className="flex items-center text-text-secondary">
                    <Wallet className="w-4 h-4 mr-2 text-green-400" /> 
                    Budget: <span className="font-semibold text-white ml-1">{team.budget}</span>
                </p>
                <p className="flex items-center text-text-secondary">
                    <Users className="w-4 h-4 mr-2 text-blue-400" />
                    Players: <span className={`font-semibold ml-1 ${team.players.length >= squadLimit ? 'text-red-400' : 'text-white'}`}>{team.players.length} / {squadLimit}</span>
                </p>
            </div>

            {isAdmin && isAuctionLive && (
                <div className="mt-3 pt-2 border-t border-white/10">
                    <button 
                        onClick={handleAdminBid}
                        disabled={!canAfford || isHighest || isLimitReached}
                        className={`w-full py-1.5 px-3 rounded text-xs font-bold flex items-center justify-center uppercase tracking-wide transition-colors ${
                            isHighest 
                                ? 'bg-green-600 text-white cursor-default' 
                                : isLimitReached
                                    ? 'bg-red-900/50 text-red-200 border border-red-500/30 cursor-not-allowed'
                                : !canAfford 
                                    ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                                    : 'bg-highlight hover:bg-teal-400 text-primary'
                        }`}
                    >
                        {isHighest ? (
                            <>Leading</>
                        ) : isLimitReached ? (
                            <>{limitReason}</>
                        ) : !canAfford ? (
                            <>No Funds</>
                        ) : (
                            <><Gavel className="w-3 h-3 mr-1"/> Bid {nextBid}</>
                        )}
                    </button>
                </div>
            )}
        </div>
    );
};

export default TeamStatusCard;

import React, { createContext, useState, useEffect, useContext, useMemo } from 'react';
import { AuctionContextType, AuctionState, UserProfile, Team, Player, AuctionStatus, BiddingStatus, AdminViewOverride, BidIncrementSlab, UserRole, SponsorConfig } from '../types';
import { db, auth } from '../firebase';
import firebase from 'firebase/compat/app';

// Initial State
const initialState: AuctionState = {
    players: [],
    teams: [],
    unsoldPlayers: [],
    categories: [],
    roles: [],
    status: AuctionStatus.NotStarted,
    currentPlayerId: null,
    currentPlayerIndex: null,
    currentBid: null,
    highestBidder: null,
    timer: 0,
    bidIncrement: 0,
    bidSlabs: [],
    auctionLog: [],
    biddingStatus: 'PAUSED',
    playerSelectionMode: 'MANUAL',
    auctionLogoUrl: '',
    tournamentName: '',
    sponsors: [],
    sponsorConfig: { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
    projectorLayout: 'STANDARD',
    obsLayout: 'STANDARD',
    adminViewOverride: null,
    maxPlayersPerTeam: 25 // Default
};

export const AuctionContext = createContext<AuctionContextType | null>(null);

export const AuctionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, setState] = useState<AuctionState>(initialState);
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [activeAuctionId, setActiveAuctionId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    // Auth Listener
    useEffect(() => {
        const unsubscribe = auth.onAuthStateChanged(async (user) => {
            if (user) {
                // Check if user is anonymous (Team Owner usually) or Google/Email (Admin)
                if (user.isAnonymous) {
                    // Try to recover session from localStorage if exists
                    const session = localStorage.getItem('sm_sports_team_session');
                    if (session) {
                        const data = JSON.parse(session);
                        setUserProfile({
                            uid: user.uid,
                            email: 'team@smsports.com',
                            role: UserRole.TEAM_OWNER,
                            teamId: data.teamId
                        });
                        if (data.auctionId) joinAuction(data.auctionId);
                    } else {
                        // Just a viewer or lost session
                        setUserProfile({ uid: user.uid, email: 'viewer@smsports.com', role: UserRole.VIEWER });
                    }
                } else {
                    // Admin
                    setUserProfile({
                        uid: user.uid,
                        email: user.email || '',
                        name: user.displayName || '',
                        role: user.email === 'admin@smsports.com' ? UserRole.SUPER_ADMIN : UserRole.ADMIN
                    });
                }
            } else {
                setUserProfile(null);
            }
        });
        return () => unsubscribe();
    }, []);

    // Auction Listener
    useEffect(() => {
        if (!activeAuctionId) return;

        const unsubscribe = db.collection('auctions').doc(activeAuctionId).onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data();
                if (data) {
                    setState(prev => ({
                        ...prev,
                        ...data,
                        // Explicitly map 'slabs' from DB to 'bidSlabs' in state
                        bidSlabs: data.slabs || [],
                        // Explicitly map Title and Logo for display
                        tournamentName: data.title || prev.tournamentName,
                        auctionLogoUrl: data.logoUrl || prev.auctionLogoUrl,
                        // Ensure sponsorConfig has defaults
                        sponsorConfig: data.sponsorConfig || prev.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
                        // Map Squad Limit
                        maxPlayersPerTeam: data.playersPerTeam || 25
                    }));
                }
            } else {
                setError("Auction not found");
            }
        }, (err) => {
            console.error("Auction Listener Error", err);
            setError(err.message);
        });

        // Listen to Subcollections
        const unsubTeams = db.collection('auctions').doc(activeAuctionId).collection('teams').onSnapshot(snap => {
            const teams = snap.docs.map(d => ({ id: d.id, ...d.data() } as Team));
            setState(prev => ({ ...prev, teams }));
        });

        const unsubPlayers = db.collection('auctions').doc(activeAuctionId).collection('players').onSnapshot(snap => {
            const allPlayers = snap.docs.map(d => ({ id: d.id, ...d.data() } as Player));
            setState(prev => ({ ...prev, players: allPlayers }));
        });

        const unsubCategories = db.collection('auctions').doc(activeAuctionId).collection('categories').onSnapshot(snap => {
             const categories = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, categories }));
        });

        const unsubSponsors = db.collection('auctions').doc(activeAuctionId).collection('sponsors').onSnapshot(snap => {
             const sponsors = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, sponsors }));
        });

        return () => {
            unsubscribe();
            unsubTeams();
            unsubPlayers();
            unsubCategories();
            unsubSponsors();
        };
    }, [activeAuctionId]);

    const joinAuction = (id: string) => {
        setActiveAuctionId(id);
    };

    const logout = async () => {
        await auth.signOut();
        localStorage.removeItem('sm_sports_team_session');
        setUserProfile(null);
        setActiveAuctionId(null);
        setState(initialState);
    };

    // --- DERIVED STATE (Fixes "Not Automatic Showing" Issue) ---
    // Instead of setting these in the listener, we calculate them whenever players or currentId changes.
    const derivedUnsoldPlayers = useMemo(() => {
        return state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
    }, [state.players]);

    const derivedCurrentPlayerIndex = useMemo(() => {
        if (!state.currentPlayerId || derivedUnsoldPlayers.length === 0) return null;
        const idx = derivedUnsoldPlayers.findIndex(p => String(p.id) === String(state.currentPlayerId));
        return idx !== -1 ? idx : null;
    }, [state.currentPlayerId, derivedUnsoldPlayers]);

    // Merge derived values into the state object consumed by the app
    const activeState = {
        ...state,
        unsoldPlayers: derivedUnsoldPlayers,
        currentPlayerIndex: derivedCurrentPlayerIndex
    };

    // Derived State: nextBid
    const nextBid = useMemo(() => {
        const { currentPlayerId, players, currentBid, bidIncrement, bidSlabs, categories } = state;
        const currentPlayer = players.find(p => String(p.id) === String(currentPlayerId));

        if (!currentPlayer) return 0;

        const basePrice = Number(currentPlayer.basePrice) || 0;
        const currentPrice = Number(currentBid) || 0;

        // SCENARIO 1: No bids yet (First Bid)
        if (currentPrice === 0) {
            return basePrice > 0 ? basePrice : (bidIncrement || 100);
        }

        // 1. Check Category Specific Rules First (Specific overrides General)
        if (currentPlayer.category) {
            const cat = categories.find(c => c.name === currentPlayer.category);

            // Category Slabs
            if (cat && cat.slabs && cat.slabs.length > 0) {
                 const sortedSlabs = [...cat.slabs].sort((a, b) => b.from - a.from);
                 const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
                 if (activeSlab) {
                     return currentPrice + Number(activeSlab.increment);
                 }
            }

            // Category specific increment (without slabs)
            if (cat && cat.bidIncrement > 0) {
                return currentPrice + Number(cat.bidIncrement);
            }
        }

        // 2. Check Global Slabs
        if (bidSlabs && bidSlabs.length > 0) {
            const sortedSlabs = [...bidSlabs].sort((a, b) => b.from - a.from);
            const activeSlab = sortedSlabs.find(s => currentPrice >= s.from);
            if (activeSlab) {
                return currentPrice + Number(activeSlab.increment);
            }
        }

        // 3. Default Global Increment
        return currentPrice + (Number(bidIncrement) || 100);
    }, [state.currentBid, state.currentPlayerId, state.players, state.bidIncrement, state.bidSlabs, state.categories]);

    // Implementation of actions
    const placeBid = async (teamId: string | number, amount: number) => {
        if (!activeAuctionId) return;
        const team = state.teams.find(t => String(t.id) === String(teamId));
        if (!team) throw new Error("Team not found");

        const currentPlayer = state.players.find(p => String(p.id) === String(state.currentPlayerId));

        // --- BID LIMIT RULE VALIDATION ---
        if (currentPlayer) {
            let reservedBudget = 0;
            state.categories.forEach(cat => {
                if (cat.maxPerTeam > 0) {
                    const playersInCat = team.players.filter(p => p.category === cat.name).length;
                    let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);

                    // If current player belongs to this category, we count this bid as filling one slot (so don't reserve for it)
                    if (currentPlayer.category === cat.name) {
                        slotsToFill = Math.max(0, slotsToFill - 1);
                    }

                    reservedBudget += slotsToFill * cat.basePrice;
                }
            });

            const maxAllowedBid = team.budget - reservedBudget;
            if (amount > maxAllowedBid) {
                throw new Error(`Bid Limit Reached! Max allowable bid is ${maxAllowedBid} to ensure squad completion.`);
            }
        }
        // ---------------------------------

        const log = {
            message: `${team.name} bid ${amount}`,
            timestamp: Date.now(),
            type: 'BID'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: amount,
            highestBidder: team,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const sellPlayer = async (teamId?: string | number, customPrice?: number) => {
        if (!activeAuctionId || !state.currentPlayerId) return;

        const finalTeam = teamId ? state.teams.find(t => String(t.id) === String(teamId)) : state.highestBidder;
        const finalPrice = customPrice !== undefined ? customPrice : (state.currentBid || 0);

        if (!finalTeam) throw new Error("No team selected to sell to");

        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.runTransaction(async (transaction) => {
            const auctionRef = db.collection('auctions').doc(activeAuctionId);
            const playerRef = auctionRef.collection('players').doc(String(player.id));
            const teamRef = auctionRef.collection('teams').doc(String(finalTeam.id));

            // CRITICAL CHECK: Ensure team doc exists before reading data
            const teamDoc = await transaction.get(teamRef);
            if (!teamDoc.exists) {
                throw new Error("Target team document does not exist in database");
            }
            const teamData = teamDoc.data() as Team;

            transaction.update(playerRef, {
                status: 'SOLD',
                soldPrice: finalPrice,
                soldTo: finalTeam.name
            });

            const updatedPlayers = [...(teamData.players || []), { ...player, status: 'SOLD', soldPrice: finalPrice, soldTo: finalTeam.name }];
            const newBudget = (teamData.budget || 0) - finalPrice;

            transaction.update(teamRef, {
                budget: newBudget,
                players: updatedPlayers
            });

            const log = {
                message: `${player.name} SOLD to ${finalTeam.name} for ${finalPrice}`,
                timestamp: Date.now(),
                type: 'SOLD'
            };

            transaction.update(auctionRef, {
                status: AuctionStatus.Sold, 
                auctionLog: firebase.firestore.FieldValue.arrayUnion(log),
                currentBid: finalPrice,
                highestBidder: finalTeam
            });
        });
    };

    const passPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(player.id)).update({
            status: 'UNSOLD'
        });

        const log = {
            message: `${player.name} UNSOLD`,
            timestamp: Date.now(),
            type: 'UNSOLD'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Unsold,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const startAuction = async (specificPlayerId?: string | number) => {
        if (!activeAuctionId) return false;

        let nextPlayerId = specificPlayerId;

        if (!nextPlayerId) {
            const available = state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
            if (available.length === 0) return false;
            const next = available[Math.floor(Math.random() * available.length)];
            nextPlayerId = next.id;
        }

        if (!nextPlayerId) return false;

        const player = state.players.find(p => String(p.id) === String(nextPlayerId));

        await db.collection('auctions').doc(activeAuctionId).update({
            currentPlayerId: nextPlayerId,
            currentBid: 0,
            highestBidder: null,
            status: AuctionStatus.InProgress,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `Bidding started for ${player?.name}`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });

        return true;
    };

    const resetCurrentPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: 0,
            highestBidder: null,
            timer: 10,
            status: AuctionStatus.InProgress
        });
    };

    const endAuction = async () => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Finished,
            currentPlayerId: null
        });
    };

    const resetAuction = async () => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        // 1. Fetch Default Purse from Auction Config
        const auctionSnap = await auctionRef.get();
        if (!auctionSnap.exists) return;
        const defaultPurse = auctionSnap.data()?.purseValue || 10000;

        // 2. Fetch all Teams and Players to reset
        const playersSnap = await auctionRef.collection('players').get();
        const teamsSnap = await auctionRef.collection('teams').get();

        // OPTIMIZATION: Only reset players that have been modified to reduce write volume
        const modifiedPlayers = playersSnap.docs.filter(d => {
            const data = d.data();
            return data.status !== undefined || data.soldPrice !== undefined || data.soldTo !== undefined;
        });

        // 3. Batched Updates (Chunks of 300 to prevent Write Stream Exhaustion)
        const batchSize = 300;
        const allDocs = [
            ...modifiedPlayers.map(d => ({ type: 'PLAYER', ref: d.ref })),
            ...teamsSnap.docs.map(d => ({ type: 'TEAM', ref: d.ref }))
        ];

        // Process in chunks with delay
        for (let i = 0; i < allDocs.length; i += batchSize) {
            const batch = db.batch();
            const chunk = allDocs.slice(i, i + batchSize);

            chunk.forEach(item => {
                if (item.type === 'PLAYER') {
                    batch.update(item.ref, {
                        status: firebase.firestore.FieldValue.delete(),
                        soldPrice: firebase.firestore.FieldValue.delete(),
                        soldTo: firebase.firestore.FieldValue.delete()
                    });
                } else {
                    batch.update(item.ref, {
                        budget: defaultPurse,
                        players: []
                    });
                }
            });

            // Only update root auction doc in the first batch
            if (i === 0) {
                batch.update(auctionRef, {
                    status: AuctionStatus.NotStarted,
                    currentPlayerId: null,
                    currentBid: 0,
                    highestBidder: null,
                    auctionLog: [],
                    timer: 0
                });
            }

            await batch.commit();
            // Throttling: Wait 200ms between batches to clear write stream buffer
            await new Promise(resolve => setTimeout(resolve, 200));
        }

        // If there were no sub-docs, we still need to reset the auction status
        if (allDocs.length === 0) {
             await auctionRef.update({
                status: AuctionStatus.NotStarted,
                currentPlayerId: null,
                currentBid: 0,
                highestBidder: null,
                auctionLog: [],
                timer: 0
            });
        }
    };

    const resetUnsoldPlayers = async () => {
        if (!activeAuctionId) return;
        const unsold = state.players.filter(p => p.status === 'UNSOLD');

        // Batching for Unsold Reset (prevent exhaustion if > 500 unsold)
        const batchSize = 300;
        for (let i = 0; i < unsold.length; i += batchSize) {
             const batch = db.batch();
             const chunk = unsold.slice(i, i + batchSize);
             chunk.forEach(p => {
                 const ref = db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(p.id));
                 batch.update(ref, { status: firebase.firestore.FieldValue.delete() });
             });
             await batch.commit();
             // Throttling
             await new Promise(r => setTimeout(r, 100));
        }

        await db.collection('auctions').doc(activeAuctionId).update({
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `${unsold.length} unsold players brought back to pool`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });
    };

    const updateBiddingStatus = async (status: BiddingStatus) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ biddingStatus: status });
    };

    const updateSponsorConfig = async (config: SponsorConfig) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ sponsorConfig: config });
    };

    const toggleSelectionMode = async () => {
        if (!activeAuctionId) return;
        const newMode = state.playerSelectionMode === 'MANUAL' ? 'AUTO' : 'MANUAL';
        await db.collection('auctions').doc(activeAuctionId).update({ playerSelectionMode: newMode });
    };

    const updateTheme = async (type: 'PROJECTOR' | 'OBS', layout: string) => {
        if (!activeAuctionId) return;
        const field = type === 'PROJECTOR' ? 'projectorLayout' : 'obsLayout';
        await db.collection('auctions').doc(activeAuctionId).update({ [field]: layout });
    };

    const setAdminView = async (view: AdminViewOverride | null) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ adminViewOverride: view });
    };

    const correctPlayerSale = async (playerId: string, newTeamId: string | null, newPrice: number) => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        await db.runTransaction(async (t) => {
            const playerRef = auctionRef.collection('players').doc(playerId);
            const playerDoc = await t.get(playerRef);
            const playerData = playerDoc.data() as Player;

            // 1. Revert previous sale if applicable
            if (playerData.status === 'SOLD' && playerData.soldTo) {
                const prevTeam = state.teams.find(tm => tm.name === playerData.soldTo);
                if (prevTeam) {
                    const prevTeamRef = auctionRef.collection('teams').doc(String(prevTeam.id));
                    const prevTeamDoc = await t.get(prevTeamRef);
                    if (prevTeamDoc.exists) {
                        const ptData = prevTeamDoc.data() as Team;
                        const refund = playerData.soldPrice || 0;
                        const newBudget = (ptData.budget || 0) + refund;
                        const newPlayers = (ptData.players || []).filter(p => String(p.id) !== playerId);

                        t.update(prevTeamRef, { budget: newBudget, players: newPlayers });
                    }
                }
            }

            // 2. Apply new sale if newTeamId provided
            if (newTeamId) {
                const newTeamRef = auctionRef.collection('teams').doc(newTeamId);
                const newTeamDoc = await t.get(newTeamRef);
                const newTeamData = newTeamDoc.data() as Team;

                const newBudget = (newTeamData.budget || 0) - newPrice;
                const updatedPlayerObj = { ...playerData, status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name };
                const newPlayers = [...(newTeamData.players || []), updatedPlayerObj];

                t.update(newTeamRef, { budget: newBudget, players: newPlayers });
                t.update(playerRef, { status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name });
            } else {
                t.update(playerRef, { 
                    status: firebase.firestore.FieldValue.delete(), 
                    soldPrice: firebase.firestore.FieldValue.delete(),
                    soldTo: firebase.firestore.FieldValue.delete()
                });
            }
        });
    };

    return (
        <AuctionContext.Provider value={{
            state: activeState, // Pass the state with derived values overrides
            userProfile,
            setUserProfile,
            placeBid,
            sellPlayer,
            passPlayer,
            correctPlayerSale,
            startAuction,
            endAuction,
            resetAuction,
            resetCurrentPlayer,
            resetUnsoldPlayers,
            updateBiddingStatus,
            updateSponsorConfig,
            toggleSelectionMode,
            updateTheme,
            setAdminView,
            logout,
            error,
            joinAuction,
            activeAuctionId,
            nextBid
        }}>
            {children}
        </AuctionContext.Provider>
    );
};

import React, { useEffect, useState, useRef } from 'react';
import { useAuction } from '../hooks/useAuction';
import { useParams } from 'react-router-dom';
import { User, Gavel, DollarSign } from 'lucide-react';
import { Player, Team, AuctionStatus } from '../types';

// Types for our local frozen state
interface OverlayState {
    player: Player | null;
    bid: number;
    bidder: Team | null;
    status: 'WAITING' | 'LIVE' | 'SOLD' | 'UNSOLD' | 'FINISHED';
}

const OBSOverlay: React.FC = () => {
  const { state, joinAuction } = useAuction();
  const { auctionId } = useParams<{ auctionId: string }>();

  // Local state to handle persistence
  const [display, setDisplay] = useState<OverlayState>({
      player: null,
      bid: 0,
      bidder: null,
      status: 'WAITING'
  });

  const [currentSponsorIndex, setCurrentSponsorIndex] = useState(0);
  const loopInterval = state.sponsorConfig?.loopInterval || 5;
  const sponsorsLength = state.sponsors.length;

  useEffect(() => {
      if (sponsorsLength <= 1) return;
      const interval = setInterval(() => {
          setCurrentSponsorIndex(prev => (prev + 1) % sponsorsLength);
      }, loopInterval * 1000);
      return () => clearInterval(interval);
  }, [sponsorsLength, loopInterval]);

  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Force Transparency on Mount
  useEffect(() => {
      const originalBodyBg = document.body.style.backgroundColor;
      const originalHtmlBg = document.documentElement.style.backgroundColor;
      document.body.style.backgroundColor = 'transparent';
      document.documentElement.style.backgroundColor = 'transparent';
      return () => {
          document.body.style.backgroundColor = originalBodyBg;
          document.documentElement.style.backgroundColor = originalHtmlBg;
      };
  }, []);

  useEffect(() => {
      if (auctionId) joinAuction(auctionId);
  }, [auctionId]);

  // --- SYNC LOGIC ---
  useEffect(() => {
      const { currentPlayerId, players, currentBid, highestBidder, status, teams } = state;
      // Look up in full player list to support showing SOLD players (who are removed from unsoldPlayers)
      const currentPlayer = currentPlayerId ? players.find(p => String(p.id) === String(currentPlayerId)) : null;

      if (status === AuctionStatus.Finished) {
           setDisplay({ player: null, bid: 0, bidder: null, status: 'FINISHED' });
           return;
      }

      if (currentPlayer) {
          if (timeoutRef.current) clearTimeout(timeoutRef.current);

          let derivedStatus: 'LIVE' | 'SOLD' | 'UNSOLD' | 'FINISHED' = 'LIVE';
          if (status === AuctionStatus.Sold || currentPlayer.status === 'SOLD') derivedStatus = 'SOLD';
          else if (status === AuctionStatus.Unsold || currentPlayer.status === 'UNSOLD') derivedStatus = 'UNSOLD';

          // Determine Bidder for Sold Status
          let resolvedBidder = highestBidder;

          if (derivedStatus === 'SOLD' && !resolvedBidder && currentPlayer.soldTo) {
             const winningTeam = teams.find(t => t.name === currentPlayer.soldTo);
             if (winningTeam) resolvedBidder = winningTeam;
          }

          setDisplay({
              player: currentPlayer,
              bid: currentPlayer.soldPrice || currentBid || currentPlayer.basePrice,
              bidder: resolvedBidder,
              status: derivedStatus
          });
      } else {
          // No player
          if (display.status !== 'WAITING' && display.status !== 'FINISHED') {
              timeoutRef.current = setTimeout(() => {
                  setDisplay({ player: null, bid: 0, bidder: null, status: 'WAITING' });
              }, 2000); 
          }
      }
  }, [state]);

  if (window.location.protocol === 'blob:') {
      return (
          <div className="min-h-screen w-full flex items-center justify-center bg-black/90 p-10">
              <div className="bg-red-600/20 border border-red-500 text-white p-8 rounded-xl text-center">
                  <h1 className="text-2xl font-bold mb-2">Preview Mode Detected</h1>
                  <p>Please deploy the app to use the OBS Overlay.</p>
              </div>
          </div>
      );
  }

  // Common Sponsor
  const SponsorLogo = () => (
      state.sponsorConfig?.showOnOBS && state.sponsors.length > 0 && (
          <div className="absolute top-6 right-6 w-40 h-24 bg-white/90 backdrop-blur rounded-xl shadow-lg p-2 flex items-center justify-center z-50 border-2 border-white/20 overflow-hidden">
               <img 
                  src={state.sponsors[currentSponsorIndex]?.imageUrl} 
                  className="max-w-full max-h-full object-contain"
                  alt="Sponsor"
