import React, { createContext, useState, useEffect, useContext, useMemo } from 'react';
import { AuctionContextType, AuctionState, UserProfile, Team, Player, AuctionStatus, BiddingStatus, AdminViewOverride, BidIncrementSlab, UserRole, SponsorConfig } from '../types';
import { db, auth } from '../firebase';
import firebase from 'firebase/compat/app';

// Initial State
const initialState: AuctionState = {
    players: [],
    teams: [],
    unsoldPlayers: [],
    categories: [],
    roles: [],
    status: AuctionStatus.NotStarted,
    currentPlayerId: null,
    currentPlayerIndex: null,
    currentBid: null,
    highestBidder: null,
    timer: 0,
    bidIncrement: 0,
    bidSlabs: [],
    auctionLog: [],
    biddingStatus: 'PAUSED',
    playerSelectionMode: 'MANUAL',
    auctionLogoUrl: '',
    tournamentName: '',
    sponsors: [],
    sponsorConfig: { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
    projectorLayout: 'STANDARD',
    obsLayout: 'STANDARD',
    adminViewOverride: null,
    maxPlayersPerTeam: 25 // Default
};

export const AuctionContext = createContext<AuctionContextType | null>(null);

export const AuctionProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [state, setState] = useState<AuctionState>(initialState);
    const [userProfile, setUserProfile] = useState<UserProfile | null>(null);
    const [activeAuctionId, setActiveAuctionId] = useState<string | null>(null);
    const [error, setError] = useState<string | null>(null);

    // Auth Listener
    useEffect(() => {
        const unsubscribe = auth.onAuthStateChanged(async (user) => {
            if (user) {
                // Check if user is anonymous (Team Owner usually) or Google/Email (Admin)
                if (user.isAnonymous) {
                    // Try to recover session from localStorage if exists
                    const session = localStorage.getItem('sm_sports_team_session');
                    if (session) {
                        const data = JSON.parse(session);
                        setUserProfile({
                            uid: user.uid,
                            email: 'team@smsports.com',
                            role: UserRole.TEAM_OWNER,
                            teamId: data.teamId
                        });
                        if (data.auctionId) joinAuction(data.auctionId);
                    } else {
                        // Just a viewer or lost session
                        setUserProfile({ uid: user.uid, email: 'viewer@smsports.com', role: UserRole.VIEWER });
                    }
                } else {
                    // Admin
                    setUserProfile({
                        uid: user.uid,
                        email: user.email || '',
                        name: user.displayName || '',
                        role: user.email === 'admin@smsports.com' ? UserRole.SUPER_ADMIN : UserRole.ADMIN
                    });
                }
            } else {
                setUserProfile(null);
            }
        });
        return () => unsubscribe();
    }, []);

    // Auction Listener
    useEffect(() => {
        if (!activeAuctionId) return;

        const unsubscribe = db.collection('auctions').doc(activeAuctionId).onSnapshot((doc) => {
            if (doc.exists) {
                const data = doc.data();
                if (data) {
                    setState(prev => ({
                        ...prev,
                        ...data,
                        // Explicitly map 'slabs' from DB to 'bidSlabs' in state
                        bidSlabs: data.slabs || [],
                        // Explicitly map Title and Logo for display
                        tournamentName: data.title || prev.tournamentName,
                        auctionLogoUrl: data.logoUrl || prev.auctionLogoUrl,
                        // Ensure sponsorConfig has defaults
                        sponsorConfig: data.sponsorConfig || prev.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 },
                        // Map Squad Limit
                        maxPlayersPerTeam: data.playersPerTeam || 25
                    }));
                }
            } else {
                setError("Auction not found");
            }
        }, (err) => {
            console.error("Auction Listener Error", err);
            setError(err.message);
        });

        // Listen to Subcollections
        const unsubTeams = db.collection('auctions').doc(activeAuctionId).collection('teams').onSnapshot(snap => {
            const teams = snap.docs.map(d => ({ id: d.id, ...d.data() } as Team));
            setState(prev => ({ ...prev, teams }));
        });

        const unsubPlayers = db.collection('auctions').doc(activeAuctionId).collection('players').onSnapshot(snap => {
            const allPlayers = snap.docs.map(d => ({ id: d.id, ...d.data() } as Player));
            setState(prev => ({ ...prev, players: allPlayers }));
        });

        const unsubCategories = db.collection('auctions').doc(activeAuctionId).collection('categories').onSnapshot(snap => {
             const categories = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, categories }));
        });

        const unsubSponsors = db.collection('auctions').doc(activeAuctionId).collection('sponsors').onSnapshot(snap => {
             const sponsors = snap.docs.map(d => ({ id: d.id, ...d.data() } as any));
             setState(prev => ({ ...prev, sponsors }));
        });

        return () => {
            unsubscribe();
            unsubTeams();
            unsubPlayers();
            unsubCategories();
            unsubSponsors();
        };
    }, [activeAuctionId]);

    const joinAuction = (id: string) => {
        setActiveAuctionId(id);
    };

    const logout = async () => {
        await auth.signOut();
        localStorage.removeItem('sm_sports_team_session');
        setUserProfile(null);
        setActiveAuctionId(null);
        setState(initialState);
    };

    // --- DERIVED STATE (Fixes "Not Automatic Showing" Issue) ---
    // Instead of setting these in the listener, we calculate them whenever players or currentId changes.
    const derivedUnsoldPlayers = useMemo(() => {
        return state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
    }, [state.players]);

    const derivedCurrentPlayerIndex = useMemo(() => {
        if (!state.currentPlayerId || derivedUnsoldPlayers.length === 0) return null;
        const idx = derivedUnsoldPlayers.findIndex(p => String(p.id) === String(state.currentPlayerId));
        return idx !== -1 ? idx : null;
    }, [state.currentPlayerId, derivedUnsoldPlayers]);

    // Merge derived values into the state object consumed by the app
    const activeState = {
        ...state,
        unsoldPlayers: derivedUnsoldPlayers,
        currentPlayerIndex: derivedCurrentPlayerIndex
    };

    // Derived State: nextBid
    const nextBid = useMemo(() => {
        const { currentPlayerId, players, currentBid, bidIncrement, bidSlabs, categories } = state;
        const currentPlayer = players.find(p => String(p.id) === String(currentPlayerId));

        if (!currentPlayer) return 0;

        const basePrice = Number(currentPlayer.basePrice) || 0;
        const currentPrice = Number(currentBid) || 0;

        // SCENARIO 1: No bids yet (First Bid)
        if (currentPrice === 0) {
            return basePrice > 0 ? basePrice : (Number(bidIncrement) || 100);
        }

        // Priority 1: Category Specific Slabs
        if (currentPlayer.category) {
            const cat = categories.find(c => c.name === currentPlayer.category);
            if (cat && cat.slabs && cat.slabs.length > 0) {
                 const sortedSlabs = [...cat.slabs].sort((a, b) => Number(b.from) - Number(a.from));
                 const activeSlab = sortedSlabs.find(s => currentPrice >= Number(s.from));
                 if (activeSlab) {
                     return currentPrice + Number(activeSlab.increment);
                 }
            }
        }

        // Priority 2: Global Slabs
        if (bidSlabs && bidSlabs.length > 0) {
            const sortedSlabs = [...bidSlabs].sort((a, b) => Number(b.from) - Number(a.from));
            const activeSlab = sortedSlabs.find(s => currentPrice >= Number(s.from));
            if (activeSlab) {
                return currentPrice + Number(activeSlab.increment);
            }
        }

        // Priority 3: Category Specific Flat Increment (Only if no slabs matched)
        if (currentPlayer.category) {
            const cat = categories.find(c => c.name === currentPlayer.category);
            // Only apply if strictly defined and > 0.
            if (cat && cat.bidIncrement > 0) {
                return currentPrice + Number(cat.bidIncrement);
            }
        }

        // Priority 4: Default Global Increment
        return currentPrice + (Number(bidIncrement) || 100);
    }, [state.currentBid, state.currentPlayerId, state.players, state.bidIncrement, state.bidSlabs, state.categories]);

    // Implementation of actions
    const placeBid = async (teamId: string | number, amount: number) => {
        if (!activeAuctionId) return;
        const team = state.teams.find(t => String(t.id) === String(teamId));
        if (!team) throw new Error("Team not found");

        const currentPlayer = state.players.find(p => String(p.id) === String(state.currentPlayerId));

        // --- BID LIMIT RULE VALIDATION ---
        if (currentPlayer) {
            let reservedBudget = 0;
            state.categories.forEach(cat => {
                if (cat.maxPerTeam > 0) {
                    const playersInCat = team.players.filter(p => p.category === cat.name).length;
                    let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);

                    // If current player belongs to this category, we count this bid as filling one slot (so don't reserve for it)
                    if (currentPlayer.category === cat.name) {
                        slotsToFill = Math.max(0, slotsToFill - 1);
                    }

                    reservedBudget += slotsToFill * cat.basePrice;
                }
            });

            const maxAllowedBid = team.budget - reservedBudget;
            if (amount > maxAllowedBid) {
                throw new Error(`Bid Limit Reached! Max allowable bid is ${maxAllowedBid} to ensure squad completion.`);
            }
        }
        // ---------------------------------

        const log = {
            message: `${team.name} bid ${amount}`,
            timestamp: Date.now(),
            type: 'BID'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: amount,
            highestBidder: team,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const sellPlayer = async (teamId?: string | number, customPrice?: number) => {
        if (!activeAuctionId || !state.currentPlayerId) return;

        const finalTeam = teamId ? state.teams.find(t => String(t.id) === String(teamId)) : state.highestBidder;
        const finalPrice = customPrice !== undefined ? customPrice : (state.currentBid || 0);

        if (!finalTeam) throw new Error("No team selected to sell to");

        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.runTransaction(async (transaction) => {
            const auctionRef = db.collection('auctions').doc(activeAuctionId);
            const playerRef = auctionRef.collection('players').doc(String(player.id));
            const teamRef = auctionRef.collection('teams').doc(String(finalTeam.id));

            // CRITICAL CHECK: Ensure team doc exists before reading data
            const teamDoc = await transaction.get(teamRef);
            if (!teamDoc.exists) {
                throw new Error("Target team document does not exist in database");
            }
            const teamData = teamDoc.data() as Team;

            transaction.update(playerRef, {
                status: 'SOLD',
                soldPrice: finalPrice,
                soldTo: finalTeam.name
            });

            const updatedPlayers = [...(teamData.players || []), { ...player, status: 'SOLD', soldPrice: finalPrice, soldTo: finalTeam.name }];
            const newBudget = (teamData.budget || 0) - finalPrice;

            transaction.update(teamRef, {
                budget: newBudget,
                players: updatedPlayers
            });

            const log = {
                message: `${player.name} SOLD to ${finalTeam.name} for ${finalPrice}`,
                timestamp: Date.now(),
                type: 'SOLD'
            };

            transaction.update(auctionRef, {
                status: AuctionStatus.Sold, 
                auctionLog: firebase.firestore.FieldValue.arrayUnion(log),
                currentBid: finalPrice,
                highestBidder: finalTeam
            });
        });
    };

    const passPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        const player = state.players.find(p => String(p.id) === String(state.currentPlayerId));
        if (!player) return;

        await db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(player.id)).update({
            status: 'UNSOLD'
        });

        const log = {
            message: `${player.name} UNSOLD`,
            timestamp: Date.now(),
            type: 'UNSOLD'
        };

        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Unsold,
            auctionLog: firebase.firestore.FieldValue.arrayUnion(log)
        });
    };

    const startAuction = async (specificPlayerId?: string | number) => {
        if (!activeAuctionId) return false;

        let nextPlayerId = specificPlayerId;

        if (!nextPlayerId) {
            const available = state.players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
            if (available.length === 0) return false;
            const next = available[Math.floor(Math.random() * available.length)];
            nextPlayerId = next.id;
        }

        if (!nextPlayerId) return false;

        const player = state.players.find(p => String(p.id) === String(nextPlayerId));

        await db.collection('auctions').doc(activeAuctionId).update({
            currentPlayerId: nextPlayerId,
            currentBid: 0,
            highestBidder: null,
            status: AuctionStatus.InProgress,
            timer: 10,
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `Bidding started for ${player?.name}`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });

        return true;
    };

    const undoPlayerSelection = async () => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            currentPlayerId: null,
            currentBid: 0,
            highestBidder: null,
            status: AuctionStatus.NotStarted
        });
    };

    const resetCurrentPlayer = async () => {
        if (!activeAuctionId || !state.currentPlayerId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            currentBid: 0,
            highestBidder: null,
            timer: 10,
            status: AuctionStatus.InProgress
        });
    };

    const endAuction = async () => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({
            status: AuctionStatus.Finished,
            currentPlayerId: null
        });
    };

    const resetAuction = async () => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        // 1. Fetch Default Purse from Auction Config
        const auctionSnap = await auctionRef.get();
        if (!auctionSnap.exists) return;
        const defaultPurse = auctionSnap.data()?.purseValue || 10000;

        // 2. Fetch all Teams and Players to reset
        const playersSnap = await auctionRef.collection('players').get();
        const teamsSnap = await auctionRef.collection('teams').get();

        // OPTIMIZATION: Only reset players that have been modified to reduce write volume
        const modifiedPlayers = playersSnap.docs.filter(d => {
            const data = d.data();
            return data.status !== undefined || data.soldPrice !== undefined || data.soldTo !== undefined;
        });

        // 3. Batched Updates (Chunks of 300 to prevent Write Stream Exhaustion)
        const batchSize = 300;
        const allDocs = [
            ...modifiedPlayers.map(d => ({ type: 'PLAYER', ref: d.ref })),
            ...teamsSnap.docs.map(d => ({ type: 'TEAM', ref: d.ref }))
        ];

        // Process in chunks with delay
        for (let i = 0; i < allDocs.length; i += batchSize) {
            const batch = db.batch();
            const chunk = allDocs.slice(i, i + batchSize);

            chunk.forEach(item => {
                if (item.type === 'PLAYER') {
                    batch.update(item.ref, {
                        status: firebase.firestore.FieldValue.delete(),
                        soldPrice: firebase.firestore.FieldValue.delete(),
                        soldTo: firebase.firestore.FieldValue.delete()
                    });
                } else {
                    batch.update(item.ref, {
                        budget: defaultPurse,
                        players: []
                    });
                }
            });

            // Only update root auction doc in the first batch
            if (i === 0) {
                batch.update(auctionRef, {
                    status: AuctionStatus.NotStarted,
                    currentPlayerId: null,
                    currentBid: 0,
                    highestBidder: null,
                    auctionLog: [],
                    timer: 0
                });
            }

            await batch.commit();
            // Throttling: Wait 200ms between batches to clear write stream buffer
            await new Promise(resolve => setTimeout(resolve, 200));
        }

        // If there were no sub-docs, we still need to reset the auction status
        if (allDocs.length === 0) {
             await auctionRef.update({
                status: AuctionStatus.NotStarted,
                currentPlayerId: null,
                currentBid: 0,
                highestBidder: null,
                auctionLog: [],
                timer: 0
            });
        }
    };

    const resetUnsoldPlayers = async () => {
        if (!activeAuctionId) return;
        const unsold = state.players.filter(p => p.status === 'UNSOLD');

        // Batching for Unsold Reset (prevent exhaustion if > 500 unsold)
        const batchSize = 300;
        for (let i = 0; i < unsold.length; i += batchSize) {
             const batch = db.batch();
             const chunk = unsold.slice(i, i + batchSize);
             chunk.forEach(p => {
                 const ref = db.collection('auctions').doc(activeAuctionId).collection('players').doc(String(p.id));
                 batch.update(ref, { status: firebase.firestore.FieldValue.delete() });
             });
             await batch.commit();
             // Throttling
             await new Promise(r => setTimeout(r, 100));
        }

        await db.collection('auctions').doc(activeAuctionId).update({
            auctionLog: firebase.firestore.FieldValue.arrayUnion({
                message: `${unsold.length} unsold players brought back to pool`,
                timestamp: Date.now(),
                type: 'SYSTEM'
            })
        });
    };

    const updateBiddingStatus = async (status: BiddingStatus) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ biddingStatus: status });
    };

    const updateSponsorConfig = async (config: SponsorConfig) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ sponsorConfig: config });
    };

    const toggleSelectionMode = async () => {
        if (!activeAuctionId) return;
        const newMode = state.playerSelectionMode === 'MANUAL' ? 'AUTO' : 'MANUAL';
        await db.collection('auctions').doc(activeAuctionId).update({ playerSelectionMode: newMode });
    };

    const updateTheme = async (type: 'PROJECTOR' | 'OBS', layout: string) => {
        if (!activeAuctionId) return;
        const field = type === 'PROJECTOR' ? 'projectorLayout' : 'obsLayout';
        await db.collection('auctions').doc(activeAuctionId).update({ [field]: layout });
    };

    const setAdminView = async (view: AdminViewOverride | null) => {
        if (!activeAuctionId) return;
        await db.collection('auctions').doc(activeAuctionId).update({ adminViewOverride: view });
    };

    const correctPlayerSale = async (playerId: string, newTeamId: string | null, newPrice: number) => {
        if (!activeAuctionId) return;

        const auctionRef = db.collection('auctions').doc(activeAuctionId);

        await db.runTransaction(async (t) => {
            const playerRef = auctionRef.collection('players').doc(playerId);
            const playerDoc = await t.get(playerRef);
            const playerData = playerDoc.data() as Player;

            // 1. Revert previous sale if applicable
            if (playerData.status === 'SOLD' && playerData.soldTo) {
                const prevTeam = state.teams.find(tm => tm.name === playerData.soldTo);
                if (prevTeam) {
                    const prevTeamRef = auctionRef.collection('teams').doc(String(prevTeam.id));
                    const prevTeamDoc = await t.get(prevTeamRef);
                    if (prevTeamDoc.exists) {
                        const ptData = prevTeamDoc.data() as Team;
                        const refund = playerData.soldPrice || 0;
                        const newBudget = (ptData.budget || 0) + refund;
                        const newPlayers = (ptData.players || []).filter(p => String(p.id) !== playerId);

                        t.update(prevTeamRef, { budget: newBudget, players: newPlayers });
                    }
                }
            }

            // 2. Apply new sale if newTeamId provided
            if (newTeamId) {
                const newTeamRef = auctionRef.collection('teams').doc(newTeamId);
                const newTeamDoc = await t.get(newTeamRef);
                const newTeamData = newTeamDoc.data() as Team;

                const newBudget = (newTeamData.budget || 0) - newPrice;
                const updatedPlayerObj = { ...playerData, status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name };
                const newPlayers = [...(newTeamData.players || []), updatedPlayerObj];

                t.update(newTeamRef, { budget: newBudget, players: newPlayers });
                t.update(playerRef, { status: 'SOLD', soldPrice: newPrice, soldTo: newTeamData.name });
            } else {
                t.update(playerRef, { 
                    status: firebase.firestore.FieldValue.delete(), 
                    soldPrice: firebase.firestore.FieldValue.delete(),
                    soldTo: firebase.firestore.FieldValue.delete()
                });
            }
        });
    };

    return (
        <AuctionContext.Provider value={{
            state: activeState, // Pass the state with derived values overrides
            userProfile,
            setUserProfile,
            placeBid,
            sellPlayer,
            passPlayer,
            correctPlayerSale,
            startAuction,
            undoPlayerSelection, // Export new function
            endAuction,
            resetAuction,
            resetCurrentPlayer,
            resetUnsoldPlayers,
            updateBiddingStatus,
            updateSponsorConfig,
            toggleSelectionMode,
            updateTheme,
            setAdminView,
            logout,
            error,
            joinAuction,
            activeAuctionId,
            nextBid
        }}>
            {children}
        </AuctionContext.Provider>
    );
};

import React, { useState, useEffect, useMemo } from 'react';
import { useAuction } from '../hooks/useAuction';
import { AuctionStatus, Team, Player, ProjectorLayout, OBSLayout } from '../types';
import TeamStatusCard from '../components/TeamStatusCard';
import { Play, Check, X, ArrowLeft, Loader2, RotateCcw, AlertOctagon, DollarSign, Cast, Lock, Unlock, Monitor, ChevronDown, Shuffle, Search, User, Palette, Trophy, Gavel, Wallet, Eye, EyeOff, Clock, Zap, Undo2 } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const LiveAdminPanel: React.FC = () => {
  const { state, sellPlayer, passPlayer, startAuction, undoPlayerSelection, endAuction, resetAuction, resetCurrentPlayer, resetUnsoldPlayers, updateBiddingStatus, toggleSelectionMode, updateTheme, activeAuctionId, placeBid, nextBid, updateSponsorConfig } = useAuction();
  const { teams, players, biddingStatus, playerSelectionMode, categories, maxPlayersPerTeam } = state;
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(false);

  // Inline Sell State
  const [isSellingMode, setIsSellingMode] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string>('');
  const [finalPrice, setFinalPrice] = useState<number>(0);

  // Manual Player Selection State
  const [manualPlayerId, setManualPlayerId] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState(''); // New search state
  const [showUnsold, setShowUnsold] = useState(false); // Toggle to include unsold players

  // Sponsor Config Local State (debounce or immediate)
  const [sponsorLoop, setSponsorLoop] = useState(state.sponsorConfig?.loopInterval || 5);

  // Auto-fill price and leader when entering sell mode or when bid updates
  useEffect(() => {
      // 1. Determine Price
      if (state.currentBid !== null && state.currentBid > 0) {
          setFinalPrice(Number(state.currentBid));
      } else if (state.currentPlayerId) {
          // Fallback to Base Price if no bids
          const p = players.find(player => String(player.id) === String(state.currentPlayerId));
          if (p) setFinalPrice(p.basePrice);
      }

      // 2. Determine Team
      if (state.highestBidder) {
          setSelectedTeamId(String(state.highestBidder.id));
      } else if (!isSellingMode) {
          // Reset selection only if we aren't currently editing
          setSelectedTeamId('');
      }
  }, [state.currentBid, state.highestBidder, isSellingMode, state.currentPlayerId, players]);

  // Sync sponsor loop state
  useEffect(() => {
      if(state.sponsorConfig?.loopInterval) setSponsorLoop(state.sponsorConfig.loopInterval);
  }, [state.sponsorConfig]);

  const handleStart = async (specificId?: string) => {
      if (teams.length === 0) {
          alert("Cannot start auction: No teams added. Please go back to Dashboard > Edit Auction > Teams to add teams.");
          return;
      }

      const availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
      if (availablePlayers.length === 0 && !showUnsold) {
          alert("Cannot start auction: No more players available.");
          return;
      }

      setIsProcessing(true);
      const hasNextPlayer = await startAuction(specificId);

      if (!hasNextPlayer && !showUnsold) {
          if (window.confirm("No more players available in the pool.\n\nDo you want to MARK AUCTION AS COMPLETED?")) {
              await endAuction();
          }
      } else {
          // Clear manual selection
          setManualPlayerId('');
          setSearchTerm('');
      }
      setIsProcessing(false);
  }

  const handleResetFull = async () => {
      if(!window.confirm("WARNING: This will reset the auction status to 'Not Started'. It will NOT remove sold players from teams. Proceed?")) return;
      setIsProcessing(true);
      await resetAuction();
      setIsProcessing(false);
  }

  const handleResetPlayer = async () => {
      if(!window.confirm("This will clear the current bid and timer for this player. Proceed?")) return;
      setIsProcessing(true);
      await resetCurrentPlayer();
      setIsProcessing(false);
  }

  const handleCancelSelection = async () => {
      if(!window.confirm("Change Player? This will cancel the current round and allow you to select a different player.")) return;
      setIsProcessing(true);
      await undoPlayerSelection();
      setIsProcessing(false);
  }

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!activeAuctionId) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      const url = `${baseUrl}#/${route}/${activeAuctionId}`;
      navigator.clipboard.writeText(url);

      if (type === 'green') {
          alert("PROJECTOR VIEW URL Copied!\n\nOpen this link on the projector screen.");
      } else {
          alert("OBS OVERLAY URL Copied!\n\nPaste this into OBS Browser Source.");
      }
  };

  const handleSellClick = () => {
      setIsSellingMode(true);
  };

  const cancelSell = () => {
      setIsSellingMode(false);
  };

  const confirmSell = async () => {
      if (!selectedTeamId) {
          alert("Please select a team to sell to.");
          return;
      }
      if (finalPrice <= 0) {
          alert("Price must be greater than 0.");
          return;
      }

      setIsProcessing(true);
      try {
          await sellPlayer(selectedTeamId, finalPrice);
          setIsSellingMode(false);
      } catch(e) {
          console.error(e);
          alert("Failed to sell player. Check console.");
      } finally {
          setIsProcessing(false);
      }
  };

  const handlePass = async () => {
      if (window.confirm("Confirm UNSOLD?")) {
          setIsProcessing(true);
          await passPlayer();
          setIsProcessing(false);
      }
  }

  const handleQuickBid = async (teamId: string | number) => {
      try {
          await placeBid(teamId, nextBid);
      } catch (e) {
          console.error(e);
          // Optional: Show toast error
      }
  };

  const updateSponsorVisibility = (target: 'OBS' | 'PROJECTOR') => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      const newConfig = {
          ...current,
          showOnOBS: target === 'OBS' ? !current.showOnOBS : current.showOnOBS,
          showOnProjector: target === 'PROJECTOR' ? !current.showOnProjector : current.showOnProjector
      };
      updateSponsorConfig(newConfig);
  };

  const handleSponsorLoopChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = Number(e.target.value);
      setSponsorLoop(val);
  };

  const saveSponsorLoop = () => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      updateSponsorConfig({ ...current, loopInterval: sponsorLoop });
  };

  const selectedPlayerObj = players.find(p => p.id === manualPlayerId);
  const currentPlayer = state.currentPlayerId ? state.players.find(p => String(p.id) === String(state.currentPlayerId)) : null;

  const getControlButtons = () => {
      const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
      const availablePlayersCount = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD').length;
      const isStartDisabled = isProcessing || (state.status === AuctionStatus.NotStarted && (teams.length === 0 || availablePlayersCount === 0));
      const unsoldCount = players.filter(p => p.status === 'UNSOLD').length;

      // NEW: Finish Auction Option
      // Show this if no players are left AND we are not currently bidding on one (isRoundActive is false)
      if (availablePlayersCount === 0 && state.status !== AuctionStatus.NotStarted && !isRoundActive) {
          return (
             <div className="space-y-4 animate-fade-in">
                 {unsoldCount > 0 && (
                     <div className="bg-blue-900/30 border border-blue-500/50 p-4 rounded-xl text-center shadow-inner">
                        <h3 className="text-white font-bold text-lg mb-2">Unsold Players Available</h3>
                        <p className="text-gray-300 text-xs mb-4">There are {unsoldCount} unsold players. Do you want to bring them back into the bidding pool?</p>
                        <button 
                            onClick={async () => {
                                if(window.confirm(`Bring back ${unsoldCount} unsold players to the pool?`)) {
                                    setIsProcessing(true);
                                    await resetUnsoldPlayers();
                                    setIsProcessing(false);
                                }
                            }}
                            disabled={isProcessing}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 rounded-lg shadow-lg transition-all active:scale-95 flex items-center justify-center"
                        >
                            {isProcessing ? <Loader2 className="mr-2 h-4 w-4 animate-spin"/> : <RotateCcw className="mr-2 h-4 w-4"/>}
                            BRING BACK UNSOLD ({unsoldCount})
                        </button>
                     </div>
                 )}

                 <div className="bg-green-900/30 border border-green-500/50 p-6 rounded-xl text-center shadow-inner">
                    <Trophy className="w-12 h-12 text-yellow-400 mx-auto mb-3 drop-shadow-lg" />
                    <h3 className="text-white font-bold text-xl mb-2">Auction Completed!</h3>
                    <p className="text-gray-300 text-sm mb-6">All players have been auctioned. You can now finalize the event.</p>
                    <button 
                        onClick={async () => {
                            if(window.confirm("Are you sure you want to finish the auction? This will enable the summary view for all users.")) {
                                setIsProcessing(true);
                                await endAuction();
                                setIsProcessing(false);
                            }
                        }}
                        disabled={isProcessing}
                        className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-lg shadow-lg shadow-green-900/20 transition-all active:scale-95 flex items-center justify-center tracking-wide"
                    >
                        {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : "GENERATE SUMMARY & FINISH"}
                    </button>
                </div>
            </div>
          );
      }

      // 1. ACTIVE ROUND CONTROLS (SOLD / UNSOLD)
      if (isRoundActive) {
          if (isSellingMode) {
              return (
                  <div className="bg-primary/20 p-3 rounded-lg border border-gray-600 animate-fade-in space-y-3">
                      <div className="flex items-center gap-2 mb-2 text-white font-bold border-b border-gray-600 pb-1">
                          <Check className="w-4 h-4 text-green-500" /> Confirm Sale
                      </div>

                      {/* Inline Form */}
                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Sold To Team</label>
                          <div className="relative">
                            <select 
                                value={selectedTeamId} 
                                onChange={(e) => setSelectedTeamId(e.target.value)}
                                className="w-full bg-primary border border-gray-600 rounded p-2 text-sm text-white outline-none focus:border-green-500 appearance-none"
                            >
                                <option value="">-- Select Team --</option>
                                {teams.map(t => (
                                    <option key={t.id} value={t.id}>{t.name} ({t.budget})</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                          </div>
                      </div>

                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Final Price</label>
                          <div className="relative">
                              <DollarSign className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />
                              <input 
                                type="number" 
                                value={finalPrice} 
                                onChange={(e) => setFinalPrice(Number(e.target.value))}
                                className="w-full bg-primary border border-gray-600 rounded p-2 pl-8 text-sm text-white font-bold outline-none focus:border-green-500"
                              />
                          </div>
                      </div>

                      <div className="flex gap-2 pt-1">
                          <button 
                            onClick={cancelSell}
                            className="flex-1 bg-gray-600 hover:bg-gray-700 text-white py-2 rounded text-sm font-bold transition-colors"
                          >
                              Cancel
                          </button>
                          <button 
                            onClick={confirmSell}
                            disabled={isProcessing}
                            className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 rounded text-sm font-bold shadow-lg flex items-center justify-center transition-colors"
                          >
                              {isProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Confirm'}
                          </button>
                      </div>
                  </div>
              );
          }

          return (
              <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={handleSellClick}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-green-600 hover:bg-green-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <Check className="mb-1 h-6 w-6"/>}
                          {isProcessing ? 'SELLING...' : 'SOLD'}
                      </button>
                      <button 
                        onClick={handlePass}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-red-600 hover:bg-red-700 disabled:bg-gray-700 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <X className="mb-1 h-6 w-6"/>}
                          UNSOLD
                      </button>
                  </div>
                  {/* Cancel / Change Player Button */}
                  <button 
                    onClick={handleCancelSelection} 
                    disabled={isProcessing}
                    className="w-full flex items-center justify-center bg-orange-600 hover:bg-orange-700 text-white font-bold py-2 rounded-lg text-xs transition-colors"
                  >
                      <Undo2 className="w-4 h-4 mr-1" /> Change Player (Cancel Round)
                  </button>
              </div>
          );
      }

      // 2. NEXT PLAYER SELECTION (Based on Mode)
      if (playerSelectionMode === 'MANUAL') {
           // Filter based on search term and unsold toggle
           let availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
           if (showUnsold) {
               const unsoldList = players.filter(p => p.status === 'UNSOLD');
               availablePlayers = [...availablePlayers, ...unsoldList];
           }

           availablePlayers.sort((a, b) => a.name.localeCompare(b.name));

           const filteredPlayers = availablePlayers.filter(p => 
               p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
               p.category.toLowerCase().includes(searchTerm.toLowerCase())
           );

           return (
               <div className="space-y-3 bg-primary/20 p-3 rounded-lg border border-gray-600">
                   <div>
                       <div className="flex justify-between items-center mb-1">
                           <label className="block text-[10px] text-text-secondary uppercase font-bold">Select Next Player</label>
                           <label className="flex items-center text-[10px] text-yellow-400 cursor-pointer">
                               <input type="checkbox" checked={showUnsold} onChange={(e) => setShowUnsold(e.target.checked)} className="mr-1 accent-yellow-500" />
                               Include Unsold
                           </label>
                       </div>

                       {/* Search Input */}
                       <div className="relative mb-2">
                           <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                           <input 
                                type="text"
                                className="w-full bg-gray-900 border border-gray-700 rounded p-1.5 pl-7 text-xs text-white focus:border-highlight outline-none"
                                placeholder="Search player name..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                           />
                       </div>

                       <div className="relative">
                           <select 
                               className="w-full bg-gray-900 text-white text-xs p-3 rounded border border-gray-700 focus:border-highlight outline-none appearance-none cursor-pointer"
                               value={manualPlayerId}
                               onChange={(e) => setManualPlayerId(e.target.value)}
                           >
                               <option value="">-- Choose Player ({filteredPlayers.length}) --</option>
                               {filteredPlayers.map(p => (
                                   <option key={p.id} value={p.id} className={p.status === 'UNSOLD' ? 'text-red-400 font-bold' : ''}>
                                       {p.name} ({p.category}) {p.status === 'UNSOLD' ? '[UNSOLD]' : ''} - Base: {p.basePrice}
                                   </option>
                               ))}
                           </select>
                           <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" />
                       </div>
                   </div>

                   <button 
                     onClick={() => handleStart(manualPlayerId)} 
                     disabled={isStartDisabled || !manualPlayerId}
                     className={`w-full flex items-center justify-center font-bold py-3 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                         ${isStartDisabled || !manualPlayerId
                             ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                             : 'bg-highlight hover:bg-teal-500 text-primary'}`
                     }
                   >
                       {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Play className="mr-2 h-5 w-5"/>} 
                       {manualPlayerId && players.find(p => p.id === manualPlayerId)?.status === 'UNSOLD' ? 'Re-Auction Player' : 'Start Bidding'}
                   </button>
               </div>
           );
      }

      // AUTO MODE
      return (
          <button 
            onClick={() => handleStart()} 
            disabled={isStartDisabled}
            className={`w-full flex items-center justify-center font-bold py-4 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                ${isStartDisabled 
                    ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                    : 'bg-highlight hover:bg-teal-500 text-primary'}`
            }
          >
              {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Shuffle className="mr-2 h-5 w-5"/>} 
              {state.status === AuctionStatus.NotStarted ? 'Start Auction (Auto Random)' : 'Next Random Player'}
          </button>
      );
  }

  // --- RENDER QUICK BID BUTTONS ---
  const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
  const renderQuickBidButtons = () => {
        if (!isRoundActive || isSellingMode) return null;

        return (
            <div className="mb-4">
                <h3 className="text-xs font-bold text-text-secondary uppercase mb-2 flex items-center">
                    <Zap className="w-3 h-3 mr-1 text-yellow-400" /> Quick Bids (Next: {nextBid})
                </h3>
                <div className="grid grid-cols-2 gap-2">
                    {teams.map(team => {
                        // Logic Check
                        let allowed = true;
                        let reason = '';

                        // 1. Budget
                        if (team.budget < nextBid) { allowed = false; reason = 'NO FUNDS'; }
                        // 2. Highest
                        else if (state.highestBidder?.id === team.id) { allowed = false; reason = 'LEADING'; }
                        // 3. Squad Full
                        else if (team.players.length >= (maxPlayersPerTeam || 25)) { allowed = false; reason = 'FULL'; }

                        // 4. Bid Limit & Category
                        else if (currentPlayer) {
                            if (currentPlayer.category) {
                                const catConfig = categories.find(c => c.name === currentPlayer.category);
                                if (catConfig && catConfig.maxPerTeam > 0) {
                                    const count = team.players.filter(p => p.category === currentPlayer.category).length;
                                    if (count >= catConfig.maxPerTeam) { allowed = false; reason = 'CAT LIMIT'; }
                                }
                            }
                            if (allowed) {
                                let reservedBudget = 0;
                                categories.forEach(cat => {
                                    if (cat.maxPerTeam > 0) {
                                        const playersInCat = team.players.filter(p => p.category === cat.name).length;
                                        let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);
                                        if (currentPlayer.category === cat.name) {
                                            slotsToFill = Math.max(0, slotsToFill - 1);
                                        }
                                        reservedBudget += slotsToFill * cat.basePrice;
                                    }
                                });
                                const maxAllowedBid = team.budget - reservedBudget;
                                if (nextBid > maxAllowedBid) { allowed = false; reason = 'MAX BID'; }
                            }
                        }

                        return (
                            <button
                                key={team.id}
                                onClick={() => handleQuickBid(team.id)}
                                disabled={!allowed || isProcessing}
                                className={`
                                    flex items-center justify-between px-2 py-2 rounded border text-left transition-all relative group
                                    ${allowed 
                                        ? 'bg-white border-gray-300 hover:border-green-500 hover:shadow-md active:scale-95' 
                                        : 'bg-gray-200 border-transparent opacity-60 cursor-not-allowed'}
                                `}
                            >
                                <div className="flex items-center gap-2 min-w-0 flex-1">
                                    {team.logoUrl ? (
                                        <img src={team.logoUrl} className="w-6 h-6 rounded-full object-contain bg-gray-100 flex-shrink-0" />
                                    ) : (
                                        <div className="w-6 h-6 rounded-full bg-gray-300 flex items-center justify-center text-[10px] font-bold text-gray-600 flex-shrink-0">
                                            {team.name.charAt(0)}
                                        </div>
                                    )}
                                    <div className="flex flex-col min-w-0">
                                        <span className="text-xs font-bold text-gray-800 truncate leading-none">{team.name}</span>
                                        <span className="text-[9px] text-gray-500 font-mono leading-none mt-0.5">{team.budget}</span>
                                    </div>
                                </div>

                                <div className="flex-shrink-0 ml-1">
                                    {!allowed ? (
                                        <span className="text-[8px] font-black text-red-500 uppercase bg-red-100 px-1 rounded">{reason}</span>
                                    ) : (
                                        <span className="text-[10px] font-bold text-green-600 bg-green-50 px-1.5 py-0.5 rounded group-hover:bg-green-600 group-hover:text-white transition-colors">
                                            +{nextBid}
                                        </span>
                                    )}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
  };

  return (
    <div className="bg-secondary p-4 rounded-lg shadow-lg h-full flex flex-col border border-gray-700 relative">

      <div className="flex justify-between items-center mb-4 border-b border-accent pb-2">
          <div className="flex flex-col gap-2 w-full">
              <div className="flex justify-between items-center w-full">
                <h2 className="text-xl font-bold text-highlight uppercase tracking-wider">Auctioneer</h2>
                <button onClick={() => navigate('/admin')} className="text-xs text-text-secondary hover:text-white flex items-center">
                    <ArrowLeft className="w-3 h-3 mr-1"/> Dashboard
                </button>
              </div>

              {/* Quick Actions & Theme Selectors */}
              <div className="flex flex-wrap gap-2 items-center bg-primary/50 rounded-lg p-2 w-full">
                  <div className="flex items-center gap-1">
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('transparent'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-highlight transition-colors"
                        title="Copy OBS Transparent Link"
                    >
                        <Cast className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('green'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-green-400 transition-colors"
                        title="Copy Projector View Link"
                    >
                        <Monitor className="w-4 h-4" />
                    </button>

                    {/* Bidding Dropdown */}
                    <div className="relative ml-1">
                        <select
                            value={biddingStatus === 'ON' ? 'ON' : 'OFF'}
                            onChange={(e) => {
                                const newVal = e.target.value === 'ON';
                                updateBiddingStatus(newVal ? 'ON' : 'PAUSED');
                            }}
                            className={`appearance-none pl-6 pr-6 py-1 rounded text-xs font-bold border outline-none cursor-pointer ${biddingStatus === 'ON' ? 'bg-green-900/30 text-green-400 border-green-500/50' : 'bg-red-900/30 text-red-400 border-red-500/50'}`}
                        >
                            <option value="ON">BIDDING ON</option>
                            <option value="OFF">BIDDING PAUSED</option>
                        </select>
                        <div className="absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none">
                            {biddingStatus === 'ON' ? <Unlock className="w-3 h-3 text-green-400"/> : <Lock className="w-3 h-3 text-red-400"/>}
                        </div>
                    </div>
                  </div>
              </div>

              {/* Display & Sponsors Toolbar */}
              <div className="flex flex-wrap gap-2 items-center bg-primary/50 rounded-lg p-2 w-full mt-1 border-t border-gray-700">
                  <div className="flex items-center gap-2 flex-grow">
                      <div className="w-24">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">Projector</label>
                          <select 
                            value={state.projectorLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('PROJECTOR', e.target.value)}
                            className="w-full bg-gray-800 text-white text-[10px] p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="IPL">Gold/Blue</option>
                              <option value="MODERN">Modern</option>
                          </select>
                      </div>
                      <div className="w-24">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">OBS</label>
                          <select 
                            value={state.obsLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('OBS', e.target.value)}
                            className="w-full bg-gray-800 text-white text-[10px] p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="MINIMAL">Minimal</option>
                              <option value="VERTICAL">Vertical</option>
                          </select>
                      </div>
                  </div>

                  <div className="w-px h-8 bg-gray-600 mx-1"></div>

                  <div className="flex flex-col gap-1 items-end">
                      <span className="text-[9px] text-gray-400 font-bold uppercase">Sponsors</span>
                      <div className="flex items-center gap-1">
                          <button 
                              onClick={() => updateSponsorVisibility('PROJECTOR')}
                              className={`p-1 rounded flex items-center gap-1 text-[9px] font-bold border transition-colors ${state.sponsorConfig?.showOnProjector ? 'bg-blue-600 border-blue-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
                              title="Toggle on Projector"
                          >
                              <Monitor className="w-3 h-3"/> Proj
                          </button>
                          <button 
                              onClick={() => updateSponsorVisibility('OBS')}
                              className={`p-1 rounded flex items-center gap-1 text-[9px] font-bold border transition-colors ${state.sponsorConfig?.showOnOBS ? 'bg-purple-600 border-purple-400 text-white' : 'bg-gray-800 border-gray-600 text-gray-400'}`}
                              title="Toggle on OBS"
                          >
                              <Cast className="w-3 h-3"/> OBS
                          </button>
                          <div className="relative group w-10">
                              <input 
                                  type="number" 
                                  className="w-full bg-gray-800 text-white text-[9px] p-1 rounded border border-gray-600 text-center outline-none" 
                                  value={sponsorLoop}
                                  onChange={handleSponsorLoopChange}
                                  onBlur={saveSponsorLoop}
                                  title="Loop Interval (Sec)"
                              />
                              <Clock className="w-2 h-2 absolute top-0.5 right-0.5 text-gray-500 pointer-events-none"/>
                          </div>
                      </div>
                  </div>
              </div>
          </div>
      </div>

      {/* SELECTION MODE TOGGLE */}
      <div className="bg-primary/40 rounded-lg p-2 mb-4 flex justify-between items-center border border-gray-700">
          <span className="text-xs font-bold text-text-secondary uppercase ml-1">Selection Mode</span>
          <div className="flex bg-gray-800 rounded p-1">
              <button 
                onClick={playerSelectionMode !== 'MANUAL' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'MANUAL' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Manual
              </button>
              <button 
                onClick={playerSelectionMode !== 'AUTO' ? toggleSelectionMode : undefined}
                className={`px-3 py-1 rounded text-xs font-bold transition-all ${playerSelectionMode === 'AUTO' ? 'bg-highlight text-primary shadow' : 'text-gray-400 hover:text-white'}`}
              >
                  Auto
              </button>
          </div>
      </div>

      <div className="mb-6 space-y-3">
         {getControlButtons()}

         {renderQuickBidButtons()}

         {!isSellingMode && (
             <div className="grid grid-cols-2 gap-2 mt-4 pt-4 border-t border-accent/30">
                 <button 
                    onClick={handleResetPlayer} 
                    disabled={isProcessing || !state.currentPlayerId}
                    className="flex flex-col items-center justify-center bg-yellow-600 hover:bg-yellow-700 text-xs text-white py-2 rounded transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
                    title="Clears bids for current player only"
                 >
                    <RotateCcw className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Current
                 </button>
                 <button 
                    onClick={handleResetFull} 
                    disabled={isProcessing}
                    className="flex flex-col items-center justify-center bg-red-900/80 hover:bg-red-900 text-xs text-red-200 border border-red-800 py-2 rounded transition-colors disabled:opacity-50"
                    title="Resets auction status to Not Started"
                 >
                    <AlertOctagon className={`mb-1 h-4 w-4 ${isProcessing ? 'animate-spin' : ''}`}/>
                    Reset Full
                 </button>
             </div>
         )}
      </div>

      <h3 className="text-sm font-bold mb-3 text-text-secondary uppercase">Teams Overview</h3>
      <div className="flex-grow overflow-y-auto space-y-3 pr-1 custom-scrollbar">
        {teams.map((team: Team) => (
          <TeamStatusCard key={team.id} team={team} />
        ))}
      </div>
    </div>
  );
};

export default LiveAdminPanel;

import React, { useState, useEffect, useMemo } from 'react';
import { useAuction } from '../hooks/useAuction';
import { AuctionStatus, Team, Player, ProjectorLayout, OBSLayout } from '../types';
import TeamStatusCard from '../components/TeamStatusCard';
import { Play, Check, X, ArrowLeft, Loader2, RotateCcw, AlertOctagon, DollarSign, Cast, Lock, Unlock, Monitor, ChevronDown, Shuffle, Search, User, Palette, Trophy, Gavel, Wallet, Eye, EyeOff, Clock, Zap, Undo2, RefreshCw } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const LiveAdminPanel: React.FC = () => {
  const { state, sellPlayer, passPlayer, startAuction, undoPlayerSelection, endAuction, resetAuction, resetCurrentPlayer, resetUnsoldPlayers, updateBiddingStatus, toggleSelectionMode, updateTheme, activeAuctionId, placeBid, nextBid, updateSponsorConfig, correctPlayerSale } = useAuction();
  const { teams, players, biddingStatus, playerSelectionMode, categories, maxPlayersPerTeam } = state;
  const navigate = useNavigate();
  const [isProcessing, setIsProcessing] = useState(false);

  // Inline Sell State
  const [isSellingMode, setIsSellingMode] = useState(false);
  const [selectedTeamId, setSelectedTeamId] = useState<string>('');
  const [finalPrice, setFinalPrice] = useState<number>(0);

  // Manual Player Selection State
  const [manualPlayerId, setManualPlayerId] = useState<string>('');
  const [searchTerm, setSearchTerm] = useState(''); // New search state
  const [showUnsold, setShowUnsold] = useState(false); // Toggle to include unsold players

  // Undo State
  const [lastAction, setLastAction] = useState<{playerId: string, type: 'SOLD' | 'UNSOLD', name: string} | null>(null);

  // Sponsor Config Local State (debounce or immediate)
  const [sponsorLoop, setSponsorLoop] = useState(state.sponsorConfig?.loopInterval || 5);

  // Auto-fill price and leader when entering sell mode or when bid updates
  useEffect(() => {
      // 1. Determine Price
      if (state.currentBid !== null && state.currentBid > 0) {
          setFinalPrice(Number(state.currentBid));
      } else if (state.currentPlayerId) {
          // Fallback to Base Price if no bids
          const p = players.find(player => String(player.id) === String(state.currentPlayerId));
          if (p) setFinalPrice(p.basePrice);
      }

      // 2. Determine Team
      if (state.highestBidder) {
          setSelectedTeamId(String(state.highestBidder.id));
      } else if (!isSellingMode) {
          // Reset selection only if we aren't currently editing
          setSelectedTeamId('');
      }
  }, [state.currentBid, state.highestBidder, isSellingMode, state.currentPlayerId, players]);

  // Sync sponsor loop state
  useEffect(() => {
      if(state.sponsorConfig?.loopInterval) setSponsorLoop(state.sponsorConfig.loopInterval);
  }, [state.sponsorConfig]);

  const handleStart = async (specificId?: string) => {
      if (teams.length === 0) {
          alert("Cannot start auction: No teams added. Please go back to Dashboard > Edit Auction > Teams to add teams.");
          return;
      }

      const availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
      if (availablePlayers.length === 0 && !showUnsold) {
          alert("Cannot start auction: No more players available.");
          return;
      }

      setIsProcessing(true);
      // If restarting an unsold player, specificId will be passed.
      const hasNextPlayer = await startAuction(specificId);

      if (!hasNextPlayer && !showUnsold) {
          if (window.confirm("No more players available in the pool.\n\nDo you want to MARK AUCTION AS COMPLETED?")) {
              await endAuction();
          }
      } else {
          // Clear manual selection
          setManualPlayerId('');
          setSearchTerm('');
      }
      setIsProcessing(false);
  }

  const handleResetFull = async () => {
      if(!window.confirm("WARNING: This will reset the auction status to 'Not Started'. It will NOT remove sold players from teams. Proceed?")) return;
      setIsProcessing(true);
      await resetAuction();
      setIsProcessing(false);
  }

  const handleResetPlayer = async () => {
      if(!window.confirm("This will clear the current bid and timer for this player. Proceed?")) return;
      setIsProcessing(true);
      await resetCurrentPlayer();
      setIsProcessing(false);
  }

  const handleCancelSelection = async () => {
      if(!window.confirm("Change Player? This will cancel the current round and allow you to select a different player.")) return;
      setIsProcessing(true);
      await undoPlayerSelection();
      setIsProcessing(false);
  }

  const handleUndoLastAction = async () => {
      if (!lastAction) return;
      if (!window.confirm(`Undo ${lastAction.type} status for ${lastAction.name}? This will return them to the pool.`)) return;

      setIsProcessing(true);
      try {
          await correctPlayerSale(lastAction.playerId, null, 0); // null team, 0 price = reset to pool
          setLastAction(null);
      } catch (e) {
          console.error(e);
          alert("Failed to undo action.");
      } finally {
          setIsProcessing(false);
      }
  }

  const handleResetSingleUnsold = async (playerId: string, e: React.MouseEvent) => {
      e.stopPropagation();
      if (!window.confirm("Bring this player back to pool (remove UNSOLD status)?")) return;

      setIsProcessing(true);
      try {
          await correctPlayerSale(playerId, null, 0);
          // If this player was selected in manual dropdown, they will now appear as normal available player
      } catch (e) {
          alert("Failed to reset player.");
      } finally {
          setIsProcessing(false);
      }
  }

  const copyOBSLink = (type: 'transparent' | 'green') => {
      if (!activeAuctionId) return;
      const baseUrl = window.location.href.split('#')[0];
      const route = type === 'green' ? 'obs-green' : 'obs-overlay';
      const url = `${baseUrl}#/${route}/${activeAuctionId}`;
      navigator.clipboard.writeText(url);

      if (type === 'green') {
          alert("PROJECTOR VIEW URL Copied!\n\nOpen this link on the projector screen.");
      } else {
          alert("OBS OVERLAY URL Copied!\n\nPaste this into OBS Browser Source.");
      }
  };

  const handleSellClick = () => {
      setIsSellingMode(true);
  };

  const cancelSell = () => {
      setIsSellingMode(false);
  };

  const confirmSell = async () => {
      if (!selectedTeamId) {
          alert("Please select a team to sell to.");
          return;
      }
      if (finalPrice <= 0) {
          alert("Price must be greater than 0.");
          return;
      }

      setIsProcessing(true);
      const pid = state.currentPlayerId ? String(state.currentPlayerId) : '';
      const pName = players.find(p => String(p.id) === pid)?.name || 'Player';

      try {
          await sellPlayer(selectedTeamId, finalPrice);
          setLastAction({ playerId: pid, type: 'SOLD', name: pName });
          setIsSellingMode(false);
      } catch(e) {
          console.error(e);
          alert("Failed to sell player. Check console.");
      } finally {
          setIsProcessing(false);
      }
  };

  const handlePass = async () => {
      if (window.confirm("Confirm UNSOLD?")) {
          setIsProcessing(true);
          const pid = state.currentPlayerId ? String(state.currentPlayerId) : '';
          const pName = players.find(p => String(p.id) === pid)?.name || 'Player';

          await passPlayer();
          setLastAction({ playerId: pid, type: 'UNSOLD', name: pName });
          setIsProcessing(false);
      }
  }

  const handleQuickBid = async (teamId: string | number) => {
      try {
          await placeBid(teamId, nextBid);
      } catch (e) {
          console.error(e);
          // Optional: Show toast error
      }
  };

  const updateSponsorVisibility = (target: 'OBS' | 'PROJECTOR') => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      const newConfig = {
          ...current,
          showOnOBS: target === 'OBS' ? !current.showOnOBS : current.showOnOBS,
          showOnProjector: target === 'PROJECTOR' ? !current.showOnProjector : current.showOnProjector
      };
      updateSponsorConfig(newConfig);
  };

  const handleSponsorLoopChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = Number(e.target.value);
      setSponsorLoop(val);
  };

  const saveSponsorLoop = () => {
      const current = state.sponsorConfig || { showOnOBS: false, showOnProjector: false, loopInterval: 5 };
      updateSponsorConfig({ ...current, loopInterval: sponsorLoop });
  };

  const selectedPlayerObj = players.find(p => p.id === manualPlayerId);
  const currentPlayer = state.currentPlayerId ? state.players.find(p => String(p.id) === String(state.currentPlayerId)) : null;

  const getControlButtons = () => {
      const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
      const availablePlayersCount = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD').length;
      const isStartDisabled = isProcessing || (state.status === AuctionStatus.NotStarted && (teams.length === 0 || availablePlayersCount === 0));
      const unsoldCount = players.filter(p => p.status === 'UNSOLD').length;

      // NEW: Finish Auction Option
      // Show this if no players are left AND we are not currently bidding on one (isRoundActive is false)
      if (availablePlayersCount === 0 && state.status !== AuctionStatus.NotStarted && !isRoundActive) {
          return (
             <div className="space-y-4 animate-fade-in">
                 {unsoldCount > 0 && (
                     <div className="bg-blue-900/30 border border-blue-500/50 p-4 rounded-xl text-center shadow-inner">
                        <h3 className="text-white font-bold text-lg mb-2">Unsold Players Available</h3>
                        <p className="text-gray-300 text-xs mb-4">There are {unsoldCount} unsold players. Do you want to bring them back into the bidding pool?</p>
                        <button 
                            onClick={async () => {
                                if(window.confirm(`Bring back ${unsoldCount} unsold players to the pool?`)) {
                                    setIsProcessing(true);
                                    await resetUnsoldPlayers();
                                    setIsProcessing(false);
                                }
                            }}
                            disabled={isProcessing}
                            className="w-full bg-blue-600 hover:bg-blue-500 text-white font-bold py-3 rounded-lg shadow-lg transition-all active:scale-95 flex items-center justify-center"
                        >
                            {isProcessing ? <Loader2 className="mr-2 h-4 w-4 animate-spin"/> : <RotateCcw className="mr-2 h-4 w-4"/>}
                            BRING BACK UNSOLD ({unsoldCount})
                        </button>
                     </div>
                 )}

                 <div className="bg-green-900/30 border border-green-500/50 p-6 rounded-xl text-center shadow-inner">
                    <Trophy className="w-12 h-12 text-yellow-400 mx-auto mb-3 drop-shadow-lg" />
                    <h3 className="text-white font-bold text-xl mb-2">Auction Completed!</h3>
                    <p className="text-gray-300 text-sm mb-6">All players have been auctioned. You can now finalize the event.</p>
                    <button 
                        onClick={async () => {
                            if(window.confirm("Are you sure you want to finish the auction? This will enable the summary view for all users.")) {
                                setIsProcessing(true);
                                await endAuction();
                                setIsProcessing(false);
                            }
                        }}
                        disabled={isProcessing}
                        className="w-full bg-green-600 hover:bg-green-500 text-white font-bold py-4 rounded-lg shadow-lg shadow-green-900/20 transition-all active:scale-95 flex items-center justify-center tracking-wide"
                    >
                        {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : "GENERATE SUMMARY & FINISH"}
                    </button>
                </div>
            </div>
          );
      }

      // 1. ACTIVE ROUND CONTROLS (SOLD / UNSOLD)
      if (isRoundActive) {
          if (isSellingMode) {
              return (
                  <div className="bg-primary/20 p-3 rounded-lg border border-gray-600 animate-fade-in space-y-3">
                      <div className="flex items-center gap-2 mb-2 text-white font-bold border-b border-gray-600 pb-1">
                          <Check className="w-4 h-4 text-green-500" /> Confirm Sale
                      </div>

                      {/* Inline Form */}
                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Sold To Team</label>
                          <div className="relative">
                            <select 
                                value={selectedTeamId} 
                                onChange={(e) => setSelectedTeamId(e.target.value)}
                                className="w-full bg-primary border border-gray-600 rounded p-2 text-sm text-white outline-none focus:border-green-500 appearance-none"
                            >
                                <option value="">-- Select Team --</option>
                                {teams.map(t => (
                                    <option key={t.id} value={t.id}>{t.name} ({t.budget})</option>
                                ))}
                            </select>
                            <ChevronDown className="absolute right-2 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400 pointer-events-none" />
                          </div>
                      </div>

                      <div>
                          <label className="block text-[10px] text-text-secondary uppercase font-bold mb-1">Final Price</label>
                          <div className="relative">
                              <DollarSign className="absolute left-2 top-1/2 -translate-y-1/2 w-4 h-4 text-green-500" />
                              <input 
                                type="number" 
                                value={finalPrice} 
                                onChange={(e) => setFinalPrice(Number(e.target.value))}
                                className="w-full bg-primary border border-gray-600 rounded p-2 pl-8 text-sm text-white font-bold outline-none focus:border-green-500"
                              />
                          </div>
                      </div>

                      <div className="flex gap-2 pt-1">
                          <button 
                            onClick={cancelSell}
                            className="flex-1 bg-gray-600 hover:bg-gray-700 text-white py-2 rounded text-sm font-bold transition-colors"
                          >
                              Cancel
                          </button>
                          <button 
                            onClick={confirmSell}
                            disabled={isProcessing}
                            className="flex-1 bg-green-600 hover:bg-green-700 text-white py-2 rounded text-sm font-bold shadow-lg flex items-center justify-center transition-colors"
                          >
                              {isProcessing ? <Loader2 className="w-4 h-4 animate-spin"/> : 'Confirm'}
                          </button>
                      </div>
                  </div>
              );
          }

          return (
              <div className="space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                      <button 
                        onClick={handleSellClick}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-green-600 hover:bg-green-700 disabled:bg-gray-700 disabled:text-gray-500 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <Check className="mb-1 h-6 w-6"/>}
                          {isProcessing ? 'SELLING...' : 'SOLD'}
                      </button>
                      <button 
                        onClick={handlePass}
                        disabled={isProcessing}
                        className="flex flex-col items-center justify-center bg-red-600 hover:bg-red-700 disabled:bg-gray-700 disabled:cursor-not-allowed text-white font-bold py-4 px-2 rounded-lg transition-all shadow-md active:scale-95"
                      >
                          {isProcessing ? <Loader2 className="mb-1 h-6 w-6 animate-spin"/> : <X className="mb-1 h-6 w-6"/>}
                          UNSOLD
                      </button>
                  </div>
                  {/* Cancel / Change Player Button */}
                  <button 
                    onClick={handleCancelSelection} 
                    disabled={isProcessing}
                    className="w-full flex items-center justify-center bg-orange-600 hover:bg-orange-700 text-white font-bold py-2 rounded-lg text-xs transition-colors shadow-sm active:scale-95"
                  >
                      <Undo2 className="w-4 h-4 mr-1" /> Change Player / Cancel Round
                  </button>
              </div>
          );
      }

      // 2. NEXT PLAYER SELECTION (Based on Mode)
      if (playerSelectionMode === 'MANUAL') {
           // Filter based on search term and unsold toggle
           let availablePlayers = players.filter(p => p.status !== 'SOLD' && p.status !== 'UNSOLD');
           if (showUnsold) {
               const unsoldList = players.filter(p => p.status === 'UNSOLD');
               availablePlayers = [...availablePlayers, ...unsoldList];
           }

           availablePlayers.sort((a, b) => a.name.localeCompare(b.name));

           const filteredPlayers = availablePlayers.filter(p => 
               p.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
               p.category.toLowerCase().includes(searchTerm.toLowerCase())
           );

           return (
               <div className="space-y-3 bg-primary/20 p-3 rounded-lg border border-gray-600">
                   <div>
                       <div className="flex justify-between items-center mb-1">
                           <label className="block text-[10px] text-text-secondary uppercase font-bold">Select Next Player</label>
                           <label className="flex items-center text-[10px] text-yellow-400 cursor-pointer">
                               <input type="checkbox" checked={showUnsold} onChange={(e) => setShowUnsold(e.target.checked)} className="mr-1 accent-yellow-500" />
                               Include Unsold
                           </label>
                       </div>

                       {/* Search Input */}
                       <div className="relative mb-2">
                           <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-gray-400" />
                           <input 
                                type="text"
                                className="w-full bg-gray-900 border border-gray-700 rounded p-1.5 pl-7 text-xs text-white focus:border-highlight outline-none"
                                placeholder="Search player name..."
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                           />
                       </div>

                       <div className="relative flex gap-1">
                           <div className="relative flex-grow">
                               <select 
                                   className="w-full bg-gray-900 text-white text-xs p-3 rounded border border-gray-700 focus:border-highlight outline-none appearance-none cursor-pointer pr-8"
                                   value={manualPlayerId}
                                   onChange={(e) => setManualPlayerId(e.target.value)}
                               >
                                   <option value="">-- Choose Player ({filteredPlayers.length}) --</option>
                                   {filteredPlayers.map(p => (
                                       <option key={p.id} value={p.id} className={p.status === 'UNSOLD' ? 'text-red-400 font-bold' : ''}>
                                           {p.name} ({p.category}) {p.status === 'UNSOLD' ? '[UNSOLD]' : ''} - Base: {p.basePrice}
                                       </option>
                                   ))}
                               </select>
                               <ChevronDown className="absolute right-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-500 pointer-events-none" />
                           </div>

                           {/* Reset Unsold Icon Button */}
                           {manualPlayerId && players.find(p => p.id === manualPlayerId)?.status === 'UNSOLD' && (
                               <button 
                                   onClick={(e) => handleResetSingleUnsold(manualPlayerId, e)}
                                   className="bg-yellow-600 hover:bg-yellow-700 text-white p-2 rounded border border-yellow-800 transition-colors"
                                   title="Reset this player to pool (Remove UNSOLD status)"
                               >
                                   <RefreshCw className={`w-5 h-5 ${isProcessing ? 'animate-spin' : ''}`} />
                               </button>
                           )}
                       </div>
                   </div>

                   <button 
                     onClick={() => handleStart(manualPlayerId)} 
                     disabled={isStartDisabled || !manualPlayerId}
                     className={`w-full flex items-center justify-center font-bold py-3 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                         ${isStartDisabled || !manualPlayerId
                             ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                             : 'bg-highlight hover:bg-teal-500 text-primary'}`
                     }
                   >
                       {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Play className="mr-2 h-5 w-5"/>} 
                       {manualPlayerId && players.find(p => p.id === manualPlayerId)?.status === 'UNSOLD' ? 'Re-Auction Player' : 'Start Bidding'}
                   </button>
               </div>
           );
      }

      // AUTO MODE
      return (
          <button 
            onClick={() => handleStart()} 
            disabled={isStartDisabled}
            className={`w-full flex items-center justify-center font-bold py-4 px-4 rounded-lg transition-colors duration-300 shadow-lg shadow-highlight/20 active:scale-95
                ${isStartDisabled 
                    ? 'bg-gray-600 text-gray-400 cursor-not-allowed' 
                    : 'bg-highlight hover:bg-teal-500 text-primary'}`
            }
          >
              {isProcessing ? <Loader2 className="mr-2 h-5 w-5 animate-spin"/> : <Shuffle className="mr-2 h-5 w-5"/>} 
              {state.status === AuctionStatus.NotStarted ? 'Start Auction (Auto Random)' : 'Next Random Player'}
          </button>
      );
  }

  // --- RENDER QUICK BID BUTTONS ---
  const isRoundActive = state.status === AuctionStatus.InProgress && state.currentPlayerId;
  const renderQuickBidButtons = () => {
        if (!isRoundActive || isSellingMode) return null;

        return (
            <div className="mb-4">
                <h3 className="text-xs font-bold text-text-secondary uppercase mb-2 flex items-center">
                    <Zap className="w-3 h-3 mr-1 text-yellow-400" /> Quick Bids (Next: {nextBid})
                </h3>
                <div className="grid grid-cols-2 gap-2">
                    {teams.map(team => {
                        // Logic Check
                        let allowed = true;
                        let reason = '';

                        // 1. Budget
                        if (team.budget < nextBid) { allowed = false; reason = 'NO FUNDS'; }
                        // 2. Highest
                        else if (state.highestBidder?.id === team.id) { allowed = false; reason = 'LEADING'; }
                        // 3. Squad Full
                        else if (team.players.length >= (maxPlayersPerTeam || 25)) { allowed = false; reason = 'FULL'; }

                        // 4. Bid Limit & Category
                        else if (currentPlayer) {
                            if (currentPlayer.category) {
                                const catConfig = categories.find(c => c.name === currentPlayer.category);
                                if (catConfig && catConfig.maxPerTeam > 0) {
                                    const count = team.players.filter(p => p.category === currentPlayer.category).length;
                                    if (count >= catConfig.maxPerTeam) { allowed = false; reason = 'CAT LIMIT'; }
                                }
                            }
                            if (allowed) {
                                let reservedBudget = 0;
                                categories.forEach(cat => {
                                    if (cat.maxPerTeam > 0) {
                                        const playersInCat = team.players.filter(p => p.category === cat.name).length;
                                        let slotsToFill = Math.max(0, cat.maxPerTeam - playersInCat);
                                        if (currentPlayer.category === cat.name) {
                                            slotsToFill = Math.max(0, slotsToFill - 1);
                                        }
                                        reservedBudget += slotsToFill * cat.basePrice;
                                    }
                                });
                                const maxAllowedBid = team.budget - reservedBudget;
                                if (nextBid > maxAllowedBid) { allowed = false; reason = 'MAX BID'; }
                            }
                        }

                        return (
                            <button
                                key={team.id}
                                onClick={() => handleQuickBid(team.id)}
                                disabled={!allowed || isProcessing}
                                className={`
                                    flex items-center justify-between px-2 py-2 rounded border text-left transition-all relative group
                                    ${allowed 
                                        ? 'bg-white border-gray-300 hover:border-green-500 hover:shadow-md active:scale-95' 
                                        : 'bg-gray-200 border-transparent opacity-60 cursor-not-allowed'}
                                `}
                            >
                                <div className="flex items-center gap-2 min-w-0 flex-1">
                                    {team.logoUrl ? (
                                        <img src={team.logoUrl} className="w-6 h-6 rounded-full object-contain bg-gray-100 flex-shrink-0" />
                                    ) : (
                                        <div className="w-6 h-6 rounded-full bg-gray-300 flex items-center justify-center text-[10px] font-bold text-gray-600 flex-shrink-0">
                                            {team.name.charAt(0)}
                                        </div>
                                    )}
                                    <div className="flex flex-col min-w-0">
                                        <span className="text-xs font-bold text-gray-800 truncate leading-none">{team.name}</span>
                                        <span className="text-[9px] text-gray-500 font-mono leading-none mt-0.5">{team.budget}</span>
                                    </div>
                                </div>

                                <div className="flex-shrink-0 ml-1">
                                    {!allowed ? (
                                        <span className="text-[8px] font-black text-red-500 uppercase bg-red-100 px-1 rounded">{reason}</span>
                                    ) : (
                                        <span className="text-[10px] font-bold text-green-600 bg-green-50 px-1.5 py-0.5 rounded group-hover:bg-green-600 group-hover:text-white transition-colors">
                                            +{nextBid}
                                        </span>
                                    )}
                                </div>
                            </button>
                        );
                    })}
                </div>
            </div>
        );
  };

  return (
    <div className="bg-secondary p-4 rounded-lg shadow-lg h-full flex flex-col border border-gray-700 relative">

      <div className="flex justify-between items-center mb-4 border-b border-accent pb-2">
          <div className="flex flex-col gap-2 w-full">
              <div className="flex justify-between items-center w-full">
                <h2 className="text-xl font-bold text-highlight uppercase tracking-wider">Auctioneer</h2>
                <button onClick={() => navigate('/admin')} className="text-xs text-text-secondary hover:text-white flex items-center">
                    <ArrowLeft className="w-3 h-3 mr-1"/> Dashboard
                </button>
              </div>

              {/* Quick Actions & Theme Selectors */}
              <div className="flex flex-wrap gap-2 items-center bg-primary/50 rounded-lg p-2 w-full">
                  <div className="flex items-center gap-1">
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('transparent'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-highlight transition-colors"
                        title="Copy OBS Transparent Link"
                    >
                        <Cast className="w-4 h-4" />
                    </button>
                    <button 
                        onClick={(e) => { e.stopPropagation(); copyOBSLink('green'); }}
                        className="p-1.5 rounded hover:bg-white/10 text-green-400 transition-colors"
                        title="Copy Projector View Link"
                    >
                        <Monitor className="w-4 h-4" />
                    </button>

                    {/* Bidding Dropdown */}
                    <div className="relative ml-1">
                        <select
                            value={biddingStatus === 'ON' ? 'ON' : 'OFF'}
                            onChange={(e) => {
                                const newVal = e.target.value === 'ON';
                                updateBiddingStatus(newVal ? 'ON' : 'PAUSED');
                            }}
                            className={`appearance-none pl-6 pr-6 py-1 rounded text-xs font-bold border outline-none cursor-pointer ${biddingStatus === 'ON' ? 'bg-green-900/30 text-green-400 border-green-500/50' : 'bg-red-900/30 text-red-400 border-red-500/50'}`}
                        >
                            <option value="ON">BIDDING ON</option>
                            <option value="OFF">BIDDING PAUSED</option>
                        </select>
                        <div className="absolute left-1.5 top-1/2 -translate-y-1/2 pointer-events-none">
                            {biddingStatus === 'ON' ? <Unlock className="w-3 h-3 text-green-400"/> : <Lock className="w-3 h-3 text-red-400"/>}
                        </div>
                    </div>
                  </div>
              </div>

              {/* Display & Sponsors Toolbar */}
              <div className="flex flex-wrap gap-2 items-center bg-primary/50 rounded-lg p-2 w-full mt-1 border-t border-gray-700">
                  <div className="flex items-center gap-2 flex-grow">
                      <div className="w-24">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">Projector</label>
                          <select 
                            value={state.projectorLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('PROJECTOR', e.target.value)}
                            className="w-full bg-gray-800 text-white text-[10px] p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="IPL">Gold/Blue</option>
                              <option value="MODERN">Modern</option>
                          </select>
                      </div>
                      <div className="w-24">
                          <label className="block text-[8px] text-gray-400 uppercase font-bold mb-0.5">OBS</label>
                          <select 
                            value={state.obsLayout || 'STANDARD'} 
                            onChange={(e) => updateTheme('OBS', e.target.value)}
                            className="w-full bg-gray-800 text-white text-[10px] p-1 rounded border border-gray-600 outline-none hover:border-highlight cursor-pointer"
                          >
                              <option value="STANDARD">Standard</option>
                              <option value="MINIMAL">Minimal</option>
                              <option value="VERTICAL">Vertical</option>
                          </select>
                      </div>
                  </div>

                  <div className="w-px h-8 bg-gray-600 mx-1"></div>

                  <div className="flex flex-col gap-1 items-end">
                      <span className="text-[9px] text-gray-400 font-bold uppercase">Sponsors</span>
