                                                    {match.status}
                                                </span>
                                                <span className="text-[10px] text-gray-400 font-bold bg-gray-50 px-2 py-1 rounded">
                                                    {match.sourceType === 'TOURNAMENT' ? '🏆 TOUR' : '🔨 AUCTION'}
                                                </span>
