                                            <div className="flex items-center justify-between">
                                                <div className="w-[45%]">
                                                    <div className="font-bold text-gray-800 truncate text-sm" title={match.teamAName}>{match.teamAName}</div>
                                                </div>
                                                <div className="text-gray-300 font-bold text-xs">VS</div>
                                                <div className="w-[45%] text-right">
                                                    <div className="font-bold text-gray-800 truncate text-sm" title={match.teamBName}>{match.teamBName}</div>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="bg-gray-50 p-3 flex justify-between gap-2 opacity-90 group-hover:opacity-100 transition-opacity">
                                            <button 
                                                onClick={() => navigate(`/scoring/${match.id}`)}
                                                className="flex-1 bg-white hover:bg-blue-50 text-blue-600 border border-blue-200 text-xs font-bold py-2 rounded flex items-center justify-center gap-2 transition-colors"
                                            >
                                                <Play className="w-3 h-3"/> Scorer
                                            </button>
                                            <button 
                                                onClick={() => window.open(`/#/match-overlay/${match.id}`, '_blank')}
                                                className="bg-white hover:bg-gray-100 text-gray-600 border border-gray-200 p-2 rounded"
                                                title="OBS Overlay"
                                            >
                                                <Monitor className="w-4 h-4"/>
                                            </button>
                                            <button 
                                                onClick={(e) => deleteMatch(match.id, e)}
                                                className="bg-white hover:bg-red-50 text-red-400 border border-gray-200 hover:border-red-200 p-2 rounded transition-colors"
                                                title="Delete Match"
                                            >
                                                <Trash2 className="w-4 h-4"/>
                                            </button>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </>
                )}
            </main>
        </div>
    );
};

export default ScoringDashboard;

import React, { useEffect, useState, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { db } from '../firebase';
import { Match, Player, Team, InningsState, BallEvent, BatsmanStats, BowlerStats, ScoringAsset } from '../types';
import { ArrowLeft, Trophy, Users, RotateCcw, Save, Loader2, Undo2, Circle, Settings, UserPlus, Info, CheckSquare, Square, Palette, ChevronDown, RefreshCw, Trash2, Image as ImageIcon, Check } from 'lucide-react';
import { useAuction } from '../hooks/useAuction';

const MatchScorer: React.FC = () => {
    const { matchId } = useParams<{ matchId: string }>();
    const navigate = useNavigate();
    const { userProfile } = useAuction();
    const [match, setMatch] = useState<Match | null>(null);
    const [teamA, setTeamA] = useState<Team | null>(null);
    const [teamB, setTeamB] = useState<Team | null>(null);
    const [assets, setAssets] = useState<ScoringAsset[]>([]);
    const [loading, setLoading] = useState(true);

    // UI States
    const [showTossModal, setShowTossModal] = useState(false);
    const [tossWinner, setTossWinner] = useState('');
    const [tossChoice, setTossChoice] = useState<'BAT' | 'BOWL'>('BAT');
    const [processing, setProcessing] = useState(false);

    // Controller Inputs
    const [isWide, setIsWide] = useState(false);
    const [isNoBall, setIsNoBall] = useState(false);
    const [isBye, setIsBye] = useState(false);
    const [isLegBye, setIsLegBye] = useState(false);
    const [isWicket, setIsWicket] = useState(false);

    // Team Editing Inputs
    const [newPlayerNameA, setNewPlayerNameA] = useState('');
    const [newPlayerNameB, setNewPlayerNameB] = useState('');

    // Overlay Inputs
    const [customInput, setCustomInput] = useState('');
    const [selectedMOM, setSelectedMOM] = useState('');

    // Initial Data Fetch
    useEffect(() => {
        if (!matchId) return;
        const unsub = db.collection('matches').doc(matchId).onSnapshot(doc => {
            if (doc.exists) {
                const m = { id: doc.id, ...doc.data() } as Match;
                setMatch(m);
                if (m.status === 'SCHEDULED' || m.status === 'TOSS') {
                    setShowTossModal(true);
                } else {
                    setShowTossModal(false);
                }
                if (m.overlay?.momId) setSelectedMOM(m.overlay.momId);
                if (m.overlay?.customMessage) setCustomInput(m.overlay.customMessage);
            } else {
                navigate('/scoring');
            }
            setLoading(false);
        });
        return () => unsub();
    }, [matchId]);

    // Fetch Assets for Library
    useEffect(() => {
        if (!userProfile?.uid) return;
        const unsub = db.collection('scoringAssets')
            .where('createdBy', '==', userProfile.uid)
            .onSnapshot(snap => {
                setAssets(snap.docs.map(d => ({ id: d.id, ...d.data() } as ScoringAsset)));
            });
        return () => unsub();
    }, [userProfile]);

    // Fetch Teams
    useEffect(() => {
        if (!match) return;
        const fetchTeams = async () => {
            const collectionName = match.sourceType === 'TOURNAMENT' ? 'tournaments' : 'auctions';
            const rootRef = db.collection(collectionName).doc(match.auctionId).collection('teams');
            const docA = await rootRef.doc(match.teamAId).get();
            const docB = await rootRef.doc(match.teamBId).get();
            if (docA.exists) setTeamA({ id: docA.id, ...docA.data() } as Team);
            if (docB.exists) setTeamB({ id: docB.id, ...docB.data() } as Team);
        };
        fetchTeams();
    }, [match?.auctionId, match?.teamAId, match?.teamBId]);

    const currentInnings = match ? match.innings[match.currentInnings] : null;
    const getTeam = (id: string | undefined | null) => {
        if (!id) return null;
        if (String(teamA?.id) === String(id)) return teamA;
        if (String(teamB?.id) === String(id)) return teamB;
        return null;
    };
    const battingTeam = currentInnings ? getTeam(currentInnings.battingTeamId) : null;
    const bowlingTeam = currentInnings ? getTeam(currentInnings.bowlingTeamId) : null;
    const needsStriker = currentInnings && !currentInnings.strikerId;
    const needsNonStriker = currentInnings && !currentInnings.nonStrikerId;
    const needsBowler = currentInnings && !currentInnings.currentBowlerId;

    const handleToss = async () => {
        if (!match || !tossWinner || !tossChoice) return;
        setProcessing(true);
        let battingId = tossWinner;
        let bowlingId = tossWinner === match.teamAId ? match.teamBId : match.teamAId;
        if (tossChoice === 'BOWL') { const temp = battingId; battingId = bowlingId; bowlingId = temp; }
        const newInnings: InningsState = {
            battingTeamId: battingId, bowlingTeamId: bowlingId, totalRuns: 0, wickets: 0, overs: 0, ballsInCurrentOver: 0, currentRunRate: 0, extras: { wides: 0, noBalls: 0, byes: 0, legByes: 0 }, strikerId: null, nonStrikerId: null, currentBowlerId: null, batsmen: {}, bowlers: {}, recentBalls: []
        };
        await db.collection('matches').doc(match.id).update({
            tossWinnerId: tossWinner, tossChoice: tossChoice, status: 'LIVE', [`innings.1`]: newInnings, overlay: { currentView: 'DEFAULT', animation: 'NONE', theme: 'DEFAULT' }
        });
        setShowTossModal(false);
        setProcessing(false);
    };

    const handleDeleteMatch = async () => {
        if(!match) return;
        if(window.confirm("Are you sure?")) {
            setProcessing(true);
            try { await db.collection('matches').doc(match.id).delete(); } catch (e) { setProcessing(false); }
        }
    };

    const handlePlayerSelect = async (type: 'STRIKER' | 'NON_STRIKER' | 'BOWLER', playerId: string) => {
        if (!match || !playerId) return;
        const targetTeam = type === 'BOWLER' ? bowlingTeam : battingTeam;
        if (!targetTeam) return;
        const playerObj = targetTeam.players.find(p => String(p.id) === String(playerId));
        if (!playerObj) return;
        const updateData: any = {};
        const prefix = `innings.${match.currentInnings}`;
        if (type === 'BOWLER') {
            if (!currentInnings?.bowlers || !currentInnings.bowlers[playerId]) {
                updateData[`${prefix}.bowlers.${playerId}`] = { playerId, name: playerObj.name, overs: 0, ballsBowled: 0, runsConceded: 0, wickets: 0, maidens: 0 };
            }
            updateData[`${prefix}.currentBowlerId`] = playerId;
        } else {
            if (!currentInnings?.batsmen || !currentInnings.batsmen[playerId]) {
                updateData[`${prefix}.batsmen.${playerId}`] = { playerId, name: playerObj.name, runs: 0, balls: 0, fours: 0, sixes: 0, isStriker: type === 'STRIKER' };
            } else { updateData[`${prefix}.batsmen.${playerId}.isStriker`] = type === 'STRIKER'; }
            if (type === 'STRIKER') updateData[`${prefix}.strikerId`] = playerId;
            else updateData[`${prefix}.nonStrikerId`] = playerId;
        }
        await db.collection('matches').doc(match.id).update(updateData);
    };

    const handleScore = async (runs: number) => {
        if (!match || !currentInnings || needsStriker || needsNonStriker || needsBowler) return;
        setProcessing(true);
        const state = JSON.parse(JSON.stringify(currentInnings)) as InningsState;
        const striker = state.batsmen[state.strikerId!];
        const bowler = state.bowlers[state.currentBowlerId!];
        let extraType: 'WIDE' | 'NOBALL' | 'BYE' | 'LEGBYE' | undefined = undefined;
        if (isWide) extraType = 'WIDE'; else if (isNoBall) extraType = 'NOBALL'; else if (isBye) extraType = 'BYE'; else if (isLegBye) extraType = 'LEGBYE';
        const isLegalBall = !isWide && !isNoBall;
        let bowlerRuns = runs; if (isWide || isNoBall) bowlerRuns += 1; if (isBye || isLegBye) bowlerRuns = 0; bowler.runsConceded += bowlerRuns;
        let totalBallRuns = runs; if (isWide || isNoBall) totalBallRuns += 1; state.totalRuns += totalBallRuns;
        if (isWide) state.extras.wides += (1 + runs); if (isNoBall) state.extras.noBalls += (1 + runs); if (isBye) state.extras.byes += runs; if (isLegBye) state.extras.legByes += runs;
        if (!isWide) { if (isLegalBall || isNoBall) { if (!isBye && !isLegBye) { striker.runs += runs; if (runs === 4) striker.fours++; if (runs === 6) striker.sixes++; } striker.balls++; } }
        if (isLegalBall) {
            state.ballsInCurrentOver++; bowler.ballsBowled++;
            const totalValidBalls = (Math.floor(state.overs) * 6) + Math.round((state.overs % 1) * 10) + 1;
            state.overs = Number(`${Math.floor(totalValidBalls / 6)}.${totalValidBalls % 6}`);
            const bValidBalls = (Math.floor(bowler.overs) * 6) + Math.round((bowler.overs % 1) * 10) + 1;
            bowler.overs = Number(`${Math.floor(bValidBalls / 6)}.${bValidBalls % 6}`);
        }
        if (isWicket) { state.wickets++; bowler.wickets++; striker.outBy = `b ${bowler.name}`; state.strikerId = null; }
        state.recentBalls.push({ ballNumber: state.ballsInCurrentOver, overNumber: Math.floor(state.overs), bowlerId: bowler.playerId, batsmanId: striker.playerId, runs, isWide, isNoBall, isWicket, isBye, isLegBye, extras: (extraType ? 1 : 0) });
        if (runs % 2 !== 0) { const temp = state.strikerId; state.strikerId = state.nonStrikerId; state.nonStrikerId = temp; }
        if (state.ballsInCurrentOver === 6) { state.ballsInCurrentOver = 0; state.currentBowlerId = null; const temp = state.strikerId; state.strikerId = state.nonStrikerId; state.nonStrikerId = temp; }
        await db.collection('matches').doc(match.id).update({ [`innings.${match.currentInnings}`]: state });
        setIsWide(false); setIsNoBall(false); setIsBye(false); setIsLegBye(false); setIsWicket(false);
        setProcessing(false);
    };

    const updateOverlay = async (updates: any) => {
        if (!match) return;
        await db.collection('matches').doc(match.id).update({ overlay: { ...match.overlay, ...updates } });
    };

    const setOverlayBackground = async (url: string) => {
        const currentBg = match?.overlay?.backgroundGraphicUrl;
        const newUrl = currentBg === url ? null : url; // Toggle off if clicked same
        await updateOverlay({ backgroundGraphicUrl: newUrl });
    };

    if (loading || !match) return <div className="flex items-center justify-center h-screen"><Loader2 className="w-8 h-8 animate-spin"/></div>;

    const renderPlayerSelector = (type: 'STRIKER' | 'NON_STRIKER' | 'BOWLER', currentId: string | null | undefined) => {
        const isBatsman = type === 'STRIKER' || type === 'NON_STRIKER';
        const team = isBatsman ? battingTeam : bowlingTeam;
        if (!team) return <div className="text-xs text-gray-400 font-bold animate-pulse">Loading Team...</div>;
        if (currentId) {
            const playerStats = isBatsman ? currentInnings?.batsmen[currentId] : currentInnings?.bowlers[currentId];
            const name = playerStats?.name || team.players.find(p => String(p.id) === String(currentId))?.name || 'Unknown';
            const statsDisplay = isBatsman ? (playerStats as BatsmanStats)?.runs || 0 : `${(playerStats as BowlerStats)?.wickets || 0}-${(playerStats as BowlerStats)?.runsConceded || 0}`;
            return <div className={`flex justify-between font-bold text-sm ${type === 'STRIKER' ? 'text-green-400' : type === 'BOWLER' ? 'text-black' : 'text-white'}`}><span>{name}</span><span>{statsDisplay}</span></div>;
        }
        return <select className={`w-full text-xs font-bold p-1 rounded border outline-none uppercase mb-1 ${type === 'BOWLER' ? 'bg-white border-cyan-500 text-black' : 'bg-gray-800 border-gray-600 text-white animate-pulse'}`} onChange={(e) => handlePlayerSelect(type, e.target.value)} value=""><option value="">SELECT {type}</option>{team.players.map(p => <option key={p.id} value={p.id}>{p.name}</option>)}</select>;
    };

    return (
        <div className="min-h-screen bg-gray-50 font-sans text-gray-800 pb-10">
            {showTossModal && (
                <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-[100] p-4 animate-fade-in backdrop-blur-sm">
                    <div className="bg-white rounded-2xl w-full max-w-sm p-6 text-center shadow-2xl border-4 border-yellow-400">
                        <Trophy className="w-16 h-16 mx-auto text-yellow-500 mb-4 animate-bounce" />
                        <h2 className="text-2xl font-black mb-6 uppercase">Match Toss</h2>
                        <div className="mb-4 text-left">
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Toss Winner</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button onClick={() => setTossWinner(match.teamAId)} className={`p-3 rounded border-2 font-bold ${tossWinner === match.teamAId ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 text-gray-600'}`}>{match.teamAName}</button>
                                <button onClick={() => setTossWinner(match.teamBId)} className={`p-3 rounded border-2 font-bold ${tossWinner === match.teamBId ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 text-gray-600'}`}>{match.teamBName}</button>
                            </div>
                        </div>
                        <div className="mb-6 text-left">
                            <label className="block text-xs font-bold text-gray-500 uppercase mb-2">Choice</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button onClick={() => setTossChoice('BAT')} className={`p-3 rounded border-2 font-bold ${tossChoice === 'BAT' ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-600'}`}>BAT</button>
                                <button onClick={() => setTossChoice('BOWL')} className={`p-3 rounded border-2 font-bold ${tossChoice === 'BOWL' ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-600'}`}>BOWL</button>
                            </div>
                        </div>
                        <button onClick={handleToss} disabled={!tossWinner || processing} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-4 rounded-xl shadow-lg transition-all disabled:opacity-50">{processing ? 'Starting...' : 'START MATCH'}</button>
                    </div>
                </div>
            )}

            <div className="bg-white p-4 shadow-sm border-b sticky top-0 z-10">
                <div className="flex justify-between items-center mb-2">
                    <button onClick={() => navigate('/scoring')} className="text-gray-500"><ArrowLeft className="w-5 h-5"/></button>
                    <h2 className="font-black text-gray-700 uppercase">Match Scoreboard</h2>
                    <div className="flex items-center gap-3">
                        <a href={`/#/match-overlay/${matchId}`} target="_blank" className="text-blue-600 font-bold text-xs underline">LIVE OVERLAY</a>
                        <button onClick={handleDeleteMatch} className="text-red-500 hover:text-red-700 p-1"><Trash2 className="w-4 h-4"/></button>
                    </div>
                </div>
                <div className="grid grid-cols-3 gap-2 mt-4 text-white">
                    <div className="bg-gray-900 rounded p-2 flex flex-col justify-center">
                        <div className="mb-1">{renderPlayerSelector('STRIKER', currentInnings?.strikerId)}</div>
                        <div>{renderPlayerSelector('NON_STRIKER', currentInnings?.nonStrikerId)}</div>
                    </div>
                    <div className="bg-blue-500 rounded p-2 text-center flex flex-col justify-center">
                        <span className="text-3xl font-black">{currentInnings?.totalRuns}-{currentInnings?.wickets}</span>
                        <span className="text-xs font-bold uppercase">{currentInnings?.overs} OVR</span>
                    </div>
                    <div className="bg-cyan-500 rounded p-2 flex flex-col justify-between">
                        <div>{renderPlayerSelector('BOWLER', currentInnings?.currentBowlerId)}</div>
                        <div className="flex gap-1 justify-center mt-2">{currentInnings?.recentBalls.slice(-6).map((b,i) => (<div key={i} className="w-3 h-3 rounded-full bg-white flex items-center justify-center text-[8px] text-black font-bold">{b.isWicket ? 'W' : b.runs}</div>))}</div>
                    </div>
                </div>
            </div>

            <div className="max-w-xl mx-auto p-2 space-y-4">

                {/* Media Gallery / Graphics Folder */}
                <div className="bg-white rounded-xl shadow-lg p-4 border border-gray-200">
                    <h3 className="text-sm font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <ImageIcon className="w-4 h-4 text-blue-500"/> Media Gallery (Overlays)
                    </h3>
                    <div className="flex gap-4 overflow-x-auto pb-2 custom-scrollbar">
                        {assets.map(asset => (
                            <button 
                                key={asset.id} 
                                onClick={() => setOverlayBackground(asset.url)}
                                className={`shrink-0 w-24 aspect-video bg-gray-100 rounded-lg border-2 overflow-hidden transition-all relative
                                    ${match.overlay?.backgroundGraphicUrl === asset.url ? 'border-green-500 shadow-lg' : 'border-gray-200 hover:border-blue-400'}
                                `}
                            >
                                <img src={asset.url} className="w-full h-full object-cover" />
                                {match.overlay?.backgroundGraphicUrl === asset.url && (
                                    <div className="absolute inset-0 bg-green-500/20 flex items-center justify-center">
                                        <Check className="text-white w-6 h-6 drop-shadow-md"/>
                                    </div>
                                )}
                            </button>
                        ))}
                        {assets.length === 0 && (
                            <button onClick={() => navigate('/scoring')} className="shrink-0 w-24 aspect-video bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center text-[8px] text-gray-400 font-bold uppercase">
                                <Plus className="w-4 h-4 mb-1"/> Add Graphics
                            </button>
                        )}
                    </div>
                </div>

                <div className="bg-gradient-to-br from-cyan-400 to-purple-600 rounded-xl p-4 shadow-lg text-white">
                    <h3 className="text-center font-bold text-black text-xl mb-4">Controller</h3>
                    <div className="flex justify-between items-center bg-white/20 p-2 rounded mb-4 text-xs font-bold">
                        <button onClick={() => setIsWide(!isWide)} className={`flex items-center gap-2 ${isWide ? 'text-blue-600' : 'text-gray-600'}`}>{isWide ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} Wide</button>
                        <button onClick={() => setIsNoBall(!isNoBall)} className={`flex items-center gap-2 ${isNoBall ? 'text-blue-600' : 'text-gray-600'}`}>{isNoBall ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} NB</button>
                        <button onClick={() => setIsWicket(!isWicket)} className={`flex items-center gap-2 ${isWicket ? 'text-red-600' : 'text-gray-600'}`}>{isWicket ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} Wicket</button>
                    </div>
                    <div className="grid grid-cols-4 gap-4 mb-4">
                        {[0, 1, 2, 3, 4, 5, 6].map(r => (
                            <button key={r} onClick={() => handleScore(r)} className="bg-white/20 hover:bg-white/40 text-black font-black text-xl py-3 rounded-lg border border-black/10 transition-all">{r}</button>
                        ))}
                        <button onClick={() => handleUndo()} className="bg-red-600 text-white font-bold rounded-lg text-xs">UNDO</button>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow p-4 text-center">
                    <h4 className="font-bold text-sm mb-2">Display Controls</h4>
                    <div className="flex flex-wrap gap-2 justify-center">
                        <button onClick={() => updateOverlay({ currentView: 'DEFAULT' })} className="bg-indigo-900 text-white text-[10px] font-bold px-3 py-1 rounded">MINI SCORE</button>
                        <button onClick={() => updateOverlay({ currentView: 'SUMMARY' })} className="bg-blue-600 text-white text-[10px] font-bold px-3 py-1 rounded">MATCH SUMMARY</button>
                        <button onClick={() => updateOverlay({ currentView: 'TARGET' })} className="bg-cyan-500 text-white text-[10px] font-bold px-3 py-1 rounded">TARGET</button>
                        <button onClick={() => toggleTheme()} className="bg-gray-800 text-white text-[10px] font-bold px-3 py-1 rounded uppercase">
                            Theme: {match.overlay?.theme || 'Default'}
                        </button>
                    </div>
                </div>

            </div>
        </div>
    );
};

