                    <div className="flex items-center gap-3">
                        <a href={`/#/match-overlay/${matchId}`} target="_blank" rel="noreferrer" className="text-blue-600 font-bold text-xs underline">LIVE OVERLAY</a>
                        <button onClick={handleDeleteMatch} className="text-red-500 hover:text-red-700 p-1"><Trash2 className="w-4 h-4"/></button>
                    </div>
                </div>

                {/* Inline Toss Section instead of popup modal */}
                {(match.status === 'SCHEDULED' || match.status === 'TOSS') && (
                    <div className="bg-white rounded-xl shadow-lg p-6 text-center border-4 border-yellow-400 mb-4 animate-fade-in">
                        <Trophy className="w-12 h-12 mx-auto text-yellow-500 mb-3" />
                        <h2 className="text-xl font-black mb-4 uppercase">Match Toss</h2>
                        <div className="mb-4 text-left">
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Toss Winner</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button onClick={() => setTossWinner(match.teamAId)} className={`p-2 rounded border-2 font-bold text-sm ${tossWinner === match.teamAId ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 text-gray-600'}`}>{match.teamAName}</button>
                                <button onClick={() => setTossWinner(match.teamBId)} className={`p-2 rounded border-2 font-bold text-sm ${tossWinner === match.teamBId ? 'border-green-500 bg-green-50 text-green-700' : 'border-gray-200 text-gray-600'}`}>{match.teamBName}</button>
                            </div>
                        </div>
                        <div className="mb-6 text-left">
                            <label className="block text-[10px] font-bold text-gray-500 uppercase mb-2">Choice</label>
                            <div className="grid grid-cols-2 gap-2">
                                <button onClick={() => setTossChoice('BAT')} className={`p-2 rounded border-2 font-bold text-sm ${tossChoice === 'BAT' ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-600'}`}>BAT</button>
                                <button onClick={() => setTossChoice('BOWL')} className={`p-2 rounded border-2 font-bold text-sm ${tossChoice === 'BOWL' ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-600'}`}>BOWL</button>
                            </div>
                        </div>
                        <button onClick={handleToss} disabled={!tossWinner || processing} className="w-full bg-green-600 hover:bg-green-700 text-white font-bold py-3 rounded-lg shadow-md transition-all disabled:opacity-50 flex items-center justify-center">
                            {processing ? <Loader2 className="animate-spin w-4 h-4 mr-2"/> : 'START MATCH'}
                        </button>
                    </div>
                )}

                <div className="grid grid-cols-3 gap-2 mt-4 text-white">
                    <div className="bg-gray-900 rounded p-2 flex flex-col justify-center">
                        <div className="mb-1">{renderPlayerSelector('STRIKER', currentInnings?.strikerId)}</div>
                        <div>{renderPlayerSelector('NON_STRIKER', currentInnings?.nonStrikerId)}</div>
                    </div>
                    <div className="bg-blue-500 rounded p-2 text-center flex flex-col justify-center">
                        <span className="text-3xl font-black">{currentInnings?.totalRuns}-{currentInnings?.wickets}</span>
                        <span className="text-xs font-bold uppercase">{currentInnings?.overs} OVR</span>
                    </div>
                    <div className="bg-cyan-500 rounded p-2 flex flex-col justify-between">
                        <div>{renderPlayerSelector('BOWLER', currentInnings?.currentBowlerId)}</div>
                        <div className="flex gap-1 justify-center mt-2">{currentInnings?.recentBalls.slice(-6).map((b,i) => (<div key={i} className="w-3 h-3 rounded-full bg-white flex items-center justify-center text-[8px] text-black font-bold">{b.isWicket ? 'W' : b.runs}</div>))}</div>
                    </div>
                </div>
            </div>

            <div className="max-w-xl mx-auto p-2 space-y-4">

                <div className="bg-white rounded-xl shadow-lg p-4 border border-gray-200">
                    <h3 className="text-sm font-bold text-gray-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                        <ImageIcon className="w-4 h-4 text-blue-500"/> Media Gallery (Overlays)
                    </h3>
                    <div className="flex gap-4 overflow-x-auto pb-2 custom-scrollbar">
                        {assets.map(asset => (
                            <button 
                                key={asset.id} 
                                onClick={() => setOverlayBackground(asset.url)}
                                className={`shrink-0 w-24 aspect-video bg-gray-100 rounded-lg border-2 overflow-hidden transition-all relative
                                    ${match.overlay?.backgroundGraphicUrl === asset.url ? 'border-green-500 shadow-lg' : 'border-gray-200 hover:border-blue-400'}
                                `}
                            >
                                <img src={asset.url} className="w-full h-full object-cover" alt={asset.name} />
                                {match.overlay?.backgroundGraphicUrl === asset.url && (
                                    <div className="absolute inset-0 bg-green-500/20 flex items-center justify-center">
                                        <Check className="text-white w-6 h-6 drop-shadow-md"/>
                                    </div>
                                )}
                            </button>
                        ))}
                        {assets.length === 0 && (
                            <button onClick={() => navigate('/scoring')} className="shrink-0 w-24 aspect-video bg-gray-50 border-2 border-dashed border-gray-300 rounded-lg flex flex-col items-center justify-center text-[8px] text-gray-400 font-bold uppercase">
                                <Plus className="w-4 h-4 mb-1"/> Add Graphics
                            </button>
                        )}
                    </div>
                </div>

                <div className="bg-gradient-to-br from-cyan-400 to-purple-600 rounded-xl p-4 shadow-lg text-white">
                    <h3 className="text-center font-bold text-black text-xl mb-4">Controller</h3>
                    <div className="flex justify-between items-center bg-white/20 p-2 rounded mb-4 text-xs font-bold">
                        <button onClick={() => setIsWide(!isWide)} className={`flex items-center gap-2 ${isWide ? 'text-blue-600' : 'text-gray-600'}`}>{isWide ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} Wide</button>
                        <button onClick={() => setIsNoBall(!isNoBall)} className={`flex items-center gap-2 ${isNoBall ? 'text-blue-600' : 'text-gray-600'}`}>{isNoBall ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} NB</button>
                        <button onClick={() => setIsWicket(!isWicket)} className={`flex items-center gap-2 ${isWicket ? 'text-red-600' : 'text-gray-600'}`}>{isWicket ? <CheckSquare className="w-5 h-5"/> : <Square className="w-5 h-5"/>} Wicket</button>
                    </div>
                    <div className="grid grid-cols-4 gap-4 mb-4">
                        {[0, 1, 2, 3, 4, 5, 6].map(r => (
                            <button key={r} onClick={() => handleScore(r)} className="bg-white/20 hover:bg-white/40 text-black font-black text-xl py-3 rounded-lg border border-black/10 transition-all">{r}</button>
                        ))}
                        <button onClick={() => handleUndo()} className="bg-red-600 text-white font-bold rounded-lg text-xs">UNDO</button>
                    </div>
                </div>

                <div className="bg-white rounded-xl shadow p-4 text-center">
                    <h4 className="font-bold text-sm mb-2">Display Controls</h4>
                    <div className="flex flex-wrap gap-2 justify-center">
                        <button onClick={() => updateOverlay({ currentView: 'DEFAULT' })} className="bg-indigo-900 text-white text-[10px] font-bold px-3 py-1 rounded">MINI SCORE</button>
                        <button onClick={() => updateOverlay({ currentView: 'SUMMARY' })} className="bg-blue-600 text-white text-[10px] font-bold px-3 py-1 rounded">MATCH SUMMARY</button>
                        <button onClick={() => updateOverlay({ currentView: 'TARGET' })} className="bg-cyan-500 text-white text-[10px] font-bold px-3 py-1 rounded">TARGET</button>
                        <button onClick={() => toggleTheme()} className="bg-gray-800 text-white text-[10px] font-bold px-3 py-1 rounded uppercase">
                            Theme: {match.overlay?.theme || 'Default'}
                        </button>
                    </div>
                </div>

            </div>
        </div>
    );
};

